// 出身原有特质注册到状态效果；displayBonus 只显示，不写入人物变量。
function applyEarthseaOriginAssetRegistration(statData, originName) {
    const origin = earthseaOrigins.find(entry => entry.name === originName);
    if (!statData || !origin?.initialAssets?.length) return;
    statData.核心资产 ??= {};
    for (const { name, value } of origin.initialAssets) {
        if (!statData.核心资产[name]) statData.核心资产[name] = structuredClone(value);
    }
}

function applyEarthseaOriginMvuBonuses(person, originName, statData) {
    if (!person || !originName) return;
    const origin = earthseaOrigins.find(entry => entry.name === originName);
    if (!origin) return;
    person.熟练度 ??= {};
    person.熟练度.战斗 ??= {};
    person.熟练度.生活 ??= {};
    person.资源技能 ??= {};
    for (const entry of origin.initialProficiencies || []) {
        const group = person.熟练度[entry.category];
        if (!group) continue;
        const tiers = {
            学徒: { order: 0, threshold: 25, bonus: 1 },
            熟手: { order: 1, threshold: 50, bonus: 3 },
            专家: { order: 2, threshold: 100, bonus: 4 },
            大师: { order: 3, threshold: 200, bonus: 6 },
            传奇: { order: 4, threshold: 0, bonus: 8 } // 传奇为满阶
        };
        const tier = entry.tier || '熟手';
        const target = tiers[tier];
        if (!target) continue;
        const current = group[entry.name];
        // 既有更高阶位不降级；低阶位升级时沿用其原有进度（不超过当前阶位阈值）。
        if (!current || (tiers[current.阶位]?.order ?? -1) < target.order) {
            const { threshold, bonus } = target;
            const progress = current ? Math.min(Math.max(0, Number(current.进度) || 0), threshold - 1) : 0;
            group[entry.name] = { 阶位: tier, 进度: progress, 升阶阈值: threshold, 效果: `${entry.name}相关检定+${bonus}` };
        }
    }
    for (const { name, ...skill } of origin.initialResourceSkills || []) {
        if (!person.资源技能[name]) person.资源技能[name] = structuredClone(skill);
    }
    applyEarthseaOriginAssetRegistration(statData, originName);
}
if (typeof window !== 'undefined') {
    window.earthseaOrigins = earthseaOrigins;
    window.applyEarthseaOriginMvuBonuses = applyEarthseaOriginMvuBonuses;
    window.applyEarthseaOriginAssetRegistration = applyEarthseaOriginAssetRegistration;
}
