            filter: grayscale(1);
            cursor: not-allowed;
        }

        .card-check {
            position: absolute;
            top: 15px;
            right: 15px;
            width: 24px;
            height: 24px;
            border-radius: 50%;
            border: 2px solid #dfe6e9;
            background: white;
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-size: 14px;
        }

        .selection-card.selected .card-check {
