        .card-header {
            display: flex;
            align-items: center;
            gap: 15px;
            margin-bottom: 12px;
        }

        .card-icon {
            width: 48px;
            height: 48px;
            background: #f1f2f6;
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 24px;
            color: var(--secondary);
        }

        .selection-card.selected .card-icon {
            background: var(--accent);
            color: white;
        }

        .card-title {
            font-size: 1.1rem;
            font-weight: 700;
            margin-bottom: 4px;
        }

        .card-subtitle {
            font-size: 0.75rem;
            color: var(--accent);
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        .card-desc {
            font-size: 0.85rem;
            color: var(--secondary);
            line-height: 1.5;
            margin-bottom: 15px;
        }

        .worldview-card .worldview-desc {
            margin-top: 4px;
            font-size: 0.9rem;
            line-height: 1.82;
            letter-spacing: 0.01em;
            color: #51626a;
            text-indent: 2em;
            white-space: pre-line;
            text-wrap: pretty;
        }

        .worldview-card.selected .worldview-desc {
