        /* Stats Radar / Summary */
        .summary-panel {
            background: white;
            border-radius: var(--radius-lg);
            padding: 40px;
            text-align: center;
            max-width: 600px;
            margin: 0 auto;
            position: relative;
        }

        .summary-avatar {
            width: 120px;
            height: 120px;
            border-radius: 50%;
            background: #dfe6e9;
            margin: 0 auto 20px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 3rem;
            color: #b2bec3;
            border: 4px solid white;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
        }

        .summary-name {
            font-size: 2rem;
            font-weight: 700;
            margin-bottom: 5px;
            font-family: var(--font-main);
        }

        .summary-meta {
            color: var(--secondary);
            font-size: 0.9rem;
            margin-bottom: 30px;
            letter-spacing: 1px;
        }

        .summary-setting-card {
            text-align: left;
            background: #f8f9fa;
            padding: 18px 20px;
            border-radius: 12px;
            margin-top: 22px;
            border: 1px solid rgba(0, 0, 0, 0.06);
        }

        .summary-setting-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 12px;
            margin-bottom: 14px;
            flex-wrap: wrap;
        }

        .summary-setting-title {
            display: flex;
            align-items: center;
            gap: 8px;
            margin: 0;
            color: var(--primary);
            font-size: 0.98rem;
            font-weight: 700;
        }

        .summary-setting-title i {
            color: var(--accent);
            font-size: 1rem;
        }

        .summary-setting-current {
            color: var(--secondary);
            font-size: 0.78rem;
            font-weight: 700;
        }

        .summary-setting-list {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .summary-setting-row {
            display: block;
        }

        .summary-setting-row+.summary-setting-row {
            border-top: 1px solid rgba(0, 0, 0, 0.06);
            padding-top: 12px;
        }

        .summary-setting-label {
            color: var(--primary);
            font-size: 0.82rem;
            font-weight: 700;
        }

        .summary-setting-desc {
            margin: 6px 0 0;
            color: var(--secondary);
            font-size: 0.76rem;
            line-height: 1.55;
        }

        .summary-setting-segment {
            display: grid;
            gap: 8px;
            margin-top: 10px;
        }

        .summary-setting-segment.two {
            grid-template-columns: repeat(2, minmax(0, 1fr));
        }

        .summary-setting-segment.auto {
            grid-template-columns: repeat(auto-fit, minmax(78px, 1fr));
        }

        .summary-setting-btn {
            height: 40px;
            border-radius: 8px;
            border: 1px solid rgba(45, 106, 79, 0.18);
            background: #fff;
            color: var(--primary);
