            font-weight: 700;
            font-size: 0.86rem;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 7px;
            transition: all 0.18s ease;
        }

        .summary-setting-btn:hover:not(:disabled) {
            border-color: var(--accent);
            color: var(--accent);
            background: rgba(45, 106, 79, 0.04);
        }

        .summary-setting-btn.selected {
            border-color: var(--accent);
            background: var(--accent);
            color: #fff;
            box-shadow: 0 6px 14px rgba(45, 106, 79, 0.16);
        }

        .summary-setting-btn:disabled {
            cursor: default;
        }

        /* 构筑共鸣评议 */
        .build-review-page { max-width: 1120px; margin: 0 auto; }
        .build-review-intro { display:flex; align-items:center; gap:10px; padding:13px 16px; border:1px solid rgba(195,151,77,.24); border-radius:12px; color:#6f5426; background:linear-gradient(135deg,#fbf5e8 0%,#f4ead2 100%); font-size:.86rem; line-height:1.6; box-shadow:0 8px 20px rgba(139,107,60,.08); }
        .build-review-intro i { flex:none; color:#b4812e; font-size:1.05rem; }
        .build-review-intro strong { color:#5e451f; }
        .build-review-grid { display:grid; grid-template-columns:minmax(0,.88fr) minmax(380px,1.12fr); gap:16px; margin-top:16px; align-items:start; }
        .build-review-card,.build-review-result-card { background:white; border:1px solid rgba(0,0,0,.06); border-radius:16px; box-shadow:var(--shadow-card); }
        .build-review-card { margin-top:0; padding:20px; }
        .build-review-card-head { display:flex; justify-content:space-between; align-items:flex-start; gap:12px; }
        .build-review-card-head h3 { display:flex; align-items:center; gap:7px; margin:0; font-size:.95rem; }
        .build-review-card-head h3 i,.build-review-section h4 i { color:var(--accent); }
        .build-review-card-head p { margin:6px 0 0; color:var(--secondary); font-size:.82rem; line-height:1.55; }
        .build-review-summary-score { color:var(--accent); font-size:1.5rem; font-weight:800; line-height:1; }
        .build-review-summary-score small { font-size:.72rem; color:var(--secondary); }
        .build-review-tags { display:flex; flex-wrap:wrap; gap:7px; margin:14px 0; }
        .build-review-tags span { display:inline-flex; align-items:center; gap:5px; padding:7px 10px; border-radius:999px; background:#edf4f0; color:#315c4c; font-size:.76rem; font-weight:700; }
        .build-review-tags span.custom { background:#f6ead1; color:#896426; }
        .build-review-note { display:flex; gap:8px; padding:11px 12px; border-radius:10px; background:#f7f5ee; color:var(--secondary); font-size:.78rem; line-height:1.65; }
        .build-review-note i { color:var(--gold-dim); margin-top:2px; }
        .build-review-mode { margin:13px 0 10px; display:flex; flex-wrap:wrap; align-items:center; gap:10px; padding:9px 12px; background:rgba(45,106,79,.04); border-radius:8px; border:1px solid rgba(45,106,79,.1); }
        .build-review-mode label { display:flex; align-items:center; gap:8px; flex:none; cursor:pointer; color:var(--primary); font-size:.8rem; user-select:none; }
        .build-review-mode-copy { color:var(--secondary); font-size:.75rem; line-height:1.45; }
        .build-review-mode-copy.limit { color:#e67e22; }
        .build-review-action { width:100%; min-height:46px; border:0; border-radius:10px; color:white; background:linear-gradient(135deg,#c3974d,#a87731); font-size:.88rem; font-weight:800; cursor:pointer; box-shadow:0 8px 18px rgba(168,119,49,.18); }
        .build-review-action:disabled { opacity:.55; cursor:not-allowed; box-shadow:none; }
        .build-review-spin { display:inline-block; animation:buildReviewSpin 1s linear infinite; }
        @keyframes buildReviewSpin { to { transform:rotate(360deg); } }
        .build-review-inline-warning { margin-top:9px; color:#a2554d; font-size:.78rem; line-height:1.5; }
        .build-review-inline-warning.stale { color:#a36b2e; }
        .build-review-result-card { min-height:0; padding:18px; }
        .build-review-result-card.empty-state { padding:0; border:0; background:transparent; box-shadow:none; }
        .build-review-score-block { display:flex; align-items:center; gap:15px; padding:16px; border-radius:14px; color:white; background:linear-gradient(135deg,#6f5c3f,#8b6b3c); }
        .build-review-score-block.passed { background:linear-gradient(135deg,#234d3f,#3b725d); }
        .build-review-score-ring { --review-score:0; width:92px; height:92px; flex:none; border-radius:50%; display:grid; place-items:center; background:conic-gradient(#ead08f calc(var(--review-score)*1%),rgba(255,255,255,.16) 0); position:relative; }
        .build-review-score-ring::before { content:''; position:absolute; inset:7px; border-radius:50%; background:#315d4d; }
        .build-review-score-block:not(.passed) .build-review-score-ring::before { background:#765e3c; }
        .build-review-score-ring>div { position:relative; text-align:center; }
        .build-review-score-ring strong { display:block; font-size:1.75rem; line-height:1; }
        .build-review-score-ring small { font-size:.7rem; opacity:.7; }
        .build-review-verdict span { color:#ead29d; font-size:.72rem; font-weight:800; letter-spacing:.12em; }
        .build-review-verdict h3 { margin:4px 0 5px; font-size:1.25rem; }
        .build-review-verdict p { margin:0; color:rgba(255,255,255,.78); font-size:.8rem; line-height:1.55; }
        .build-review-reward { display:flex; align-items:center; gap:10px; margin:12px 0; padding:11px 12px; border-radius:11px; background:#f2f3f2; color:var(--secondary); }
        .build-review-reward.unlocked { background:#edf5f0; color:#315c4c; }
        .build-review-reward>i { font-size:1.2rem; color:var(--gold-dim); }
        .build-review-reward strong,.build-review-reward span { display:block; }
        .build-review-reward strong { font-size:.82rem; }
        .build-review-reward span { margin-top:3px; font-size:.74rem; line-height:1.5; }
        .build-review-allocate-btn { width:100%; margin:-3px 0 12px; padding:9px; border:1px solid rgba(45,106,79,.2); border-radius:9px; color:var(--accent); background:#f7fbf8; font-size:.78rem; font-weight:700; cursor:pointer; }
        .build-review-dimensions { display:grid; gap:8px; }
        .build-review-dimension { padding:9px 10px; border:1px solid rgba(0,0,0,.06); border-radius:9px; }
        .build-review-dimension>div:first-child { display:flex; justify-content:space-between; font-size:.78rem; font-weight:700; }
        .build-review-dimension>div:first-child strong { color:var(--accent); }
        .build-review-bar { height:5px; margin:6px 0; border-radius:999px; background:#e6ebe7; overflow:hidden; }
        .build-review-bar span { display:block; height:100%; border-radius:inherit; background:linear-gradient(90deg,var(--accent),#72a48b); }
        .build-review-dimension p { margin:0; color:var(--secondary); font-size:.73rem; line-height:1.5; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden; }
        .build-review-penalties { margin-top:12px; padding:11px 12px; border:1px solid rgba(176,82,64,.18); border-radius:10px; background:#fff5f1; }
        .build-review-penalty-head { display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:8px; color:#914b3d; font-size:.8rem; font-weight:800; }
        .build-review-penalty-list { display:grid; gap:7px; }
        .build-review-penalty-row { display:grid; grid-template-columns:auto auto minmax(0,1fr); align-items:start; gap:7px; color:var(--secondary); font-size:.72rem; line-height:1.5; }
        .build-review-penalty-row strong { color:#a04f3e; white-space:nowrap; }
        .build-review-penalty-row b { color:#b33d2e; white-space:nowrap; }
        .build-review-section { margin-top:14px; }
        .build-review-section h4 { display:flex; align-items:center; gap:6px; margin:0 0 7px; font-size:.84rem; }
        .build-review-comment { margin:0; padding:11px 12px; border-left:3px solid var(--gold-dim); border-radius:8px; background:#f8f5ed; color:var(--secondary); white-space:pre-wrap; font-size:.76rem; line-height:1.65; }
        .build-review-chip-list { display:flex; flex-wrap:wrap; gap:6px; }
        .build-review-chip-list span { padding:6px 9px; border-radius:999px; background:#e8f2ec; color:#315c4c; font-size:.72rem; }
        .build-review-chip-list.warning span { background:#f6e3d7; color:#8a4e35; }
        .build-review-advice { display:grid; gap:6px; margin:0; padding:0; list-style:none; }
        .build-review-advice li { display:grid; grid-template-columns:20px 1fr; gap:8px; padding:9px; border:1px solid rgba(0,0,0,.06); border-radius:8px; color:var(--secondary); font-size:.74rem; line-height:1.55; }
        .build-review-advice b { width:19px; height:19px; display:grid; place-items:center; border-radius:50%; background:#f4e8ca; color:#8d672a; }
        .build-review-tools { display:grid; grid-template-columns:minmax(0,1fr) auto; gap:8px; margin-top:14px; }
        .build-review-copy-btn,.build-review-back-btn { min-height:40px; border-radius:9px; font-size:.78rem; font-weight:700; cursor:pointer; transition:all .18s ease; }
        .build-review-copy-btn { border:0; color:#fff; background:var(--accent); box-shadow:0 6px 14px rgba(45,106,79,.16); }
        .build-review-copy-btn:hover { filter:brightness(1.05); transform:translateY(-1px); }
        .build-review-copy-btn.copied { background:#3f8062; }
        .build-review-back-btn { padding:0 13px; border:1px solid rgba(45,106,79,.2); color:var(--accent); background:#f7fbf8; }
        .build-review-back-btn:hover { border-color:var(--accent); background:#edf5f0; }
        .build-review-empty { display:flex; align-items:center; gap:9px; padding:13px 15px; border:1px solid rgba(45,106,79,.14); border-radius:11px; color:#416653; background:#edf5f0; font-size:.8rem; line-height:1.55; }
        .build-review-empty i { flex:none; color:var(--accent); font-size:1rem; }
        .build-review-focus { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:6px; }
        .build-review-focus>div { padding:8px; border-radius:8px; background:#eef4f0; border:1px solid rgba(45,106,79,.1); }
        .build-review-focus strong,.build-review-focus span { display:block; }
        .build-review-focus strong { color:var(--accent); font-size:.73rem; margin-bottom:4px; }
        .build-review-focus span { color:var(--secondary); font-size:.7rem; line-height:1.5; }
        @media (max-width: 900px) { .build-review-grid { grid-template-columns:1fr; } .build-review-focus { grid-template-columns:1fr; } }
        @media (max-width: 520px) { .build-review-tools { grid-template-columns:1fr; } .build-review-back-btn { min-height:40px; } }
        .stat-grid-mini {
            display: flex;
            justify-content: center;
            gap: 15px;
            margin-bottom: 30px;
        }

        .mini-stat {
            background: #f8f9fa;
            padding: 10px 20px;
            border-radius: 10px;
        }

        .mini-stat-label {
            font-size: 0.7rem;
            color: var(--secondary);
            text-transform: uppercase;
            font-weight: 700;
        }

        .mini-stat-val {
            font-family: var(--font-num);
            font-size: 1.2rem;
            font-weight: 700;
            color: var(--primary);
        }

        /* Scrollbar */
        ::-webkit-scrollbar {
            width: 6px;
            height: 6px;
        }

        ::-webkit-scrollbar-track {
            background: transparent;
        }

        ::-webkit-scrollbar-thumb {
            background: rgba(0, 0, 0, 0.1);
            border-radius: 3px;
        }

        ::-webkit-scrollbar-thumb:hover {
            background: rgba(0, 0, 0, 0.2);
        }

        /* 种族特性区域 */
        .race-buffs-container {
            overflow: visible !important;
            position: relative;
        }

        .race-buffs-list {
            display: flex;
            flex-wrap: wrap;
            gap: 6px;
            align-items: center;
        }

        .race-buff-selected { box-shadow: 0 0 0 2px rgba(45, 106, 79, 0.22); }
        .race-buff-detail {
            margin-top: 10px;
            padding: 12px 14px;
            border-left: 3px solid var(--accent);
            border-radius: 4px 8px 8px 4px;
            background: rgba(45, 106, 79, 0.055);
            color: var(--primary);
            font-size: 0.82rem;
            line-height: 1.65;
            white-space: pre-wrap;
        }
        .race-buff-detail.negative { border-left-color: var(--danger); background: rgba(231, 76, 60, 0.055); }
        .race-buff-detail strong { display: block; margin-bottom: 4px; }
        .race-buff-detail p { margin: 0; }
        .race-buffs-list .buff-tag { position: relative; z-index: 1; cursor: pointer; }
        .race-buffs-list .buff-tag:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

        /* Buff 标签样式 */
        .buff-tag {
            display: inline-flex;
            align-items: center;
            gap: 4px;
            padding: 4px 10px;
            border-radius: 6px;
            font-size: 0.8rem;
            line-height: 1.2;
            cursor: help;
            transition: all 0.2s;
        }

        .custom-trait-tag {
            cursor: pointer;
            min-height: 34px;
            padding: 6px 12px;
            justify-content: center;
            flex: 1 1 170px;
        }

        .custom-trait-tag i {
            font-size: 0.9rem;
            flex-shrink: 0;
        }

        .race-head-meta {
            display: flex;
            align-items: center;
            gap: 6px;
            flex-wrap: wrap;
            margin-top: 8px;
        }

        .custom-race-name-input {
            width: 100%;
            padding: 6px 10px;
            border: 1px solid #e0e0e0;
            border-radius: 6px;
            font-size: 1.1rem;
            font-weight: 700;
            font-family: var(--font-main);
            line-height: 1.25;
            outline: none;
