        .amber-camp-tab-hint {
            font-size: 0.66rem;
            color: var(--secondary);
            line-height: 1.35;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .amber-camp-panel {
            background: linear-gradient(180deg, rgba(45, 106, 79, 0.05), rgba(45, 106, 79, 0.02));
            border: 1px solid rgba(45, 106, 79, 0.12);
            border-radius: 12px;
            padding: 10px;
            min-width: 0;
