            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 8px;
            margin-bottom: 8px;
            padding-bottom: 8px;
            border-bottom: 1px solid rgba(45, 106, 79, 0.1);
        }

        .amber-camp-races {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(148px, 1fr));
            gap: 8px;
        }

        .amber-race-list-item {
            margin-bottom: 0;
            min-height: 54px;
            display: flex;
            align-items: center;
            padding: 10px 12px !important;
            border-radius: 10px;
            border-width: 1px;
            background: rgba(255, 255, 255, 0.72);
