        .amber-race-list-item:hover {
            transform: translateY(-1px);
            background: rgba(45, 106, 79, 0.07);
        }

        .amber-race-list-item.selected {
            background: rgba(45, 106, 79, 0.1);
            box-shadow: inset 0 0 0 1px rgba(45, 106, 79, 0.18);
        }

        .amber-race-name {
            font-weight: 600;
            font-size: 0.87rem;
