            text-overflow: ellipsis;
            white-space: nowrap;
        }

        .amber-race-custom {
            margin-top: 10px;
            padding-top: 10px;
            border-top: 1px solid rgba(45, 106, 79, 0.1);
        }

        @media (max-width: 640px) {
