        /* ========== 出身背景选择 - 双栏布局 ========== */
        .identity-selection-panel {
            margin-bottom: 35px;
        }

        .identity-layout {
            display: grid;
            grid-template-columns: 220px 1fr;
            gap: 20px;
            min-height: 320px;
