            min-width: 0;
        }

        .identity-name {
            font-weight: 600;
            font-size: 0.95rem;
            color: var(--primary);
            margin-bottom: 2px;
            white-space: nowrap;
        }

        .identity-item.active .identity-name {
            color: white;
        }

        .identity-cost {
            font-family: var(--font-num);
            font-size: 0.8rem;
            font-weight: 600;
            color: var(--danger);
