            background: rgba(45, 106, 79, 0.06);
            color: #2d6a4f;
        }

        .skill-gen-btn-revise:not(:disabled):hover {
            border-color: rgba(45, 106, 79, 0.48);
            background: rgba(45, 106, 79, 0.11);
            box-shadow: 0 5px 14px rgba(45, 106, 79, 0.10);
        }

        .skill-gen-btn-regenerate {
            border: 1px solid transparent;
            background: linear-gradient(135deg, #2d6a4f, #40916c);
            color: #fff;
            box-shadow: 0 4px 10px rgba(45, 106, 79, 0.16);
        }

        .skill-gen-btn-regenerate:not(:disabled):hover {
            box-shadow: 0 6px 15px rgba(45, 106, 79, 0.23);
        }

        @media (max-width: 720px) {
            .skill-gen-controls.has-revision {
                grid-template-columns: 1fr 1fr;
            }

            .skill-gen-controls.has-revision .skill-gen-input {
                grid-column: 1 / -1;
            }

            .skill-gen-btn {
                width: 100%;
                min-width: 0;
            }
        }
</style>
<style>html,body{height:auto!important;min-height:0!important}</style>
</head>

<body>

    <div id="app">
        <!-- HEADER -->
        <header class="app-header">
            <div class="app-title">
                <i class="ri-quill-pen-line"></i>
                <span>创世回廊</span>
            </div>
            <div
                style="display:flex; align-items:center; gap:15px; margin-left:auto; flex-wrap:wrap; justify-content:flex-end;">
                <button v-if="presetMode === null && presetSubPage" @click="presetSubPage = false" class="preset-btn">
                    <i class="ri-arrow-left-line"></i> 返回
                </button>
                <div style="display:flex; align-items:center; gap:15px;" v-show="presetMode !== null">
                    <!-- 预设管理按钮 -->
                    <button @click="showPresetModal = true" class="preset-btn">
                        <i class="ri-bookmark-line"></i> 管理预设
                    </button>
                    <div class="points-display">
                        <div class="point-group">
                            <span class="point-label">AP</span>
                            <span :class="['point-val', {negative: remainingAP < 0}]">{{ remainingAP }}</span>
                        </div>
                        <div style="width:1px; height:20px; background:#eee;"></div>
                        <div class="point-group">
                            <span class="point-label">RP</span>
                            <span :class="['point-val', {highlight: remainingRP >= 0, negative: remainingRP < 0}]">{{
                                remainingRP }}</span>
                        </div>
                    </div>
                </div>
            </div>
        </header>

        <!-- 预设管理弹窗 -->
        <div v-if="showPresetModal" class="preset-modal-overlay" @click.self="showPresetModal = false">
            <div class="preset-modal">
                <div class="preset-modal-header">
                    <h3><i class="ri-bookmark-3-line"></i> 预设管理</h3>
                    <button class="preset-modal-close" @click="showPresetModal = false"><i
                            class="ri-close-line"></i></button>
                </div>
                <div class="preset-modal-body">
                    <!-- 保存新预设 -->
                    <div class="preset-save-section">
                        <input v-model="newPresetName" type="text" placeholder="输入预设名称..." class="preset-input">
                        <button @click="savePreset" class="preset-save-btn" :disabled="!newPresetName.trim()">
                            <i class="ri-save-line"></i> 保存当前配置
                        </button>
                        <button @click="importPresetJson" class="preset-save-btn"
                            style="background: linear-gradient(135deg, #d4a853 0%, #b8860b 100%); box-shadow: 0 4px 12px rgba(184,134,11,0.3);">
                            <i class="ri-upload-2-line"></i> 导入
                        </button>
                    </div>
                    <!-- 预设列表 -->
                    <div class="preset-list">
                        <div v-if="presetList.length === 0" class="preset-empty">
                            <i class="ri-inbox-line"></i>
                            <p>暂无保存的预设</p>
                        </div>
                        <div v-for="preset in presetList" :key="preset.id" class="preset-item">
                            <div class="preset-item-info">
                                <div class="preset-item-name">{{ preset.name }}</div>
                                <div class="preset-item-meta">
                                    {{ getPresetRaceDisplay(preset.data) }} · {{ getPresetClassDisplay(preset.data) }} ·
                                    {{
                                    formatPresetDate(preset.timestamp) }}
                                </div>
                            </div>
                            <div class="preset-item-actions">
                                <button @click="loadPreset(preset)" class="preset-action-btn load" title="加载">
                                    <i class="ri-download-line"></i>
                                </button>
                                <button @click="exportPresetJson(preset)" class="preset-action-btn export"
                                    title="导出JSON">
                                    <i class="ri-file-download-line"></i>
                                </button>
                                <button @click="deletePreset(preset.id)" class="preset-action-btn delete" title="删除">
                                    <i class="ri-delete-bin-line"></i>
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <!-- STEPPER -->
        <div class="stepper" v-show="presetMode !== null">
            <div v-for="(step, index) in steps" :key="index"
                :class="['step-item', {active: currentStep === index + 1, passed: currentStep > index + 1}]"
                @click="goToStep(index + 1)">
                <span class="step-label">
                    <span class="step-index">0{{ index + 1 }}</span>
                    <span class="step-title">{{ step.title }}</span>
                </span>
            </div>
        </div>

        <!-- MAIN CONTENT -->
        <main class="main-content">
            <transition name="fade" mode="out-in">
                <div :key="presetMode === null ? (presetSubPage ? 'workshop' : 'select') : currentStep">

                    <!-- STEP 0: PRESET CHARACTER SELECT -->
                    <template v-if="presetMode === null">
                        <!-- 子页面：预设角色列表（队友卡片风格） -->
                        <div v-if="presetSubPage">
                            <div class="workshop-embed-page">
                                <div v-if="false" class="workshop-embed-header">
                                    <div class="workshop-embed-copy">
                                        <h2>创意工坊</h2>
                                        <p>在这里浏览角色、拓展和世界书 MOD。嵌入在酒馆时，创意工坊会通过当前开局页桥接世界书 API。</p>
                                    </div>
                                    <div class="workshop-embed-actions">
                                        <button class="workshop-embed-btn back" @click="presetSubPage = false">
                                            <i class="ri-arrow-left-line"></i> 返回
                                        </button>
                                        <button class="workshop-embed-btn open" @click="openCreativeWorkshopInNewTab">
                                            <i class="ri-external-link-line"></i> 新窗口打开
                                        </button>
                                    </div>
                                </div>
                                <div class="workshop-embed-shell">
                                    <div v-if="workshopEmbedLoading" class="workshop-embed-loading">
                                        <div class="workshop-embed-loading-card">
                                            <i class="ri-loader-4-line"></i>
                                            <span>创意工坊加载中...</span>
                                            <small>首次打开可能需要几秒钟</small>
                                        </div>
                                    </div>
                                    <iframe class="workshop-embed-frame" :src="creativeWorkshopEmbedUrl" title="创意工坊"
                                        loading="lazy" referrerpolicy="strict-origin-when-cross-origin"
                                        @load="handleCreativeWorkshopFrameLoad" allow="clipboard-read; clipboard-write">
                                    </iframe>
                                </div>
                            </div>
                            <div v-if="false">
                                <div style="display:flex; align-items:center; gap:12px; margin-bottom:20px;">
                                    <span @click="presetSubPage = false"
                                        style="cursor:pointer; color:var(--accent); font-weight:600; display:flex; align-items:center; gap:4px;">
                                        <i class="ri-arrow-left-line"></i> 返回
                                    </span>
                                    <h2 style="margin:0; font-family:var(--font-main);">选择预设角色</h2>
                                </div>
                                <div class="teammate-grid">
                                    <!-- 癌骑士 -->
                                    <div class="teammate-card"
                                        @click="selectedPresetChar = presetCharacters.cancer_knight"
                                        style="cursor:pointer;">
                                        <div class="teammate-avatar" style="position:relative;">
                                            <img src="https://dnf.rown.dpdns.org/%E5%B0%81%E9%9D%A2/%E7%99%8C%E9%AA%91%E5%A3%AB.webp"
                                                alt="癌骑士">
                                            <div class="art-blur-mask" :class="{revealed: cancerKnightRevealed}">
                                                <span class="blur-warn-text">⚠ 立绘略猎奇</span>
                                            </div>
                                            <button class="reveal-eye-btn" v-show="!cancerKnightRevealed"
                                                @click.stop="cancerKnightRevealed = true" title="查看原图">
                                                <i class="ri-eye-line"></i>
                                            </button>
                                        </div>
                                        <div class="teammate-info">
                                            <div
                                                style="font-size:0.65rem; color:#8b6914; font-weight:700; letter-spacing:3px; margin-bottom:2px; font-family:var(--font-main);">
                                                — 第一骑士 —</div>
                                            <div class="teammate-name">癌骑士</div>
                                            <div class="teammate-meta">
                                                <span class="cost-badge"><i class="ri-ghost-smile-line"></i> 幻想种</span>
                                                <span class="cost-badge"><i class="ri-sword-line"></i> 殉道骑士</span>
                                            </div>
                                        </div>
                                    </div>
                                    <!-- 夜斗 -->
                                    <div class="teammate-card" @click="selectedPresetChar = presetCharacters.yato"
                                        style="cursor:pointer;">
                                        <div class="teammate-avatar">
                                            <img src="https://dnf.rown.dpdns.org/%E5%B0%81%E9%9D%A2/%E5%A4%9C%E6%96%97.webp"
                                                alt="夜斗">
                                        </div>
                                        <div class="teammate-info">
                                            <div
                                                style="font-size:0.65rem; color:#e74c3c; font-weight:700; letter-spacing:3px; margin-bottom:2px; font-family:var(--font-main);">
                                                — 第二骑士 —</div>
                                            <div class="teammate-name">夜斗</div>
                                            <div class="teammate-meta">
                                                <span class="cost-badge"><i class="ri-ghost-smile-line"></i> 幻想种</span>
                                                <span class="cost-badge"><i class="ri-sword-line"></i> 祸津神</span>
                                            </div>
                                        </div>
                                    </div>
                                    <!-- 未来预设角色占位 -->
                                </div>

                                <!-- 预设角色确认弹窗 -->
                                <div v-if="selectedPresetChar" class="teammate-modal-overlay"
                                    @click.self="selectedPresetChar = null" style="position:fixed; inset:0;">
                                    <div class="teammate-modal" style="margin-top:60px;">
                                        <button class="modal-close" @click="selectedPresetChar = null"><i
                                                class="ri-close-line"></i></button>
                                        <div class="modal-avatar" style="position:relative;">
                                            <img :src="selectedPresetChar.avatar" :alt="selectedPresetChar.name">
                                            <div v-if="selectedPresetChar.id === 'cancer_knight'" class="art-blur-mask"
                                                :class="{revealed: cancerKnightRevealed}" @click.stop>
                                                <span class="blur-warn-text">⚠ 立绘略猎奇</span>
                                            </div>
                                            <button v-if="selectedPresetChar.id === 'cancer_knight'"
                                                class="reveal-eye-btn" v-show="!cancerKnightRevealed"
                                                @click.stop="cancerKnightRevealed = true" title="查看原图"
                                                style="position:absolute; bottom:12px; right:12px; z-index:5;">
                                                <i class="ri-eye-line"></i>
                                            </button>
                                        </div>
                                        <div class="modal-content">
                                            <div class="modal-name">{{ selectedPresetChar.name }}</div>

                                            <div class="modal-desc" style="white-space:pre-line;">{{
                                                selectedPresetChar.intro }}</div>

                                            <div
                                                style="font-size:0.8rem; color:var(--secondary); font-style:italic; text-align:center; margin-bottom:20px; opacity:0.7;">
                                                ——{{ selectedPresetChar.flavor }}
                                            </div>

                                            <button class="modal-select-btn"
                                                @click="selectPresetCharacter(selectedPresetChar.id); selectedPresetChar = null;">
                                                <i class="ri-sword-line"></i> 以此角色开始
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            </div>
                            <!-- 主页面：自定义 vs 预设 -->
                        </div>
                        <div v-else class="preset-select-page">
                            <div class="preset-select-title">选择你的角色</div>
                            <div class="preset-select-subtitle">自定义创建属于你的角色，或选择预设角色直接开始冒险</div>
                            <div class="preset-char-grid">
                                <!-- 自定义角色 -->
                                <div class="preset-char-card card-custom" @click="selectPresetCharacter('custom')">
                                    <div class="custom-card-icon">
                                        <i class="ri-user-add-line"></i>
                                        <span>从零开始创建</span>
                                    </div>
                                    <div class="preset-char-body">
                                        <div class="preset-char-name">自定义角色</div>
                                        <div class="preset-char-tag">自由创建 · 无限可能</div>
                                        <div class="preset-char-desc">
                                            <template v-if="isSolarisWorldview">选择身份、职业、出身背景和特质，从自己的出生地开始，书写属于你的索拉里斯故事。</template>
                                            <template v-else>自由选择种族、职业、出身背景和特质，打造完全属于你的冒险者。从十六种族中挑选血脉，在数十种职业中找到你的战斗风格，书写独一无二的传奇。</template>
                                        </div>
                                    </div>
                                </div>
                                <!-- 预设角色入口 -->
                                <div class="preset-char-card card-preset" @click="presetSubPage = true">
                                    <div class="custom-card-icon"
                                        style="background:linear-gradient(135deg, #2d3436 0%, #636e72 100%);">
                                        <i class="ri-store-2-line" style="color:rgba(255,255,255,0.7);"></i>
                                        <span style="color:rgba(255,255,255,0.8);">查看创意工坊</span>
                                    </div>
                                    <div class="preset-char-body">
                                        <div class="preset-char-name">预设角色</div>
                                        <div class="preset-char-tag">创意工坊 · 即刻冒险</div>
                                        <div class="preset-char-desc">
                                            下载其他玩家的预设角色，或者拓展规则，拥有独特的背景故事、技能树与羁绊关系。跳过繁琐的创建流程，直接踏上冒险之旅。
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </template>

                    <!-- STEP 1: WORLDVIEW -->
                    <template v-else-if="currentStep === 1">
                        <h2 style="margin-bottom:20px; font-family:var(--font-main);">世界观选择</h2>

                        <div class="card-grid"
                            style="grid-template-columns:repeat(auto-fit, minmax(240px, 1fr)); margin-bottom:20px;">
                            <div v-for="world in worldviewOptions" :key="world.id" @click="selectWorldview(world.id)"
                                class="selection-card worldview-card"
                                :class="{ selected: selectedWorldview === world.id }" style="min-height:210px;">
                                <div class="card-check"><i class="ri-check-line"></i></div>
                                <div class="card-header">
                                    <div class="card-icon">
                                        <svg v-if="world.iconPath" viewBox="0 0 512 512"
                                            style="width:26px; height:26px; display:block;">
                                            <path :d="world.iconPath" fill="currentColor"></path>
                                        </svg>
                                        <i v-else :class="world.icon"></i>
                                    </div>
                                    <div>
                                        <div class="card-title">{{ world.name }}</div>
                                        <div class="card-subtitle">{{ world.subtitle }}</div>
                                    </div>
                                </div>
                                <div class="card-desc worldview-desc">{{ world.desc }}</div>
                            </div>
                        </div>

                        <div v-if="selectedWorldview"
                            style="padding:14px 16px; border-radius:12px; background:rgba(45,106,79,0.08); border:1px solid rgba(45,106,79,0.16); color:var(--primary); line-height:1.7;">
                            已选择：<strong>{{ currentWorldviewLabel }}</strong>
                        </div>
                    </template>

                    <!-- STEP 2: BASIC INFO -->
                    <template v-else-if="currentStep === 2">
                        <h2 style="margin-bottom:20px; font-family:var(--font-main);">基础信息设定</h2>

                        <!-- 基本信息卡片 - 横向紧凑布局 -->
                        <div
                            style="background:white; border-radius:12px; padding:15px; box-shadow:var(--shadow-card); margin-bottom:15px;">
                            <div class="basic-info-row"
                                style="display:flex; gap:15px; align-items:center; flex-wrap:wrap;">
                                <!-- 头像上传 -->
                                <div style="flex-shrink:0;">
                                    <div style="position:relative; width:70px; height:70px;">
                                        <input type="file" accept="image/*" @change="handleAvatarUpload"
                                            style="position:absolute; width:100%; height:100%; opacity:0; cursor:pointer; z-index:1;">
                                        <div style="width:70px; height:70px; border-radius:50%; background:var(--input-bg); display:flex; align-items:center; justify-content:center; border:3px dashed rgba(45,106,79,0.3); cursor:pointer; transition:all 0.2s; overflow:hidden;"
                                            :style="{borderColor: character.avatar ? 'var(--accent)' : 'rgba(45,106,79,0.3)', borderStyle: character.avatar ? 'solid' : 'dashed'}">
                                            <img v-if="character.avatar" :src="character.avatar"
                                                style="width:100%; height:100%; object-fit:cover;">
                                            <div v-else style="text-align:center;">
                                                <i class="ri-camera-line"
                                                    style="font-size:1.1rem; color:var(--accent);"></i>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <!-- 姓名、性别、年龄 -->
                                <div class="basic-info-fields"
                                    style="flex:1; display:flex; gap:12px; align-items:flex-end; flex-wrap:wrap; min-width:200px;">
                                    <!-- 姓名 -->
                                    <div style="flex:1; min-width:120px;" :class="{'field-locked': isPresetChar}">
                                        <label class="form-label"
                                            style="font-size:0.75rem; margin-bottom:4px;">角色姓名</label>
                                        <input v-model="character.name" class="form-input" placeholder="输入姓名..."
                                            style="padding:10px 12px; font-size:0.9rem;"
                                            :class="{'locked-input': isPresetChar}" :readonly="isPresetChar">
                                    </div>

                                    <!-- 性别 -->
                                    <div style="width:80px; flex-shrink:0;" :class="{'field-locked': isPresetChar}">
                                        <label class="form-label"
                                            style="font-size:0.75rem; margin-bottom:4px;">性别</label>
                                        <select v-model="character.gender" class="form-select"
                                            style="padding:10px 8px; font-size:0.9rem;"
                                            :class="{'locked-input': isPresetChar}" :disabled="isPresetChar">
                                            <option>男性</option>
                                            <option>女性</option>
                                            <option>无</option>
                                        </select>
                                    </div>

                                    <!-- 年龄 -->
                                    <div style="width:60px; flex-shrink:0;" :class="{'field-locked': isPresetChar}">
                                        <label class="form-label"
                                            style="font-size:0.75rem; margin-bottom:4px;">年龄</label>
                                        <input type="number" v-model.number="character.age" class="form-input" min="1"
                                            style="text-align:center; padding:10px 8px; font-size:0.9rem;"
                                            :class="{'locked-input': isPresetChar}" :readonly="isPresetChar">
                                    </div>
                                </div>
                            </div>
                        </div>

                        <!-- 种族选择区域 -->
                        <div v-if="!isPresetChar" class="race-selection-container"
                            :class="{'amber-race-selection': isAmberWorldview}"
                            style="display:grid; grid-template-columns:200px 1fr; gap:12px; position:relative;">
                            <!-- 左侧：种族列表 -->
                            <div class="race-list-wrapper" style="position:relative;">
                                <div class="race-list-scroll"
                                    style="background:white; border-radius:12px; padding:6px; position:absolute; top:0; left:0; right:0; bottom:0; overflow-y:auto; box-shadow:var(--shadow-card);">
                                    <div
                                        style="font-size:0.8rem; color:var(--secondary); font-weight:700; margin:6px 4px 8px; padding-bottom:6px; border-bottom:1px solid rgba(0,0,0,0.05);">
                                        {{ (isJiuzhouWorldview || isDragonWorldview || isEarthseaWorldview || isSolarisWorldview) ? '选择出身' : '选择种族' }}</div>
                                    <template v-if="isAmberWorldview">
                                        <div class="amber-camp-tabs">
                                            <div v-for="camp in amberCampTabs" :key="camp.key" class="amber-camp-tab"
                                                :class="{active: selectedAmberCamp === camp.key}"
                                                @click="selectedAmberCamp = camp.key">
                                                <div class="amber-camp-tab-main">
                                                    <span class="amber-camp-tab-title">{{ camp.title }}</span>
                                                </div>
                                                <div class="amber-camp-tab-hint">
                                                    {{ camp.desc }}
                                                </div>
                                            </div>
                                        </div>
                                        <div v-if="activeAmberCampGroup" class="amber-camp-panel">
                                            <div class="amber-camp-header">
                                                <span class="amber-camp-title">{{ activeAmberCampGroup.title }}</span>
                                            </div>
                                            <div class="amber-camp-races">
                                                <div v-for="race in activeAmberCampGroup.races" :key="race.name"
                                                    @click="character.race = race.name; customRace.enabled = false"
                                                    class="race-list-item amber-race-list-item"
                                                    :class="{selected: character.race === race.name}">
                                                    <div
                                                        style="display:flex; align-items:center; gap:6px; min-width:0;">
                                                        <i :class="race.icon"
                                                            :style="{color: race.tierColor, fontSize:'0.95rem', flexShrink:0}"></i>
                                                        <span class="amber-race-name">{{
                                                            race.name }}</span>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                        <div class="amber-race-custom">
                                            <div @click="toggleCustomRace" class="race-list-item"
                                                :class="{selected: character.race === '__custom__'}"
                                                style="padding:8px 10px; margin-bottom:0;">
                                                <div
                                                    style="display:flex; align-items:center; justify-content:space-between; gap:4px;">
                                                    <div
                                                        style="display:flex; align-items:center; gap:6px; min-width:0;">
                                                        <i class="ri-quill-pen-line"
                                                            style="color:#6c5ce7; font-size:0.95rem; flex-shrink:0;"></i>
                                                        <span
                                                            style="font-weight:600; font-size:0.85rem; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">{{ isSolarisWorldview ? '自定义出生' : '自定义种族' }}</span>
                                                    </div>
                                                    <div
                                                        style="font-size:0.68rem; color:var(--secondary); white-space:nowrap;">
                                                        自行设定种族特性
                                                    </div>
