                                <div><div style="font-size:0.72rem; color:var(--secondary);">构筑共鸣评议</div><div style="font-size:0.86rem; font-weight:700; margin-top:2px;">{{ buildReviewResult.总分 }}/100 · {{ buildReviewResult.结论 }}<span v-if="buildReviewStale" style="color:#b06c32;">（构筑已变化）</span></div></div>
                                <div v-if="buildReviewRewardActive" style="font-size:0.72rem; color:var(--success); font-weight:700;"><i class="ri-gift-2-line"></i> +10 RP · +2 属性点</div>
                            </div>
                            <div v-if="currentClassSkillTree && remainingRP >= 0 && remainingPoints <= 0"
