                            style="font-size:0.75rem; padding:3px 8px; border-radius:6px; background:rgba(45,106,79,0.1); color:var(--accent); font-weight:600;">
                            <i class="ri-heart-pulse-line"></i> {{ selectedTeammate.coreTag }}
                        </span>
                        <span
                            style="font-size:0.75rem; padding:3px 8px; border-radius:6px; background:rgba(212,168,83,0.15); color:var(--gold-dim); font-weight:600;">
                            <i class="ri-calendar-line"></i> {{ selectedTeammate.age }}
                        </span>
                        <span
