                        style="background:rgba(192,57,43,0.05); border-radius:10px; padding:12px; margin-bottom:16px; border:1px solid rgba(192,57,43,0.1);">
                        <div
                            style="font-size:0.75rem; font-weight:700; color:var(--danger); margin-bottom:6px; display:flex; align-items:center; gap:4px;">
                            <i class="ri-error-warning-line"></i> 同伴限制
                        </div>
                        <div style="font-size:0.85rem; color:#555; line-height:1.6;">{{ selectedTeammate.powerLimit }}
                        </div>
                    </div>

                    <div class="modal-stats">
