爆发出一片锋利的骨刺与触手丛林，对范围内敌人造成多段伤害并束缚。", "特殊效果": { "1": "对范围内敌人造成多段伤害并附加[束缚]状态。" } }, { "名称": "生命透支", "类型": "特殊", "描述": "主动通过通过激素刺激让癌细胞侵蚀肌肉纤维，以还要承受剧痛和生命流逝为代价，换取爆发性的力量。", "特殊效果": { "1": "主动消耗5%当前生命值，最终伤害增加10%，持续2回合", "2": "主动消耗5%当前生命值，最终伤害增加12%，持续2回合", "3": "主动消耗5%当前生命值，最终伤害增加15%，持续3回合", "4": "主动消耗6%当前生命值，最终伤害增加18%，持续3回合", "5": "主动消耗6%当前生命值，最终伤害增加22%，持续3回合", "6": "主动消耗7%当前生命值，最终伤害增加26%，持续4回合", "7": "主动消耗7%当前生命值，最终伤害增加30%，持续4回合", "8": "主动消耗8%当前生命值，最终伤害增加35%，持续4回合", "9": "主动消耗9%当前生命值，最终伤害增加40%，持续5回合", "10": "主动消耗10%当前生命值，最终伤害增加50%，且下一次攻击造成的伤害转化为生命值，持续5回合" } }], "Tier4": [{ "名称": "血肉堡垒", "类型": "主动", "描述": "癌瞬间恶性膨胀，化为超越骑士体型的巨大血肉巨盾，向前推进冲撞，击飞沿途所有敌人并抵挡海量伤害。" }, { "名称": "暴食吞噬", "类型": "主动", "描述": "释放巨大的捕食触手将敌人擒抱并拉至身前，直接进行生物层面的吞噬与吸收，造成大量伤害并回复自身生命值。" }, { "名称": "细胞超频", "类型": "特殊", "描述": "让癌细胞全面接管神经信号传导，痛觉被彻底切断，反应速度突破人类极限，周围的时间彷佛变慢。", "特殊效果": { "1": "受到的伤害减少10%，回避率提升5%，持续2回合", "2": "受到的伤害减少12%，回避率提升6%，持续2回合", "3": "受到的伤害减少15%，回避率提升8%，持续2回合", "4": "受到的伤害减少17%，回避率提升10%，持续3回合", "5": "受到的伤害减少20%，回避率提升12%，持续3回合", "6": "受到的伤害减少22%，回避率提升15%，持续3回合", "7": "受到的伤害减少25%，回避率提升20%，免疫恐惧与魅惑状态，持续4回合" } }], "Tier5": [{ "名称": "扩散斩击", "类型": "主动", "描述": "利用触手弹射进行超高速移动，在战场上留下数道残影，同时对多个目标进行致命斩击，如同癌症扩散般无法阻挡。并将其中一名敌人标记为[原发病灶]。该状态持续3回合。期间该敌人受到的所有伤害，会有50%以\\u201c扩散伤害\\u201d的形式传递给场上所有其他敌人（链接伤害）" }, { "名称": "终末视界", "类型": "主动", "描述": "简笔画世界完全展开，视界内所有敌人的'存在'都被标记为可被擦除的线条。骑士挥剑，对全屏敌人造成无视防御的真实伤害。伤害结算后，斩杀生命值低于20%的敌人。" }, { "名称": "解离之癌", "类型": "主动", "描述": "短暂解除对癌的压制，无数漆黑的触手从体内爆射而出，对周围大范围内的敌人进行无差别的疯狂鞭挞与穿刺。" }], "觉醒": [{ "名称": "荒原骑士", "类型": "主动", "阶位": "觉醒一", "描述": "骑士的意志与癌的本能达成完美共鸣。化身为行走于生与死边界的荒原骑士，周围环境受到侵蚀化为灰白荒原，造成大量伤害，并暂时大幅提升全属性与技能伤害。" }, { "名称": "共生升格", "类型": "主动", "阶位": "觉醒二", "描述": "癌开始向'星潜者'的完全体形态进化，骑士被包裹在神圣而诡异的半透明几丁质装甲中，获得飞行能力与毁灭性的能量释放。" }, { "名称": "第一天启·白马", "类型": "主动", "阶位": "觉醒三", "描述": "'我就看着，见有一匹白马，骑在马上的拿着弓，并有冠冕赐给他。他便出来，胜了又要胜。'——彻底释放天启之力，将整个战场拖入简笔画世界，行使'勾销'权能，将敌人的存在本身如同粉笔字般擦除。" }] } };

