                        const extraMarkup = String(extraHeadMarkup || '');
                        const injectParts = [`<base href="${baseHref}">`];
                        if (bootstrapConfig && typeof bootstrapConfig === 'object') {
                            injectParts.push(bootstrapMarkup);
                        }
                        if (extraMarkup) {
                            injectParts.push(extraMarkup);
                        }
                        const injectMarkup = injectParts.join('');
                        if (/<base\b/i.test(text)) {
                            if (!bootstrapMarkup && !extraMarkup) return text;
                            if (/<head[^>]*>/i.test(text)) {
                                return text.replace(/<head([^>]*)>/i, `<head$1>${bootstrapMarkup}${extraMarkup}`);
                            }
                            if (/<!doctype[^>]*>/i.test(text)) {
                                return text.replace(/<!doctype[^>]*>/i, match => `${match}\n<head>${bootstrapMarkup}${extraMarkup}</head>`);
                            }
                            return `<head>${bootstrapMarkup}${extraMarkup}</head>${text}`;
                        }
                        if (/<head[^>]*>/i.test(text)) {
                            return text.replace(/<head([^>]*)>/i, `<head$1>${injectMarkup}`);
                        }
                        if (/<!doctype[^>]*>/i.test(text)) {
                            return text.replace(/<!doctype[^>]*>/i, match => `${match}\n<head>${injectMarkup}</head>`);
                        }
                        return `<head>${injectMarkup}</head>${text}`;
                    } catch (error) {
                        console.warn('[琥珀地图] 注入 base 失败:', error);
                        return text;
                    }
                }

                function getJiuzhouMapTouchPatchHeadMarkup() {
                    const styleMarkup = '<style>html,body{overscroll-behavior:none;}#map-container{touch-action:none;overscroll-behavior:none;-webkit-user-select:none;user-select:none;}</style>';
                    const scriptMarkup = [
                        `${'<scr' + 'ipt>'}(function(){`,
                        'const CLICK_SUPPRESS_MS = 260;',
                        'const DRAG_THRESHOLD = 6;',
                        'let installed = false;',
                        'function install(){',
                        'if (installed) return true;',
                        'const container = document.getElementById("map-container");',
                        'if (!container || typeof render !== "function") return false;',
                        'installed = true;',
                        'let touchSessionActive = false;',
                        'let activePointerId = null;',
                        'let activeTouchId = null;',
                        'let dragMoved = false;',
                        'let suppressClickUntil = 0;',
                        'const now = () => (typeof performance !== "undefined" && typeof performance.now === "function" ? performance.now() : Date.now());',
                        'const beginDrag = (clientX, clientY) => {',
                        'touchSessionActive = true;',
                        'dragMoved = false;',
                        'isDragging = true;',
                        'dragStartX = clientX;',
                        'dragStartY = clientY;',
                        'dragViewX = viewX;',
                        'dragViewY = viewY;',
                        'container.classList.add("grabbing");',
                        '};',
                        'const moveDrag = (clientX, clientY) => {',
                        'if (!touchSessionActive) return false;',
                        'const dx = clientX - dragStartX;',
                        'const dy = clientY - dragStartY;',
                        'if (!dragMoved && Math.hypot(dx, dy) < DRAG_THRESHOLD) return false;',
                        'dragMoved = true;',
                        'viewX = dragViewX + dx / scale;',
                        'viewY = dragViewY + dy / scale;',
                        'render();',
                        'return true;',
                        '};',
                        'const endDrag = () => {',
                        'if (!touchSessionActive) return;',
                        'if (dragMoved) suppressClickUntil = now() + CLICK_SUPPRESS_MS;',
                        'touchSessionActive = false;',
                        'activePointerId = null;',
                        'activeTouchId = null;',
                        'dragMoved = false;',
                        'isDragging = false;',
                        'container.classList.remove("grabbing");',
                        '};',
                        'container.addEventListener("click", function(event){',
                        'if (suppressClickUntil && now() < suppressClickUntil) {',
                        'event.preventDefault();',
                        'event.stopImmediatePropagation();',
                        '}',
                        '}, true);',
                        'if (window.PointerEvent) {',
                        'container.addEventListener("pointerdown", function(event){',
                        'if (event.pointerType === "mouse" || touchSessionActive) return;',
                        'activePointerId = event.pointerId;',
                        'beginDrag(event.clientX, event.clientY);',
                        'if (typeof container.setPointerCapture === "function") {',
                        'try { container.setPointerCapture(event.pointerId); } catch (error) {}',
                        '}',
                        '}, { passive: true });',
                        'container.addEventListener("pointermove", function(event){',
                        'if (!touchSessionActive || activePointerId !== event.pointerId) return;',
                        'if (moveDrag(event.clientX, event.clientY)) event.preventDefault();',
                        '}, { passive: false });',
                        'const finishPointerDrag = function(event){',
                        'if (!touchSessionActive || (activePointerId !== null && event.pointerId !== activePointerId)) return;',
                        'if (event.pointerId !== undefined && typeof container.releasePointerCapture === "function") {',
                        'try { container.releasePointerCapture(event.pointerId); } catch (error) {}',
                        '}',
                        'endDrag();',
                        '};',
                        'container.addEventListener("pointerup", finishPointerDrag);',
                        'container.addEventListener("pointercancel", finishPointerDrag);',
                        'container.addEventListener("lostpointercapture", finishPointerDrag);',
                        'return true;',
                        '}',
                        'const findTouch = function(touchList){',
                        'for (let i = 0; i < touchList.length; i++) {',
                        'if (touchList[i].identifier === activeTouchId) return touchList[i];',
                        '}',
                        'return null;',
                        '};',
                        'container.addEventListener("touchstart", function(event){',
                        'if (touchSessionActive || !event.changedTouches.length) return;',
                        'const touch = event.changedTouches[0];',
                        'activeTouchId = touch.identifier;',
                        'beginDrag(touch.clientX, touch.clientY);',
                        '}, { passive: true });',
                        'window.addEventListener("touchmove", function(event){',
                        'if (!touchSessionActive) return;',
                        'const touch = findTouch(event.changedTouches) || findTouch(event.touches);',
                        'if (!touch) return;',
                        'if (moveDrag(touch.clientX, touch.clientY)) event.preventDefault();',
                        '}, { passive: false });',
                        'const finishTouchDrag = function(event){',
                        'if (!touchSessionActive) return;',
                        'if (event.type !== "touchcancel" && !findTouch(event.changedTouches)) return;',
                        'endDrag();',
                        '};',
                        'window.addEventListener("touchend", finishTouchDrag, { passive: true });',
                        'window.addEventListener("touchcancel", finishTouchDrag, { passive: true });',
                        'return true;',
                        '}',
                        'if (!install()) {',
                        'window.addEventListener("DOMContentLoaded", install, { once: true });',
                        'window.addEventListener("load", install, { once: true });',
                        '}',
                        '})();',
                        `${'</scr' + 'ipt>'}`
                    ].join('');
                    return `${styleMarkup}${scriptMarkup}`;
                }

