                async function loadJiuzhouSectNodesFromNetwork(force = false) {
                    if (!force && jiuzhouSectNodes.value.length > 0) return jiuzhouSectNodes.value;
                    if (jiuzhouSectLoadPromise) return jiuzhouSectLoadPromise;
                    jiuzhouSectLoadState.value = 'loading';
                    const dataUrl = buildJiuzhouMapDataUrl(resolveJiuzhouMapBaseUrl());
                    jiuzhouSectLoadPromise = (async () => {
                        try {
                            if (!dataUrl || !/^https?:\/\//i.test(dataUrl)) {
                                throw new Error('无可用门派数据地址');
                            }
                            const response = await fetch(dataUrl, { method: 'GET', mode: 'cors', credentials: 'omit' });
                            if (!response.ok) throw new Error(`HTTP ${response.status}`);
                            const text = await response.text();
                            const parsed = parseJiuzhouMapDataScript(text);
                            const nodes = Array.isArray(parsed?.mapData?.nodes) ? parsed.mapData.nodes : [];
                            const edges = Array.isArray(parsed?.mapData?.edges) ? parsed.mapData.edges : [];
                            jiuzhouMapGraph.value = { nodes, edges };
                            jiuzhouSectNodes.value = nodes.filter(node => String(node?.type || '').trim().toLowerCase() === 'sect');
                            jiuzhouSectLoadState.value = jiuzhouSectNodes.value.length > 0 ? 'ready' : 'empty';
                            return jiuzhouSectNodes.value;
                        } catch (error) {
                            console.warn('[大明志异地图] 门派数据读取失败:', error);
                            jiuzhouMapGraph.value = { nodes: [], edges: [] };
                            jiuzhouSectNodes.value = [];
                            jiuzhouSectLoadState.value = 'error';
                            return [];
                        } finally {
                            jiuzhouSectLoadPromise = null;
                        }
                    })();
                    return jiuzhouSectLoadPromise;
                }

