                function matchesWorkshopSourceEntry(entry, sourceMeta) {
                    const meta = entry?.extra?.creativeWorkshop || null;
                    if (!meta || !sourceMeta?.sourceId) return false;
                    return String(meta.sourceId) === String(sourceMeta.sourceId)
                        && (!sourceMeta.sourceType || String(meta.sourceType || '') === String(sourceMeta.sourceType));
                }

                function createWorkshopBoundaryEntry(name, order) {
                    return {
                        name,
                        enabled: true,
                        strategy: {
                            type: 'constant',
                            keys: [],
                            keys_secondary: { logic: 'and_any', keys: [] },
                            scan_depth: 'same_as_global'
                        },
                        position: {
                            type: 'after_character_definition',
                            role: 'system',
                            depth: 0,
                            order
                        },
                        content: '',
                        probability: 100,
                        recursion: {
                            prevent_incoming: false,
                            prevent_outgoing: false,
                            delay_until: null
                        },
                        effect: {
                            sticky: null,
                            cooldown: null,
                            delay: null
                        },
                        extra: {
                            creativeWorkshop: {
                                sourceId: name,
                                sourceType: 'anchor',
                                sourceTitle: name,
                                installedAt: new Date().toISOString(),
                                slot: 'anchor'
                            }
                        }
                    };
                }

                function normalizeWorkshopBoundaryName(name) {
                    return String(name || '').trim();
                }

                function normalizeWorkshopPositionType(value) {
                    const normalized = String(value || '').trim();
                    if (normalized === 'before_character_definition' || normalized === 'after_character_definition' || normalized === 'at_depth') {
                        return normalized;
                    }
                    return 'after_character_definition';
                }

                function normalizeWorkshopDepthValue(value) {
                    const nextValue = Number(value);
                    if (!Number.isFinite(nextValue)) {
                        return 0;
                    }
                    return Math.max(0, Math.floor(nextValue));
                }

                function normalizeWorkshopManagedPosition(position = {}, fallbackOrder = workshopModStartOrder + 1) {
                    const nextOrder = Number(position?.order);
                    return {
                        ...(position || {}),
                        type: normalizeWorkshopPositionType(position?.type),
                        role: position?.role || 'system',
                        depth: normalizeWorkshopDepthValue(position?.depth),
                        order: Number.isFinite(nextOrder) ? nextOrder : fallbackOrder
                    };
                }

                function ensureWorkshopBoundaryEntries(worldbook) {
                    const nextWorldbook = [...worldbook];
                    const startMatches = nextWorldbook.filter(entry => normalizeWorkshopBoundaryName(entry?.name) === workshopModStartName);
                    const endMatches = nextWorldbook.filter(entry => normalizeWorkshopBoundaryName(entry?.name) === workshopModEndName);
                    let startEntry = startMatches[0] || null;
                    let endEntry = endMatches[0] || null;
                    const dedupedWorldbook = nextWorldbook.filter(entry => {
                        const normalizedName = normalizeWorkshopBoundaryName(entry?.name);
                        if (normalizedName === workshopModStartName) return entry === startEntry;
                        if (normalizedName === workshopModEndName) return entry === endEntry;
                        return true;
                    });
                    if (!startEntry) {
                        startEntry = createWorkshopBoundaryEntry(workshopModStartName, workshopModStartOrder);
                        dedupedWorldbook.push(startEntry);
                    }
                    if (!endEntry) {
                        endEntry = createWorkshopBoundaryEntry(workshopModEndName, workshopModEndOrder);
                        dedupedWorldbook.push(endEntry);
                    }
                    startEntry.position = { ...(startEntry.position || {}), type: 'after_character_definition', role: 'system', depth: 0, order: workshopModStartOrder };
                    endEntry.position = { ...(endEntry.position || {}), type: 'after_character_definition', role: 'system', depth: 0, order: workshopModEndOrder };
                    startEntry.enabled = true;
                    endEntry.enabled = true;
                    startEntry.name = workshopModStartName;
                    endEntry.name = workshopModEndName;
                    return dedupedWorldbook;
                }

                function reorderWorkshopManagedEntries(worldbook) {
                    const nextWorldbook = ensureWorkshopBoundaryEntries(worldbook);
                    const managedEntries = nextWorldbook
                        .filter(entry => {
                            const normalizedName = normalizeWorkshopBoundaryName(entry?.name);
                            if (normalizedName === workshopModStartName || normalizedName === workshopModEndName) return false;
                            const meta = entry?.extra?.creativeWorkshop || null;
                            return !!meta && meta.sourceType !== 'anchor';
                        })
                        .sort((a, b) => {
                            const aOrder = Number(a?.position?.order ?? 0);
                            const bOrder = Number(b?.position?.order ?? 0);
                            if (aOrder !== bOrder) return aOrder - bOrder;
                            return String(a?.name || '').localeCompare(String(b?.name || ''));
                        });
                    managedEntries.forEach((entry, index) => {
                        entry.position = normalizeWorkshopManagedPosition(entry.position || {}, workshopModStartOrder + 1 + index);
                    });
                    return nextWorldbook;
                }

                async function handleWorkshopBridgeAction(action, payload = {}) {
                    switch (action) {
                        case 'handshake':
                            return { ok: true, label: '开局页桥接' };
                        case 'getContext':
                            return { context: getWorkshopWorldbookContext() };
                        case 'getEntries':
                            return { entries: await getWorldbook(payload.worldbookName) };
                        case 'createWorldbook':
                            if (typeof createWorldbook !== 'function') throw new Error('createWorldbook 不可用');
                            return await createWorldbook(payload.worldbookName, []);
                        case 'createEntries':
                            return await createWorldbookEntries(payload.worldbookName, payload.entries || [], { render: 'immediate' });
                        case 'updateEntry':
                            return await updateWorldbookWith(payload.worldbookName, worldbook => worldbook.map(entry => (
                                Number(entry.uid) === Number(payload.uid) ? { ...entry, ...(payload.nextEntry || {}) } : entry
                            )), { render: 'immediate' });
                        case 'deleteEntries': {
                            const uidSet = new Set((payload.uids || []).map(uid => Number(uid)));
                            return await deleteWorldbookEntries(payload.worldbookName, entry => uidSet.has(Number(entry.uid)), { render: 'immediate' });
                        }
                        case 'upsertWorkshopEntries':
                            return await updateWorldbookWith(payload.worldbookName, worldbook => {
