                    { name: '脸盲', cost: -3, category: 'negative', type: 'flaw', icon: 'ri-user-unfollow-line', desc: '所有人的脸在你看来都差不多。', effect: '与只见过一次的NPC重逢时需进行识别检定，失败则无法确认对方身份，常闹出社交事故。', flavor: '「你是...那个谁来着？」' },
                    { name: '心软', cost: -6, category: 'negative', type: 'flaw', icon: 'ri-heart-line', desc: '你见不得别人受苦。', effect: '哪怕是敌人的眼泪也能让你动摇，对求饶者的命中检定劣势。', flavor: '「...算了，放你走吧。」' },
                    { name: '收藏癖', cost: -3, category: 'negative', type: 'flaw', icon: 'ri-archive-line', desc: '你无法抗拒收集某类特定物品的冲动。', effect: '遇到你收集主题内的稀奇物品时需进行感知豁免，失败则必须带走；主动丢弃已收藏之物时需再次豁免。背包永远超重。', flavor: '「这个贝壳的纹路很特别...我要留着。」' },
                    // ===== 双刃剑特质 =====
                    { name: '天生赌徒', cost: 5, category: 'double-edged', type: 'world', icon: 'ri-dice-fill', desc: '你的赌局从来不会平淡收场。', effect: '进行赌博或纯运气检定时，自然1～5视为大失败，自然15～20视为大成功。', flavor: '「小赢有什么意思？要么通吃，要么输光。」' },
                    { name: '三分钟热度', cost: 15, category: 'double-edged', type: 'fate', icon: 'ri-timer-flash-line', desc: '你的热情来得猛烈，也退得干净。', effect: '每次短休1次，当众承诺在3回合内对明确目标完成一项具体行动。3回合内，相关属性检定和攻击检定+5；此后直到场景结束，你无法再完成该承诺(例如:宣言攻击/战胜某人，三回合内仅对该人的攻击检定+5，过后无法再以任何方式攻击此人)。', flavor: '「三回合。够我把刚才的话变成真的。」' },
                    { name: '众目睽睽', cost: 10, category: 'double-edged', type: 'combat', icon: 'ri-focus-3-line', desc: '你能让混乱的战场暂时只剩下两名彼此注视的对手。', effect: '每场战斗1次，向一名能理解你的敌人公开挑战，双方以魅力或感知（取高）对抗。成功后，双方互相攻击时攻击检定+3，效果持续至一方倒下；若攻击第三者，该次攻击检定-3并立即结束效果。', flavor: '「看着我。你的敌人只有我。」' },
                    { name: '浴血狂战', cost: 15, category: 'double-edged', type: 'combat', icon: 'ri-knife-blood-line', desc: '鲜血与伤势会将你推入舍弃防守的狂战状态。', effect: '每场战斗1次，当HP低于50%或你在本场战斗首次击杀敌人后，可用附赠动作进入[浴血狂战]，持续3回合：最终物理伤害+20%、攻击检定+1，无法使用消耗品、施法或防御类技能；若HP低于25%，加成提高为最终物理伤害+30%、攻击检定+2。状态结束后获得1层[疲惫]，所有属性检定-5。', flavor: '「鲜血、战斗，使我陶醉。」' },
                    { name: '命运之子', cost: 5, category: 'double-edged', type: 'fate', icon: 'ri-star-line', desc: '命运似乎对你格外关注。', effect: '每长休1次，可重投任意一次d20检定并接受新结果；使用后，你的下一次d20检定自动劣势。', flavor: '「是福是祸，全看天意。」' },
                    { name: '死神眷顾', cost: 0, category: 'double-edged', type: 'fate', icon: 'ri-skull-2-line', desc: '死神钟情于你，刀剑、毒火与怪物只能一次次把你送到祂的白马前——其他人杀不死你，你的最后一口气，只属于那位苍白无面的骑士。', effect: '生命值降至0时不会死亡或濒死：改为获得1层持续1日的[它在等你]状态标记，然后生命值恢复至满血。每层标记使全属性检定-3、攻击检定-5；标记可叠加，新增层数会刷新全部标记的持续时间。携带标记在夜晚入睡时投掷1D20，结果小于10则触发特殊战斗[它来了]。死神是与玩家等级相同的传奇敌人，形象为骑着白马的苍白无面骑士；不可交流、不可谈判、不可逃脱，正如死亡本身。只有在与死神的战斗中，玩家生命值降至0才会真正死亡。战胜死神后清除全部标记；随后进行一次战利品检定，结果大于66时，随机获得死神之眼、心脏、颅骨、肋骨、手指等残骸中的1件，均为特殊类型的传说装备。', flavor: '「他们杀不了你。他们替我把你送回来。」' },
                    // ===== 特殊/稀有特质 =====
                    { name: '灵魂铸师', cost: 10, category: 'special', type: 'craft', icon: 'ri-hammer-line', desc: '你能捕获强敌消散前的残魂，并将其短暂锻入装备。', effect: '每次长休1次，在你参与击杀一个非召唤生物后，可将其残魂封存为[魂胚]（品质不高于该生物的战利品品质，同时最多持有1枚）。长休时可将魂胚铸入一件武器或护甲，使其获得一个符合该生物特性的临时词条，持续至下次长休；同一件装备只能承载1个魂铸词条，取出或替换后原魂胚消散。', flavor: '「钢铁只记得火焰，灵魂却记得它生前最强烈的执念。」' },
                    { name: '镜中人', cost: 5, category: 'special', type: 'supernatural', icon: 'ri-ghost-smile-line', desc: '镜子里的你...似乎有自己的想法。', effect: '你可对镜面提问，回答的真假由一次检定决定（成功为真、失败为误导）；仅在同一天连续追问时才累积[迷失]，累满触发短暂精神失控。', flavor: '「镜子里的那个家伙...我不确定他是不是我。」' },
                    { name: '梦行者', cost: 6, category: 'special', type: 'supernatural', icon: 'ri-moon-clear-line', desc: '你能在梦境中自由行走。', effect: '睡眠时意识清醒。可尝试潜入他人梦境，需与梦主进行对抗检定：成功则窥得其一段深埋秘密；失败被梦主察觉；大失败则受到精神伤害或被困梦境直至被唤醒。', flavor: '「我分不清了...这是梦，还是醒着？」' },
                    // ===== 生活技能特质 (各自代表一条玩法方向，整组保留) =====
                    { name: '营地管家', cost: 20, category: 'life_skill', type: 'survival', icon: 'ri-home-heart-line', desc: '你能让荒野中的一夜变成休整、欢聚、补给，或一场有备而来的夜袭。', effect: '在野外消耗物资扎营度夜时，耗费一夜并投掷两次D20，分别结算对应效果。两次结果不能属于同一档；若重复，第二次循环顺延至下一档。1～5：遭遇一组随机精英敌人；除自然1外，敌人第一回合无法行动，自然1时敌人正常行动且必定先攻；胜利后获得双倍战利品。6～10：每人清除全部轻度负面状态，且下一次D20检定+3。11～15：所有队友对你的好感度+10；结算后好感度大于80的队友，你在说服其参加由你主持的活动时，魅力检定获得优势，被拒绝也不会留下负面关系影响(甚至是银趴！)。16～20：每人可通过挖掘、采集或探索进行一次战利品检定。', flavor: '「火升起来以后，今晚总会发生点什么。」' },
                    { name: '大厨', cost: 8, category: 'life_skill', type: 'craft', icon: 'ri-restaurant-2-line', desc: '你是一位真正的烹饪专家，能将最普通的食材化为珍馐。', effect: '烹饪检定+4，制作的料理必定附带一种料理增益（取自料理增益表）。提供稀有及以上食材可制作同品质料理，普通食材只能做出精良以下。同一角色同时只能保留一种料理增益。', flavor: '「火候、刀工、调味——三者缺一不可。」' },
                    { name: '酿酒师', cost: 8, category: 'life_skill', type: 'craft', icon: 'ri-goblet-line', desc: '你能把不同原料的特性酿进酒里，让每一坛酒都有自己的用途。', effect: '酿造检定+4，可使用不同材料酿造对应品质的酒。每批酒根据原料与酿造目的获得一种主题效果，具体效果与副作用由品质和检定结果决定。酒可用于恢复、强化、宴请、交易、诱导、迷醉或作为特殊素材。', flavor: '「水只是解渴，酒能解决的问题可多得多。」' },
                    { name: '锻造大师', cost: 20, category: 'life_skill', type: 'craft', icon: 'ri-hammer-line', desc: '你精通锻造与制作，是公认的工匠大师。', effect: '锻造/制作检定+4，你在锻造时无视缺少蓝图的DC减值影响。', flavor: '「每一锤都要恰到好处。」' },
                    { name: '妙手回春', cost: 10, category: 'life_skill', type: 'craft', icon: 'ri-heart-pulse-line', desc: '你拥有专家级的医术，能在战场上救死扶伤。', effect: '医疗检定+4，使用治疗道具时恢复量+50%；治愈特殊伤病与诅咒需要对应材料、长时间治疗与高难度检定。', flavor: '「只要还有一口气，我就能把你拉回来。」' },
                    { name: '炼金宗师', cost: 20, category: 'life_skill', type: 'craft', icon: 'ri-flask-line', desc: '你是炼金术领域的顶尖专家，精通药剂与材料的转化。', effect: '炼金检定+4，提供卓越级及以上炼金素材可尝试调配同品质药剂，稀有以下素材最高产出精良药剂。副作用减半。', flavor: '「万物皆可分解，亦可重组。」' },
                    { name: '吟游诗人', cost: 7, category: 'life_skill', type: 'performance', icon: 'ri-music-line', desc: '你的演奏与歌声已臻化境，能打动最冷酷的心。', effect: '表演检定+4；每短休若干次，演奏可择一：为一次检定+3、给予队友临时生命值、或解除一次恐惧效果。在酒馆演出可获得报酬和情报。', flavor: '「一曲终了，满座皆泣。」' },
                    { name: '驯兽师', cost: 8, category: 'life_skill', type: 'survival', icon: 'ri-bear-smile-line', desc: '你是驯服和训练野兽的专家，与动物有着天然的默契。', effect: '驯兽检定+4，可尝试驯服野生魔物。最多同时拥有1只战斗伙伴，其等级不超过你、需维护忠诚，死亡后需较长时间重新驯养，占用1个队友槽位。', flavor: '「每一头野兽，都在等待理解它的人。」' },
                    { name: '星象师', cost: 7, category: 'life_skill', type: 'knowledge', icon: 'ri-compass-3-line', desc: '你能读懂星辰指引的隐秘路径，看见旁人看不见的道路。', effect: '星象检定+4；夜间观星时可尝试解读出一条[星辰之路]——通往当前目的地的隐藏捷径、避开危险的迂回路线，或抵达某个不为人知之地的入口。每晚可解读一次，能否成功及路径通向何方由检定结果决定。', flavor: '「星辰从不说谎，只是大多数人听不懂。」' },
                    { name: '商贾奇才', cost: 10, category: 'life_skill', type: 'social', icon: 'ri-money-cny-box-line', desc: '你天生就是做生意的料，对市场和利润有着敏锐的嗅觉。', effect: '交易检定+4，正常消费买价-15%、战利品卖价+15%，可评估物品真实价值。同一物品在同一市场不可低买高卖套利。', flavor: '「低买高卖，这是最古老也最有效的魔法。」' },
                    { name: '巧手', cost: 8, category: 'life_skill', type: 'craft', icon: 'ri-hand-heart-line', desc: '你的双手灵巧无比，精通开锁、拆卸、陷阱和复杂机关。', effect: '巧手检定+4；可在不触发的前提下尝试拆解复杂机关，并可处理专家级非魔法机关。开锁或解除陷阱检定普通失败时，不会损坏工具、锁芯或立即触发陷阱，只有大失败才会造成这些后果。扒窃检定优势。', flavor: '「锁、陷阱和齿轮只是不同的问题，而我的手总能找到答案。」' },
                    // ===== 彩蛋/趣味特质 =====
                    { name: '人中之龙', cost: 8, category: 'easter_egg', type: 'adult', icon: 'ri-brain-line', desc: '每次结束做爱行为后，你会进入短暂的贤者时间。', effect: '完成做爱行为后获得[贤者时间]状态，持续1小时；期间智力与感知属性检定+3。该效果不直接提高智力或感知数值，也不改变豁免DC及其他派生属性。', flavor: '「大彻大悟的瞬间，万物皆可看透。」' },
                    { name: '异界来客', cost: 10, category: 'easter_egg', type: 'origin', icon: 'ri-global-line', desc: '你来自另一个世界。', effect: '对本世界常识检定劣势，但拥有[异界知识]：可尝试用智力检定解决本世界无解的问题。开局额外附赠一件异界遗物。', flavor: '「这个世界的规则...和我知道的不太一样。」' },
                    { name: '雪人套', cost: -5, category: 'easter_egg', type: 'skin', icon: 'ri-user-smile-line', desc: '你对像素头和圆滚滚的雪人玩偶服有着谜一般的审美执着。', effect: '你的外观强制固定为[雪人玩偶服+像素头套]。社交魅力检定-3，但对[威吓]和[精神威慑]拥有极高抗性。', flavor: '「这叫时尚！依然是这片棋盘世界上最潮的装扮！」' },
                    { name: '罐子头', cost: -6, category: 'easter_egg', type: 'curse', icon: 'ri-funds-box-line', desc: '你总觉得下一个罐子里装着传承装备。', effect: '看到未鉴定的容器/盲盒时，产生强烈的开启冲动，你非常愿意在盲盒上投入大量金钱。通常开出来的都是垃圾，但你永远相信"下一次"会出货。', flavor: '「绝对没有空空的，绝对！」' }
                ]);
                const POINT_BUY_COSTS = {
                    8: 0, 9: 1, 10: 2, 11: 3, 12: 4, 13: 5, 14: 7, 15: 9
                };
                const BASE_ATTR = 8;
                const MAX_ATTR = 15;
                const MIN_ATTR = 8;
                const TOTAL_POINTS = 27; // 博德之门3标准购点

                const character = reactive({
                    name: '',
                    gender: '男性',
                    age: 18,
                    race: '人类种',
                    identity: '__custom__',
                    level: 1, // 会根据种族自动设置
                    avatar: localStorage.getItem('rpg_player_avatar') || '', // 头像图片URL
                    // DND标准六维：力量、敏捷、体质、智力、感知、魅力
                    attributes: { strength: 10, dexterity: 10, constitution: 10, intelligence: 10, wisdom: 10, charisma: 10 },
                    reincarnationPoints: 100,
                    class: '', // Stores the Advancement Name
                    skills: [], // Initial empty skills
                    backstory: '',
                    teammates: [],
                    selectedTraits: []
                });

                const TEAMMATE_IMAGE_TIMEOUT_STEPS = [12000, 18000, 26000, 36000, 50000];
                const TEAMMATE_IMAGE_RETRY_DELAYS = [0, 1000, 2500, 5000, 9000];
                const TEAMMATE_IMAGE_FALLBACK = `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(`
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 480">
  <rect width="360" height="480" fill="#eef1f3"/>
  <circle cx="180" cy="145" r="64" fill="#c7d0d6"/>
  <rect x="84" y="242" width="192" height="118" rx="24" fill="#d7dde2"/>
  <text x="180" y="415" text-anchor="middle" fill="#74808a" font-family="Arial, sans-serif" font-size="18">Portrait unavailable</text>
</svg>`)}`;
                const teammateAvatarLoadMap = reactive({});

                function clearTeammateAvatarTimers(entry) {
                    if (!entry) return;
                    if (entry.timeoutTimer) {
                        clearTimeout(entry.timeoutTimer);
                        entry.timeoutTimer = 0;
                    }
                    if (entry.retryTimer) {
                        clearTimeout(entry.retryTimer);
                        entry.retryTimer = 0;
                    }
                    if (entry.preloader) {
                        entry.preloader.onload = null;
                        entry.preloader.onerror = null;
                        entry.preloader = null;
                    }
                }

                function buildTeammateAvatarAttemptUrl(rawUrl, attempt) {
                    if (!rawUrl) return TEAMMATE_IMAGE_FALLBACK;
                    if (attempt <= 0) return rawUrl;
                    const separator = rawUrl.includes('?') ? '&' : '?';
                    return `${rawUrl}${separator}img_retry=${attempt}&img_ts=${Date.now()}`;
                }

                function ensureTeammateAvatarEntry(rawUrl) {
                    const key = String(rawUrl || '').trim();
                    if (!key) return null;
                    if (!teammateAvatarLoadMap[key]) {
                        teammateAvatarLoadMap[key] = {
                            rawUrl: key,
                            displaySrc: key,
                            attempt: -1,
                            status: 'idle',
                            lastError: '',
                            requestId: '',
                            timeoutTimer: 0,
                            retryTimer: 0,
                            preloader: null
                        };
                    }
                    return teammateAvatarLoadMap[key];
                }

                function scheduleTeammateAvatarRetry(rawUrl, nextAttempt, reason = 'error') {
                    const entry = ensureTeammateAvatarEntry(rawUrl);
                    if (!entry) return;

                    clearTeammateAvatarTimers(entry);
                    entry.lastError = reason;

                    if (nextAttempt >= TEAMMATE_IMAGE_TIMEOUT_STEPS.length) {
                        entry.status = 'failed';
                        entry.displaySrc = TEAMMATE_IMAGE_FALLBACK;
                        return;
                    }

                    entry.status = 'retrying';
                    const delay = TEAMMATE_IMAGE_RETRY_DELAYS[Math.min(nextAttempt, TEAMMATE_IMAGE_RETRY_DELAYS.length - 1)];
                    entry.retryTimer = setTimeout(() => {
                        runTeammateAvatarAttempt(rawUrl, nextAttempt);
                    }, delay);
                }

                function runTeammateAvatarAttempt(rawUrl, attempt = 0) {
                    const entry = ensureTeammateAvatarEntry(rawUrl);
                    if (!entry) return;

                    clearTeammateAvatarTimers(entry);
                    entry.attempt = attempt;
                    entry.status = 'loading';

                    const attemptUrl = buildTeammateAvatarAttemptUrl(entry.rawUrl, attempt);
                    const requestId = `${Date.now()}_${attempt}_${Math.random().toString(36).slice(2)}`;
                    entry.requestId = requestId;
                    entry.displaySrc = attemptUrl;

                    const timeoutMs = TEAMMATE_IMAGE_TIMEOUT_STEPS[Math.min(attempt, TEAMMATE_IMAGE_TIMEOUT_STEPS.length - 1)];
                    const preloader = new Image();
                    entry.preloader = preloader;

                    let settled = false;
                    const finish = (result) => {
                        if (settled || entry.requestId !== requestId) return;
                        settled = true;
                        if (entry.timeoutTimer) {
                            clearTimeout(entry.timeoutTimer);
                            entry.timeoutTimer = 0;
                        }
                        entry.preloader = null;

                        if (result === 'load') {
                            entry.status = 'loaded';
                            entry.lastError = '';
                            return;
                        }

                        scheduleTeammateAvatarRetry(entry.rawUrl, attempt + 1, result);
                    };

                    preloader.onload = () => finish('load');
                    preloader.onerror = () => finish('error');
                    entry.timeoutTimer = setTimeout(() => finish('timeout'), timeoutMs);
                    preloader.src = attemptUrl;
                }

                function primeTeammateAvatar(rawUrl) {
                    const entry = ensureTeammateAvatarEntry(rawUrl);
                    if (!entry) return TEAMMATE_IMAGE_FALLBACK;
                    if (entry.status === 'idle') {
                        runTeammateAvatarAttempt(entry.rawUrl, 0);
                    }
                    return entry.displaySrc || entry.rawUrl || TEAMMATE_IMAGE_FALLBACK;
                }

                function getTeammateAvatarSrc(rawUrl) {
                    if (!rawUrl) return TEAMMATE_IMAGE_FALLBACK;
                    return primeTeammateAvatar(rawUrl);
                }

                function getTeammateEncounterLevelLabel(mate) {
                    const level = Number(mate?.encounterLevel) || 1;
                    if (level === 1 && !FIXED_LEVEL_TEAMMATE_NAMES.has(mate?.name)) {
                        return `Lv.${actualStartLevel.value}（同主角）`;
                    }
                    return `Lv.${level}`;
                }

                watch(currentStep, (step) => {
                    if (step !== 5) return;
                    mockData.teammates.forEach((mate) => {
                        primeTeammateAvatar(mate.avatar);
                    });
                    if (currentPresetCompanion.value?.avatar) {
                        primeTeammateAvatar(currentPresetCompanion.value.avatar);
                    }
                }, { immediate: true });

                // 自定义种族数据
                const customRace = reactive({
                    enabled: false,
                    name: '',
                    trait1: { name: '', detail: '', negative: false },
                    trait2: { name: '', detail: '', negative: false }
                });

                // 自定义种族特性编辑弹窗
                const showCustomRaceTraitModal = ref(false);
                const customRaceTraitIndex = ref(1);
                const customRaceTraitDraft = reactive({ name: '', detail: '', negative: false });

                const normalizeCustomRaceTrait = (trait) => ({
                    name: typeof trait?.name === 'string' ? trait.name : '',
                    detail: typeof trait?.detail === 'string' ? trait.detail : '',
                    negative: !!trait?.negative
                });
                const customRaceLevelCap = mockData.races.find(r => r.name === '龙精种')?.startLevel || 65;

                // 打开自定义种族特性编辑弹窗
                function openCustomRaceTraitModal(index) {
                    customRaceTraitIndex.value = index;
                    const rawTrait = index === 1 ? customRace.trait1 : customRace.trait2;
                    const trait = normalizeCustomRaceTrait(rawTrait);
                    customRaceTraitDraft.name = trait.name;
                    customRaceTraitDraft.detail = trait.detail;
                    customRaceTraitDraft.negative = trait.negative;
                    showCustomRaceTraitModal.value = true;
                }

                // 关闭自定义种族特性编辑弹窗
                function closeCustomRaceTraitModal() {
                    showCustomRaceTraitModal.value = false;
                    customRaceTraitDraft.name = '';
                    customRaceTraitDraft.detail = '';
                    customRaceTraitDraft.negative = false;
                }

                // 确认自定义种族特性
                function confirmCustomRaceTrait() {
                    if (!customRaceTraitDraft.name.trim() || !customRaceTraitDraft.detail.trim()) return;

                    const trait = customRaceTraitIndex.value === 1 ? customRace.trait1 : customRace.trait2;
                    trait.name = customRaceTraitDraft.name.trim();
                    trait.detail = customRaceTraitDraft.detail.trim();
                    trait.negative = customRaceTraitDraft.negative;

                    // 如果种族名称为空，设置默认名称
                    if (!customRace.name.trim()) {
                        customRace.name = '自定义种族';
                    }

                    closeCustomRaceTraitModal();
                }

                // 切换自定义种族
                function toggleCustomRace() {
                    customRace.enabled = !customRace.enabled;
                    if (customRace.enabled) {
                        character.race = '__custom__';
                    } else {
                        const fallbackRace = availableRaces.value.find(r => !r.disabled)?.name || '人类种';
                        character.race = fallbackRace;
                    }
                }

                // ==================== 预设管理系统 ====================
                const PRESET_STORAGE_KEY = 'start_presets';
                // 使用 base64url（无 + / =）降低在宿主注入/序列化过程中的歧义风险；同时兼容旧版 base64-json-v1
                const PRESET_STORAGE_VERSION = 'base64url-json-v1';
                const showPresetModal = ref(false);
                const newPresetName = ref('');
                const presetList = ref([]);

                const toBase64Url = (base64) => String(base64 || '')
                    .replace(/\+/g, '-')
                    .replace(/\//g, '_')
                    .replace(/=+$/g, '');

                const fromBase64Url = (base64url) => {
                    let base64 = String(base64url || '').replace(/-/g, '+').replace(/_/g, '/');
                    const pad = base64.length % 4;
                    if (pad) base64 += '='.repeat(4 - pad);
                    return base64;
                };

                const clonePlainData = (value) => {
                    try {
                        return JSON.parse(JSON.stringify(value));
                    } catch (_) {
                        return value;
                    }
                };

                const encodePresetStoragePayload = (storage) => {
                    try {
                        const json = JSON.stringify(clonePlainData(storage) || { presets: [] });
                        const utf8 = encodeURIComponent(json).replace(/%([0-9A-F]{2})/g, (_, hex) =>
                            String.fromCharCode(parseInt(hex, 16))
                        );
                        return {
                            __type: 'encoded_preset_storage',
                            version: PRESET_STORAGE_VERSION,
                            data: toBase64Url(btoa(utf8))
                        };
                    } catch (e) {
                        console.error('[预设] 编码预设存储失败:', e);
                        return { presets: [] };
                    }
                };

                const decodePresetStoragePayload = (stored) => {
                    if (!stored || typeof stored !== 'object') return null;
                    if (stored.__type !== 'encoded_preset_storage' || !stored.data) return null;

                    const tryDecode = (base64Payload) => {
                        const binary = atob(base64Payload);
                        const json = decodeURIComponent(Array.from(binary, ch =>
                            '%' + ch.charCodeAt(0).toString(16).padStart(2, '0')
                        ).join(''));
                        const parsed = JSON.parse(json);
                        return parsed && Array.isArray(parsed.presets) ? parsed : null;
                    };

                    const version = stored.version || '';
                    const raw = String(stored.data || '');
                    const candidates = version === 'base64url-json-v1'
                        ? [fromBase64Url(raw), raw] // 优先按 base64url 解码，失败则再尝试直接 atob
                        : [raw, fromBase64Url(raw)]; // 兼容旧版 base64-json-v1（含 = + /）以及宿主可能的转义/清洗

                    for (const candidate of candidates) {
                        if (!candidate) continue;
                        try {
                            const decoded = tryDecode(candidate);
                            if (decoded) return decoded;
                        } catch (_) { }
                    }

                    console.warn('[预设] 解码预设存储失败，将回退为空存储');
                    return { presets: [] };
                };

                // 从角色卡变量读取预设存储
                const readPresetStorage = () => {
                    try {
                        const vars = getVariables({ type: 'character' });
                        const stored = vars?.[PRESET_STORAGE_KEY];
                        const decoded = decodePresetStoragePayload(stored);
                        if (decoded) return decoded;
                        if (stored && Array.isArray(stored.presets)) return stored;
                    } catch (e) {
                        console.warn('[预设] 读取角色卡变量失败，返回空存储:', e);
                    }
                    return { presets: [] };
                };

                // 写入预设存储到角色卡变量
                const writePresetStorage = (storage) => {
                    try {
                        const safePayload = encodePresetStoragePayload(storage);
                        insertOrAssignVariables({ [PRESET_STORAGE_KEY]: safePayload }, { type: 'character' });
                        console.log('✅ 预设存储已保存到角色卡变量');
                    } catch (e) {
                        console.error('[预设] 保存预设存储失败:', e);
                    }
                };

                // 加载预设列表（含 localStorage 迁移）
                const loadPresetList = () => {
                    const storage = readPresetStorage();

                    // 迁移旧 localStorage 数据
                    try {
                        const oldKey = 'rpg_character_presets';
                        const oldData = localStorage.getItem(oldKey);
                        if (oldData) {
                            const oldPresets = JSON.parse(oldData);
                            if (Array.isArray(oldPresets) && oldPresets.length > 0) {
                                const existingNames = new Set(storage.presets.map(p => p.name));
                                let migrated = 0;
                                for (const p of oldPresets) {
                                    if (!existingNames.has(p.name)) {
                                        storage.presets.push({
                                            ...p,
                                            createdAt: p.createdAt || p.timestamp || Date.now(),
                                            updatedAt: p.updatedAt || p.timestamp || Date.now()
                                        });
                                        migrated++;
                                    }
                                }
                                if (migrated > 0) {
                                    writePresetStorage(storage);
                                    console.log(`✅ 已从 localStorage 迁移 ${migrated} 个预设到角色卡变量`);
                                }
                                localStorage.removeItem(oldKey);
                                console.log('[预设] 已清理旧 localStorage 数据');
                            }
                        }
                    } catch (e) {
                        console.warn('[预设] localStorage 迁移失败（不影响使用）:', e);
                    }

                    // 将旧的原始对象存储重写为安全的编码格式，避免嵌入页遇到特殊字符时脚本解析异常
                    try {
                        writePresetStorage(storage);
                    } catch (e) {
                        console.warn('[预设] 安全重写预设存储失败（不影响当前使用）:', e);
                    }

                    presetList.value = storage.presets.sort((a, b) => (b.updatedAt || b.timestamp || 0) - (a.updatedAt || a.timestamp || 0));
                };

                // 保存预设列表到角色卡变量
                const savePresetList = () => {
                    const storage = readPresetStorage();
                    storage.presets = presetList.value;
                    writePresetStorage(storage);
                };

                // 收集当前配置（动态收集，适应字段变化）
                const collectCurrentConfig = () => {
                    return {
                        // 基础信息
                        name: character.name,
                        gender: character.gender,
                        age: character.age,
                        race: character.race,
                        identity: character.identity,
                        avatar: character.avatar,
                        attributes: { ...character.attributes },
                        backstory: character.backstory,
                        // 出生等级 & 出生点
                        selectedLevelMode: selectedLevelMode.value,
                        selectedCustomLevel: selectedCustomLevel.value,
                        selectedSpawnPoint: selectedSpawnPoint.value,
                        selectedAmberSpawn: selectedAmberSpawn.value ? cloneJson(selectedAmberSpawn.value) : null,
                        selectedJiuzhouSpawn: selectedJiuzhouSpawn.value ? cloneJson(selectedJiuzhouSpawn.value) : null,
                        selectedDragonSpawn: selectedDragonSpawn.value ? cloneJson(selectedDragonSpawn.value) : null,
                        selectedJiuzhouSect: selectedJiuzhouSect.value,
                        // 职业相关
                        class: character.class,
                        selectedBaseClass: selectedBaseClass.value,
                        // 自定义职业
                        customClassName: customClassName.value,
                        customClassStyle: customClassStyle.value,
                        customClassWeapon: customClassWeapon.value,
                        customClassCombatStyle: customClassCombatStyle.value,
                        // 技能树（如果已生成）
                        skillTree: skillTreeData.value ? JSON.parse(JSON.stringify(skillTreeData.value)) : null,
                        skillTreeForClass: skillTreeForClass.value,
                        lockedSkillMap: cloneJson(lockedSkillMap.value),
                        skillFlavorInput: skillFlavorInput.value,
                        // 队友
                        teammates: character.teammates.map(t => ({ id: t.id })),
                        // 自定义队友
                        customTeammate: customTeammate.enabled ? {
                            enabled: true,
                            name: customTeammate.name,
                            gender: customTeammate.gender,
                            race: customTeammate.race,
                            affinity: customTeammate.affinity,
                            oath: customTeammate.oath,
                            appearance: customTeammate.appearance,
                            outfit: customTeammate.outfit,
                            background: customTeammate.background,
                            attributes: { ...customTeammate.attributes },
                            equipment: customTeammate.equipment.map(e => ({ ...e, bonuses: { ...e.bonuses } })),
                            skills: customTeammate.skills.map(s => ({ ...s })),
                            combo: { ...customTeammate.combo }
                        } : null,
                        // 特质
                        selectedTraits: character.selectedTraits.map(t => t.name),
                        // 自定义特质（数组）
                        customTraits: customTraits.map(t => ({ name: t.name, effect: t.effect })),
                        // 自定义专长（数组）
                        customExpertise: customExpertise.map(t => ({ name: t.name, effect: t.effect })),
                        // 自定义出身背景
                        customIdentity: customIdentity.enabled ? {
                            enabled: true,
                            name: customIdentity.name,
                            desc: customIdentity.desc,
                            cardExpanded: !!customIdentity.cardExpanded,
                            tierIndex: customIdentity.tierIndex
                        } : null,
                        starterShopSelection: starterShopSelection.value.slice(),
                        // 开局选择
                        selectedWorldview: selectedWorldview.value,
                        selectedOpening: selectedOpening.value,
                        customOpeningText: customOpeningText.value,
                        selectedCombatValueMode: currentOpeningCombatValueMode.value,
                        selectedDifficulty: effectiveDifficultyKey.value,
                        customRace: customRace.enabled ? {
                            enabled: true,
                            name: customRace.name,
                            trait1: customRace.trait1,
                            trait2: customRace.trait2
                        } : null,
                        buildReview: buildReviewResult.value ? {
                            version: BUILD_REVIEW_RUBRIC_VERSION,
                            result: cloneJson(buildReviewResult.value),
                            fingerprint: buildReviewReviewedFingerprint.value,
                            bonusRP: buildReviewBonusRP.value,
                            bonusAttributePoints: buildReviewBonusAttributePoints.value
                        } : null
                    };
                };

                // 应用配置到当前状态
                const applyConfig = (config) => {
                    if (!config) return;
                    buildReviewBonusRP.value = 0;
                    buildReviewBonusAttributePoints.value = 0;
                    buildReviewResult.value = null;
                    buildReviewError.value = '';
                    buildReviewReviewedFingerprint.value = '';
                    buildReviewStale.value = false;

                    const detectedPresetMode = detectPresetModeFromConfig(config);
                    // 普通导入预设默认进入自定义创建流，避免退回角色选择页
                    presetMode.value = detectedPresetMode || 'custom';
                    presetSubPage.value = false;
                    selectedPresetChar.value = null;

                    // 基础信息
                    if (config.name !== undefined) character.name = config.name;
                    if (config.gender !== undefined) character.gender = config.gender;
                    if (config.age !== undefined) character.age = config.age;
                    if (config.race !== undefined) character.race = config.race;
                    if (config.identity !== undefined) character.identity = config.identity;
                    if (config.avatar !== undefined) character.avatar = config.avatar;
                    if (config.attributes) {
                        Object.assign(character.attributes, config.attributes);
                    }
                    if (config.backstory !== undefined) character.backstory = config.backstory;

                    // 出生等级 & 出生点
                    if (config.selectedLevelMode !== undefined) selectedLevelMode.value = config.selectedLevelMode;
                    if (config.selectedCustomLevel !== undefined) selectedCustomLevel.value = config.selectedCustomLevel;
                    if (config.selectedSpawnPoint !== undefined) selectedSpawnPoint.value = config.selectedSpawnPoint;
                    if (config.selectedAmberSpawn !== undefined) {
                        const restoredAmberSpawn = normalizeCommonSpawnSelection(config.selectedAmberSpawn);
                        if (!trySetAmberSpawnSelection(restoredAmberSpawn, { silent: true, source: '预设' })) {
                            selectedAmberSpawn.value = null;
                            if (isAmberWorldview.value) selectedSpawnPoint.value = null;
                        }
                    }
                    if (config.selectedJiuzhouSpawn !== undefined) {
                        const restoredJiuzhouSpawn = normalizeCommonSpawnSelection(config.selectedJiuzhouSpawn);
                        if (!trySetJiuzhouSpawnSelection(restoredJiuzhouSpawn, { silent: true, source: '预设' })) {
                            selectedJiuzhouSpawn.value = null;
                            if (isJiuzhouWorldview.value) selectedSpawnPoint.value = null;
                        }
                    }
                    if (config.selectedDragonSpawn !== undefined) {
                        const restoredDragonSpawn = normalizeCommonSpawnSelection(config.selectedDragonSpawn);
                        if (!trySetDragonSpawnSelection(restoredDragonSpawn, { silent: true, source: '预设' })) {
                            selectedDragonSpawn.value = null;
                            if (isDragonWorldview.value) selectedSpawnPoint.value = null;
                        }
                    }
                    if (config.selectedJiuzhouSect !== undefined) {
                        const nextSectId = String(config.selectedJiuzhouSect || '').trim();
                        selectedJiuzhouSect.value = jiuzhouSectOptions.value.some(sect => sect.id === nextSectId) ? nextSectId : '';
                    }

                    // 职业相关
                    if (config.selectedBaseClass !== undefined) {
                        selectedBaseClass.value = config.selectedBaseClass;
                    }
                    if (config.class !== undefined) character.class = config.class;

                    // 自定义职业
                    if (config.customClassName !== undefined) customClassName.value = config.customClassName;
                    if (config.customClassStyle !== undefined) customClassStyle.value = config.customClassStyle;
                    if (config.customClassWeapon !== undefined) customClassWeapon.value = config.customClassWeapon;
                    if (config.customClassCombatStyle !== undefined) customClassCombatStyle.value = config.customClassCombatStyle;

                    // 技能树
                    if (config.skillTree) {
                        skillTreeData.value = config.skillTree;
                        skillTreeForClass.value = config.skillTreeForClass || config.class; // 兼容旧预设
                        const warnClass = skillTreeForClass.value || character.class;
                        if (warnClass) {
                            setClassSkillSoftWarnings(warnClass, buildSkillSoftWarningsForTree(skillTreeData.value));
                        }
                    }
                    if (config.lockedSkillMap && typeof config.lockedSkillMap === 'object') {
                        lockedSkillMap.value = cloneJson(config.lockedSkillMap) || {};
                    } else {
                        lockedSkillMap.value = {};
                    }
                    if (config.skillFlavorInput !== undefined) {
                        skillFlavorInput.value = config.skillFlavorInput;
                    }

                    // 队友（需要从mockData中查找完整数据）
                    if (config.teammates && Array.isArray(config.teammates)) {
                        character.teammates = config.teammates
                            .map(t => {
                                if (t.id === '__custom__') return { id: '__custom__', name: '自定义队友', cost: CUSTOM_TEAMMATE_COST, isCustom: true };
                                const presetMate = getPresetCompanionById(t.id);
                                if (presetMate) return presetMate;
                                return mockData.teammates.find(m => m.id === t.id);
                            })
                            .filter(Boolean);
                    }

                    // 自定义队友恢复
                    if (config.customTeammate && config.customTeammate.enabled) {
                        customTeammate.enabled = true;
                        customTeammate.name = config.customTeammate.name || '';
                        customTeammate.gender = config.customTeammate.gender || '女';
                        customTeammate.race = config.customTeammate.race || '人类种';
                        customTeammate.affinity = config.customTeammate.affinity ?? 50;
                        customTeammate.oath = config.customTeammate.oath || false;
                        customTeammate.appearance = config.customTeammate.appearance || '';
                        customTeammate.outfit = config.customTeammate.outfit || '';
                        customTeammate.background = config.customTeammate.background || '';
                        if (config.customTeammate.attributes) Object.assign(customTeammate.attributes, config.customTeammate.attributes);
                        customTeammate.equipment.splice(0);
                        (config.customTeammate.equipment || []).forEach(e => customTeammate.equipment.push({ ...e, bonuses: { ...e.bonuses } }));
                        customTeammate.skills.splice(0);
                        (config.customTeammate.skills || []).forEach(s => customTeammate.skills.push({ quality: '普通', ...s }));
                        if (config.customTeammate.combo) Object.assign(customTeammate.combo, { quality: '普通', ...config.customTeammate.combo });
                    } else {
                        customTeammate.enabled = false;
                    }
                    syncCustomTeammateProxy();

                    // 特质（从traitsData中查找完整数据）
                    if (config.selectedTraits && Array.isArray(config.selectedTraits)) {
                        character.selectedTraits = config.selectedTraits
                            .map(name => traitsData.find(t => t.name === name))
                            .filter(Boolean);
                    }

                    // 自定义特质（支持数组和旧格式兼容）
                    customTraits.length = 0; // 清空数组
                    if (config.customTraits && Array.isArray(config.customTraits)) {
                        config.customTraits.forEach(t => {
                            customTraits.push({ name: t.name || '', effect: t.effect || '' });
                        });
                    } else if (config.customTrait) {
                        // 兼容旧格式
                        customTraits.push({ name: config.customTrait.name || '', effect: config.customTrait.effect || '' });
                    }

                    // 自定义专长
                    customExpertise.length = 0;
                    if (config.customExpertise && Array.isArray(config.customExpertise)) {
                        config.customExpertise.forEach(t => {
                            customExpertise.push({ name: t.name || '', effect: t.effect || '' });
                        });
                    }

                    // 自定义出身背景（预设固定出身已移除，自定义出身始终启用）
                    customIdentity.enabled = true;
                    character.identity = '__custom__';
                    if (config.customIdentity) {
                        customIdentity.name = config.customIdentity.name || '自定义出身';
                        customIdentity.desc = config.customIdentity.desc || '';
                        customIdentity.cardExpanded = config.customIdentity.cardExpanded !== undefined
                            ? !!config.customIdentity.cardExpanded
                            : !!config.customIdentity.tierPanelEnabled;
                        customIdentity.tierIndex = config.customIdentity.tierIndex || 0;
                    } else {
                        customIdentity.name = '自定义出身';
                        customIdentity.desc = '';
                        customIdentity.cardExpanded = false;
                        customIdentity.tierIndex = 0;
                    }

                    if (config.starterShopSelection && Array.isArray(config.starterShopSelection)) {
                        starterShopSelection.value = config.starterShopSelection
                            .map(id => String(id || '').trim())
                            .filter(Boolean);
                    } else {
                        starterShopSelection.value = [];
                    }

                    // 开局选择
                    if (config.selectedWorldview !== undefined) {
                        selectedWorldview.value = normalizeWorldviewId(config.selectedWorldview);
                    } else if (config.selectedOpening !== undefined) {
                        const inferredWorldview = openingOptions.value.find(opt => opt.id === config.selectedOpening)?.worldviewId || WORLDVIEW_CORRIDOR_ID;
                        selectedWorldview.value = normalizeWorldviewId(inferredWorldview);
                    } else if (!selectedWorldview.value) {
                        selectedWorldview.value = WORLDVIEW_CORRIDOR_ID;
                    }
                    if (config.selectedOpening !== undefined) selectedOpening.value = config.selectedOpening;
                    selectedOpening.value = normalizeOpeningForWorldview(selectedWorldview.value, selectedOpening.value);
                    if (config.customOpeningText !== undefined) customOpeningText.value = config.customOpeningText;
                    if (config.selectedCombatValueMode !== undefined) {
                        selectedCombatValueMode.value = normalizeCombatValueMode(config.selectedCombatValueMode);
                    }
                    if (config.selectedDifficulty !== undefined) {
                        selectedDifficulty.value = normalizeDifficultyKeyForMode(config.selectedDifficulty, currentOpeningCombatValueMode.value);
                    }
                    if (config.customRace) {
                        customRace.enabled = config.customRace.enabled;
                        customRace.name = config.customRace.name || '';
                        Object.assign(customRace.trait1, normalizeCustomRaceTrait(config.customRace.trait1));
                        Object.assign(customRace.trait2, normalizeCustomRaceTrait(config.customRace.trait2));
                        if (customRace.enabled) character.race = '__custom__';
                    } else {
                        customRace.enabled = false;
                        customRace.name = '';
                        Object.assign(customRace.trait1, { name: '', detail: '', negative: false });
                        Object.assign(customRace.trait2, { name: '', detail: '', negative: false });
                    }

                    if (config.buildReview?.result && Number(config.buildReview.version) === BUILD_REVIEW_RUBRIC_VERSION) {
                        buildReviewResult.value = cloneJson(config.buildReview.result);
                        buildReviewReviewedFingerprint.value = String(config.buildReview.fingerprint || '');
                        const reviewMatchesCurrentBuild = !!buildReviewReviewedFingerprint.value
                            && buildReviewReviewedFingerprint.value === buildReviewFingerprint.value;
                        buildReviewStale.value = !reviewMatchesCurrentBuild;
                        const savedReviewRewardClaimed = Number(config.buildReview.bonusRP || 0) >= 10
                            && Number(config.buildReview.bonusAttributePoints || 0) >= 2;
                        if (!isPresetChar.value && (savedReviewRewardClaimed || Number(buildReviewResult.value?.总分 || 0) >= 60)) {
                            // 已达标的存档即使构筑指纹或后续评议分数已变化，也恢复其已领取奖励。
                            buildReviewBonusRP.value = 10;
                            buildReviewBonusAttributePoints.value = 2;
                        }
                    }
                };

