                    const name = newPresetName.value.trim();
                    if (!name) return;

                    const now = Date.now();
                    const config = collectCurrentConfig();
                    const existingIndex = presetList.value.findIndex(p => p.name === name);

                    if (existingIndex >= 0) {
                        // 覆盖已有预设
                        presetList.value[existingIndex] = {
                            ...presetList.value[existingIndex],
                            data: config,
                            updatedAt: now
                        };
                        console.log('[预设] 已更新:', name);
                    } else {
                        // 新建预设
                        presetList.value.unshift({
                            id: now.toString(),
                            name: name,
                            timestamp: now,
                            createdAt: now,
                            updatedAt: now,
                            data: config
                        });
                        console.log('[预设] 已保存:', name);
                    }

                    savePresetList();
                    newPresetName.value = '';
                };

                // 加载预设
                const loadPreset = (preset) => {
                    if (!preset?.data) return;

                    applyConfig(preset.data);
                    showPresetModal.value = false;
                    console.log('[预设] 已加载:', preset.name);
                };

                // 删除预设
                const deletePreset = (id) => {
                    const index = presetList.value.findIndex(p => p.id === id);
                    if (index >= 0) {
                        const name = presetList.value[index].name;
                        presetList.value.splice(index, 1);
                        savePresetList();
                        console.log('[预设] 已删除:', name);
                    }
                };

