                const AMBER_BLOCKED_SPAWN_TYPE_LABELS = new Set(['遗迹', '势力', '传送门', '神殿']);

                function normalizeAmberSpawnSelection(rawSpawn) {
                    if (!rawSpawn || typeof rawSpawn !== 'object') return null;
                    const name = String(rawSpawn.名称 || rawSpawn.name || rawSpawn.场所 || '').trim();
                    if (!name) return null;
                    const parsedLayer = Number(rawSpawn.地图层级);
                    const tier = String(rawSpawn.层级 || rawSpawn.区域 || '').trim();
                    return {
                        名称: name,
                        大陆: String(rawSpawn.大陆 || '').trim(),
                        区域: name,
                        场所: name,
                        层级: tier,
                        地区等级: String(rawSpawn.地区等级 || rawSpawn.危险等级 || '').trim(),
                        危险等级: String(rawSpawn.危险等级 || rawSpawn.地区等级 || '').trim(),
                        地貌特征: String(rawSpawn.地貌特征 || '').trim(),
                        聚落描述: String(rawSpawn.聚落描述 || '').trim(),
                        周边威胁: String(rawSpawn.周边威胁 || '').trim(),
                        地点类型: String(rawSpawn.地点类型 || '').trim(),
                        节点ID: String(rawSpawn.节点ID || '').trim(),
                        地图层级: Number.isFinite(parsedLayer) ? parsedLayer : 0
                    };
                }

                function getAmberSpawnBlockedReason(rawSpawn) {
                    const normalized = normalizeAmberSpawnSelection(rawSpawn) || normalizeCommonSpawnSelection(rawSpawn);
                    if (!normalized) return '';
                    const nodeId = String(normalized.节点ID || rawSpawn?.节点ID || '').trim();
                    if (nodeId && AMBER_BLOCKED_SPAWN_IDS.has(nodeId)) {
                        return '海姆冥界附近过于危险，不能作为初始出生点。';
                    }
                    const rawTypeKey = String(rawSpawn?.type || rawSpawn?.类型 || '').trim().toLowerCase();
                    const typeLabel = String(normalized.地点类型 || rawSpawn?.地点类型 || '').trim();
                    if ((rawTypeKey && AMBER_BLOCKED_SPAWN_TYPE_KEYS.has(rawTypeKey)) || (typeLabel && AMBER_BLOCKED_SPAWN_TYPE_LABELS.has(typeLabel))) {
                        return `“${typeLabel || rawTypeKey}”类型地点不能作为初始出生点。`;
                    }
                    const areaTexts = [normalized.大陆, normalized.区域, normalized.层级].filter(Boolean);
                    if (areaTexts.some(text => String(text).includes('元素界'))) {
                        return '元素界相关地点不能作为初始出生点。';
                    }
                    const haystacks = [
                        normalized.名称,
                        normalized.大陆,
                        normalized.区域,
                        normalized.场所,
                        normalized.层级,
                        normalized.聚落描述,
                        normalized.地貌特征,
                        normalized.周边威胁
                    ].filter(Boolean);
                    const hitKeyword = AMBER_BLOCKED_SPAWN_KEYWORDS.find(keyword => haystacks.some(text => String(text).includes(keyword)));
                    return hitKeyword ? '海姆冥界附近过于危险，不能作为初始出生点。' : '';
                }

                function normalizeCommonSpawnSelection(rawSpawn) {
                    if (!rawSpawn || typeof rawSpawn !== 'object') return null;
                    const name = String(rawSpawn.名称 || rawSpawn.name || rawSpawn.场所 || '').trim();
                    if (!name) return null;
                    const levelRange = rawSpawn.levelRange ?? rawSpawn.地区等级 ?? '';
                    return {
                        名称: name,
                        大陆: String(rawSpawn.大陆 || '').trim(),
                        区域: String(rawSpawn.区域 || '').trim(),
                        场所: String(rawSpawn.场所 || name).trim(),
                        层级: String(rawSpawn.层级 || rawSpawn.tier || '').trim(),
                        地区等级: typeof levelRange === 'number' ? levelRange : String(levelRange).trim(),
                        危险等级: String(rawSpawn.危险等级 || '').trim(),
                        地貌特征: String(rawSpawn.地貌特征 || '').trim(),
                        聚落描述: String(rawSpawn.聚落描述 || rawSpawn.desc || '').trim(),
                        周边威胁: String(rawSpawn.周边威胁 || '').trim(),
                        地点类型: String(rawSpawn.type || rawSpawn.地点类型 || '').trim(),
                        节点ID: String(rawSpawn.节点ID || '').trim(),
                        地图层级: Number.isFinite(Number(rawSpawn.地图层级)) ? Number(rawSpawn.地图层级) : null
                    };
                }

                function normalizeDragonSpawnSelection(rawSpawn) {
                    const normalized = normalizeCommonSpawnSelection(rawSpawn);
                    return normalized ? { ...normalized, 大陆: '现代世界' } : null;
                }

                const DRAGON_BLOCKED_SPAWN_IDS = new Set([
                    'otherspace_rain_train',
                    'otherspace_tokoyo',
                    'otherspace_nibelungen',
                    'otherspace_dreamcorridor',
                    'otherspace_thriller_paradise',
                    'nest_odin'
                ]);

                function getDragonSpawnBlockedReason(rawSpawn) {
                    const normalized = normalizeDragonSpawnSelection(rawSpawn);
                    if (!normalized) return '';
                    const nodeId = String(normalized.节点ID || '').trim();
                    const blockedId = Array.from(DRAGON_BLOCKED_SPAWN_IDS).find(id => nodeId === id || nodeId.startsWith(`${id}_scene_`));
                    if (!blockedId) return '';
                    if (blockedId === 'nest_odin') return '奥丁之渊无法作为初始出生点。';
                    return '该地点属于特异空间，无法作为初始出生点。';
                }
                function trySetDragonSpawnSelection(rawSpawn, options = {}) {
                    const { silent = false, source = '地图' } = options;
                    const normalized = normalizeDragonSpawnSelection(rawSpawn);
                    if (!normalized) return false;
                    const blockedReason = getDragonSpawnBlockedReason(normalized);
                    if (blockedReason) {
                        if (selectedDragonSpawn.value?.名称 === normalized.名称) {
                            selectedDragonSpawn.value = null;
                            selectedSpawnPoint.value = null;
                        }
                        console.warn(`[龙族出生点] 已拦截${source}选择: ${normalized.名称}，原因: ${blockedReason}`);
                        if (!silent) {
                            alert(`"${normalized.名称}" 不能作为出生点。\n${blockedReason}`);
                        }
                        return false;
                    }
                    selectedDragonSpawn.value = normalized;
                    selectedSpawnPoint.value = normalized.名称;
                    return true;
                }

                function getEffectiveDragonSpawn() {
                    if (!isDragonWorldview.value) return null;
                    if (isDragonHighSchoolOrigin.value || selectedOpening.value === DRAGON_HIGH_SCHOOL_OPENING_ID) {
                        return normalizeDragonSpawnSelection(DRAGON_SHILAN_SPAWN);
                    }
                    return normalizeDragonSpawnSelection(selectedDragonSpawn.value);
                }

                function applyDragonSpawnSelection(rawSpawn) {
                    if (isDragonHighSchoolOrigin.value || selectedOpening.value === DRAGON_HIGH_SCHOOL_OPENING_ID) {
                        return trySetDragonSpawnSelection(DRAGON_SHILAN_SPAWN, { silent: true, source: '仕兰高中特殊开局' });
                    }
                    return trySetDragonSpawnSelection(rawSpawn, { source: '地图' });
                }

                function trySetAmberSpawnSelection(rawSpawn, options = {}) {
                    const { silent = false, source = '地图' } = options;
                    const normalized = normalizeAmberSpawnSelection(rawSpawn);
                    if (!normalized) return false;
                    const blockedReason = getAmberSpawnBlockedReason(normalized);
                    if (blockedReason) {
                        if (selectedAmberSpawn.value?.名称 === normalized.名称) {
                            selectedAmberSpawn.value = null;
                            selectedSpawnPoint.value = null;
                        }
                        console.warn(`[琥珀出生点] 已拦截${source}选择: ${normalized.名称}，原因: ${blockedReason}`);
                        if (!silent) {
                            alert(`"${normalized.名称}" 不能作为出生点。\n${blockedReason}`);
                        }
                        return false;
                    }
                    selectedAmberSpawn.value = normalized;
                    selectedSpawnPoint.value = normalized.名称;
                    return true;
                }

                function getEffectiveAmberSpawn() {
                    if (!isAmberWorldview.value) return null;
                    if (selectedOpening.value === 'amber_arrival') {
                        return normalizeAmberSpawnSelection(DEFAULT_AMBER_SPAWN);
                    }
                    if (selectedOpening.value === 'amber_nightmare') {
                        return normalizeAmberSpawnSelection(DEFAULT_AMBER_BAIMA_SPAWN);
                    }
                    return normalizeCommonSpawnSelection(selectedAmberSpawn.value);
                }

                function applyAmberSpawnSelection(rawSpawn) {
                    if (selectedOpening.value === 'amber_arrival') {
                        return trySetAmberSpawnSelection(DEFAULT_AMBER_SPAWN, { silent: true, source: '血与火的序章' });
                    }
                    if (selectedOpening.value === 'amber_nightmare') {
                        return trySetAmberSpawnSelection(DEFAULT_AMBER_BAIMA_SPAWN, { silent: true, source: '明焰与梦魇' });
                    }
                    return trySetAmberSpawnSelection(rawSpawn, { source: '地图' });
                }

                // ==================== 大明志异（两京九州）地图出生点 ====================
                const JIUZHOU_BLOCKED_SPAWN_TYPES = new Map([
                    ['sect', '门派驻地不可作为出生点，请先选择城镇、关隘、港口、村落或野外地点；门派请在下方单独选择。'],
                    ['faction', '法尸禁地是敌对污染区，不能作为出生点。']
                ]);

                function normalizeJiuzhouSpawnSelection(rawSpawn) {
                    if (!rawSpawn || typeof rawSpawn !== 'object') return null;
                    const name = String(rawSpawn.名称 || rawSpawn.name || rawSpawn.场所 || '').trim();
                    if (!name) return null;
                    const tier = String(rawSpawn.层级 || rawSpawn.区域 || rawSpawn.tier || '').trim();
                    const danger = String(rawSpawn.地区等级 || rawSpawn.危险等级 || rawSpawn.dangerLevel || '').trim();
                    return {
                        名称: name,
                        大陆: String(rawSpawn.大陆 || '九州').trim() || '九州',
                        区域: name,
                        场所: name,
                        层级: tier,
                        地区等级: danger,
                        危险等级: danger,
                        地貌特征: String(rawSpawn.地貌特征 || rawSpawn.landscape || '').trim(),
                        聚落描述: String(rawSpawn.聚落描述 || rawSpawn.summary || '').trim(),
                        周边威胁: String(rawSpawn.周边威胁 || rawSpawn.threats || '').trim(),
                        门派专长: String(rawSpawn.specialty || rawSpawn.methods || '').trim(),
                        原始地点类型: String(rawSpawn.type || '').trim(),
                        地点类型: String(rawSpawn.地点类型 || rawSpawn.type || '').trim(),
                        节点ID: String(rawSpawn.节点ID || rawSpawn.id || '').trim(),
                        地图层级: 0
                    };
                }

                function getJiuzhouSpawnBlockedReason(spawn) {
                    if (!spawn) return '';
                    return JIUZHOU_BLOCKED_SPAWN_TYPES.get(spawn.原始地点类型 || spawn.地点类型) || '';
                }

                function trySetJiuzhouSpawnSelection(rawSpawn, options = {}) {
                    const { silent = false, source = '地图' } = options;
                    const normalized = normalizeJiuzhouSpawnSelection(rawSpawn);
                    if (!normalized) return false;
                    const blockedReason = getJiuzhouSpawnBlockedReason(normalized);
                    if (blockedReason) {
                        if (selectedJiuzhouSpawn.value?.名称 === normalized.名称) {
                            selectedJiuzhouSpawn.value = null;
                            selectedSpawnPoint.value = null;
                        }
                        console.warn(`[大明志异出生点] 已拦截${source}选择: ${normalized.名称}，原因: ${blockedReason}`);
                        if (!silent) {
                            alert(`"${normalized.名称}" 不能作为出生点。\n${blockedReason}`);
                        }
                        return false;
                    }
                    selectedJiuzhouSpawn.value = normalized;
                    selectedSpawnPoint.value = normalized.名称;
                    return true;
                }

                function getEffectiveJiuzhouSpawn() {
                    if (!isJiuzhouWorldview.value) return null;
                    if (selectedOpening.value === JIUZHOU_YUAN_MARRIAGE_OPENING_ID) {
                        return normalizeCommonSpawnSelection(DEFAULT_JIUZHOU_LUOJING_SPAWN);
                    }
                    if (selectedOpening.value === JIUZHOU_FU_INLAW_OPENING_ID) {
                        return normalizeCommonSpawnSelection(DEFAULT_JIUZHOU_JIANGNING_SPAWN);
                    }
                    return normalizeCommonSpawnSelection(selectedJiuzhouSpawn.value);
                }

                function applyJiuzhouSpawnSelection(rawSpawn) {
                    if (selectedOpening.value === JIUZHOU_YUAN_MARRIAGE_OPENING_ID) {
                        return trySetJiuzhouSpawnSelection(DEFAULT_JIUZHOU_LUOJING_SPAWN, { silent: true, source: '袁府姻缘开局' });
                    }
                    if (selectedOpening.value === JIUZHOU_FU_INLAW_OPENING_ID) {
                        return trySetJiuzhouSpawnSelection(DEFAULT_JIUZHOU_JIANGNING_SPAWN, { silent: true, source: '傅府赘婿开局' });
                    }
                    return trySetJiuzhouSpawnSelection(rawSpawn, { source: '地图' });
                }

                function normalizeJiuzhouSect(rawSect) {
                    if (!rawSect || typeof rawSect !== 'object') return null;
                    const type = String(rawSect.type || '').trim().toLowerCase();
                    if (type !== 'sect') return null;
                    const id = String(rawSect.id || '').trim();
                    const name = String(rawSect.name || '').trim();
                    if (!id || !name) return null;
                    return {
                        id,
                        name,
                        tier: String(rawSect.tier || '').trim(),
                        dangerLevel: String(rawSect.dangerLevel || '').trim(),
                        summary: String(rawSect.summary || '').trim(),
                        footprint: String(rawSect.footprint || '').trim(),
                        publicFace: String(rawSect.publicFace || '').trim(),
                        methods: String(rawSect.methods || rawSect.specialty || '').trim(),
                        role: String(rawSect.role || '').trim(),
                        relationToState: String(rawSect.relationToState || '').trim()
                    };
                }

                const jiuzhouSectOptions = computed(() => jiuzhouSectNodes.value
                    .map(normalizeJiuzhouSect)
                    .filter(Boolean)
                    .sort((a, b) => a.name.localeCompare(b.name, 'zh-Hans-CN')));

                const selectedJiuzhouSectInfo = computed(() => (
                    jiuzhouSectOptions.value.find(sect => sect.id === selectedJiuzhouSect.value) || null
                ));
                const nearbyJiuzhouSectOptions = computed(() => {
                    if (!selectedJiuzhouSpawn.value || !jiuzhouSectOptions.value.length) return [];
                    const spawnNodeId = String(selectedJiuzhouSpawn.value?.节点ID || '').trim();
                    const graphNodes = Array.isArray(jiuzhouMapGraph.value?.nodes) ? jiuzhouMapGraph.value.nodes : [];
                    const graphEdges = Array.isArray(jiuzhouMapGraph.value?.edges) ? jiuzhouMapGraph.value.edges : [];
                    const sectMap = new Map(jiuzhouSectOptions.value.map(sect => [sect.id, sect]));
                    const collected = [];
                    const seen = new Set();

                    const pushSect = (sectId) => {
                        if (!sectId || seen.has(sectId)) return;
                        const sect = sectMap.get(sectId);
                        if (!sect) return;
                        seen.add(sectId);
                        collected.push(sect);
                    };

                    if (spawnNodeId) {
                        graphEdges.forEach(edge => {
                            const from = String(edge?.from || edge?.source || '').trim();
                            const to = String(edge?.to || edge?.target || '').trim();
                            if (!from || !to) return;
                            if (from === spawnNodeId) pushSect(to);
                            else if (to === spawnNodeId) pushSect(from);
                        });
                    }

                    if (collected.length > 0) return collected.slice(0, 6);

                    const nodeMap = new Map(graphNodes.map(node => [String(node?.id || '').trim(), node]));
                    const spawnNode = nodeMap.get(spawnNodeId);
                    if (!spawnNode) return jiuzhouSectOptions.value.slice(0, 6);
                    const sx = Number(spawnNode.x);
                    const sy = Number(spawnNode.y);
                    if (!Number.isFinite(sx) || !Number.isFinite(sy)) return jiuzhouSectOptions.value.slice(0, 6);

                    return jiuzhouSectOptions.value
                        .map(sect => {
                            const node = nodeMap.get(sect.id);
                            const dx = Number(node?.x) - sx;
                            const dy = Number(node?.y) - sy;
                            const distance = Number.isFinite(dx) && Number.isFinite(dy) ? Math.hypot(dx, dy) : Number.POSITIVE_INFINITY;
                            return { sect, distance };
                        })
                        .sort((a, b) => a.distance - b.distance)
                        .slice(0, 6)
                        .map(item => item.sect);
                });
                watch(jiuzhouSectOptions, (options) => {
                    if (!selectedJiuzhouSect.value) return;
                    if (!options.some(sect => sect.id === selectedJiuzhouSect.value)) {
                        selectedJiuzhouSect.value = '';
                    }
                }, { immediate: true });

                function setStartLevelMode(mode, level = null) {
                    selectedLevelMode.value = mode;
                    if (mode === 'custom' && level != null) {
                        setCustomStartLevel(level);
                    } else {
                        selectedCustomLevel.value = level;
                    }
                    if (!isAmberWorldview.value && !isJiuzhouWorldview.value && !isDragonWorldview.value) {
                        selectedSpawnPoint.value = null;
                    }
                }

                function setCustomStartLevel(level) {
                    let safeLevel = Math.max(1, Math.floor(Number(level) || 1));
                    if(isSolarisWorldview.value) safeLevel=Math.min(SOLARIS_MAX_START_LEVEL,safeLevel);
                    if (isJiuzhouWorldview.value) {
                        safeLevel = Math.min(JIUZHOU_MAX_START_LEVEL, safeLevel);
                    } else if (isDragonWorldview.value) {
                        safeLevel = Math.min(DRAGON_MAX_START_LEVEL, safeLevel);
                    } else if (isEarthseaWorldview.value) {
                        safeLevel = Math.min(EARTHSEA_MAX_START_LEVEL, safeLevel);
                    }
                    selectedCustomLevel.value = safeLevel;
                    if (!isAmberWorldview.value && !isJiuzhouWorldview.value && !isDragonWorldview.value) {
                        selectedSpawnPoint.value = null;
                    }
                }

                const normalizeAmberCampName = (campName) => {
                    const camp = String(campName || '').trim();
                    if (camp.includes('秩序')) return '秩序阵营';
                    if (camp.includes('中立')) return '中立阵营';
                    if (camp.includes('黄昏')) return '黄昏阵营';
                    return camp;
                };

                const toSafeAmberRaceList = (rawRacesByCamp) => {
                    if (!rawRacesByCamp || typeof rawRacesByCamp !== 'object') return [];
                    const normalized = [];
                    let rank = 1;
                    for (const [campName, races] of Object.entries(rawRacesByCamp)) {
                        if (!Array.isArray(races)) continue;
                        for (const race of races) {
                            if (!race || typeof race !== 'object') continue;
                            normalized.push({
                                name: String(race.name || `未命名种族${rank}`),
                                rank,
                                cost: 0,
                                startLevel: Math.max(1, Number(race.startLevel) || 1),
                                tier: Number(race.tier) || 1,
                                type: String(race.type || 'material'),
                                tierName: String(race.tierName || '未知'),
                                tierColor: String(race.tierColor || '#b2bec3'),
                                desc: String(race.desc || ''),
                                lore: String(race.lore || ''),
                                bonuses: {
                                    strength: Number(race?.bonuses?.strength) || 0,
                                    dexterity: Number(race?.bonuses?.dexterity) || 0,
                                    constitution: Number(race?.bonuses?.constitution) || 0,
                                    intelligence: Number(race?.bonuses?.intelligence) || 0,
                                    wisdom: Number(race?.bonuses?.wisdom) || 0,
                                    charisma: Number(race?.bonuses?.charisma) || 0
                                },
                                buffs: Array.isArray(race.buffs) ? race.buffs : [],
                                icon: String(race.icon || 'ri-user-line'),
                                camp: normalizeAmberCampName(campName)
                            });
                            rank += 1;
                        }
                    }
                    return normalized;
                };

                const amberWorldviewRaces = markRaw(
                    toSafeAmberRaceList(typeof amberSwordRaces !== 'undefined' ? amberSwordRaces : null)
                );
                const amberCampOrder = ['秩序阵营', '中立阵营', '黄昏阵营'];
                const amberRaceNamesByCamp = new Map(
                    amberCampOrder.map(camp => [
                        camp,
                        new Set(
                            Array.isArray(amberSwordRaces?.[camp])
                                ? amberSwordRaces[camp]
                                    .map(race => String(race?.name || '').trim())
                                    .filter(Boolean)
                                : []
                        )
                    ])
                );
                const getAmberCampByRace = (race) => {
                    const raceName = String(race?.name || '').trim();
                    for (const camp of amberCampOrder) {
                        if (amberRaceNamesByCamp.get(camp)?.has(raceName)) {
                            return camp;
                        }
                    }
                    return normalizeAmberCampName(race?.camp);
                };
                const jiuzhouWorldviewRaces = markRaw(
                    Array.isArray(typeof jiuzhouOrigins !== 'undefined' ? jiuzhouOrigins : null)
                        ? jiuzhouOrigins
                        : []
                );
                const jiuzhouRaceNameSet = new Set(
                    jiuzhouWorldviewRaces.map(race => String(race?.name || '').trim()).filter(Boolean)
                );
                const dragonWorldviewRaces = markRaw(
                    Array.isArray(typeof dragonRajaOrigins !== 'undefined' ? dragonRajaOrigins : null)
                        ? dragonRajaOrigins
                        : []
                );
                const earthseaWorldviewRaces = markRaw(
                    Array.isArray(typeof earthseaOrigins !== 'undefined' ? earthseaOrigins : null) ? earthseaOrigins : []
                );
                const earthseaRaceNameSet = new Set(earthseaWorldviewRaces.map(race => String(race?.name || '').trim()).filter(Boolean));
                const dragonRaceNameSet = new Set(
                    dragonWorldviewRaces.map(race => String(race?.name || '').trim()).filter(Boolean)
                );
                const availableRaces = computed(() => {
                    if (isSolarisWorldview.value) return solarisRaces;
                    if (isAmberWorldview.value && amberWorldviewRaces.length > 0) {
                        return amberWorldviewRaces;
                    }
                    if (isJiuzhouWorldview.value && jiuzhouWorldviewRaces.length > 0) {
                        return jiuzhouWorldviewRaces;
                    }
                    if (isDragonWorldview.value && dragonWorldviewRaces.length > 0) {
                        return dragonWorldviewRaces;
                    }
                    if (isEarthseaWorldview.value) return earthseaWorldviewRaces;
                    return mockData.races;
                });
                const amberRaceCampMap = computed(() => {
                    const campMap = new Map(amberCampOrder.map(camp => [camp, []]));

                    availableRaces.value.forEach(race => {
                        if (!race || race.disabled) return;
                        const campName = getAmberCampByRace(race);
                        if (!campMap.has(campName)) return;
                        campMap.get(campName).push(race);
                    });

                    return campMap;
                });
                const amberCampTabs = Object.freeze([
                    { key: '秩序阵营', title: '秩序阵营', desc: '文明疆域的捍卫者，为守护秩序的火种而战。' },
                    { key: '中立阵营', title: '中立阵营', desc: '没有任何阵营能完全信任你，但这也意味着整个世界都是你的舞台。' },
                    { key: '黄昏阵营', title: '黄昏阵营', desc: '化身魔物，迎接你的将是正义的利刃，准备好迎接厮杀了吗？(无法选择初始羁绊)' }
                ]);
                const amberRaceCampGroups = computed(() =>
                    amberCampTabs
                        .map(tab => ({
                            key: tab.key,
