                                    潮生泉眼: { 建设阶段: '专业', 核心设施: ['灵泉泉眼', '分流灌溉渠', '活水育苗池'], 功能: '滋养渔获并诱发海洋生物灵性，可供潮生灵泉相关能力使用。', 产出: '每7日形成一批受灵泉滋养的高品质海产或养殖种苗。', 下次产出日期: '开局后第7日' },
                                    岛屿码头: { 建设阶段: '基础', 核心设施: ['小型泊位', '冷藏仓', '维修棚'], 功能: '保障人员、渔获与补给往返，支持海底巡游前的整备。', 产出: '无固定资源产出；降低运输与出海准备成本。', 下次产出日期: '无' }
                                },
                                驻扎人员: { [owner]: '岛主兼渔场产权人' },
                                待办事件: ['为私人岛屿命名，并确认首批常驻雇员、船只与渔场经营方式。']
                            }
                        };
                    }
                    if (originName === '妖怪便利店夜班员') {
                        return {
                            name: '零点便利店',
                            value: {
                                类型: '店铺',
                                主体规模: 3,
                                所在地: `${location}附近城区`,
                                状态: '白天按普通便利店营业；零点后非人货架、夜班账目与特殊店规开始生效。',
                                建设序列: {
                                    日间卖场: { 建设阶段: '基础', 核心设施: ['普通货架', '收银台', '冷藏柜'], 功能: '维持普通便利店外观、日常客流与基础现金流。', 产出: '每日结算符合当地物价的小额营业收入。', 下次产出日期: '次日闭店后' },
                                    非人货架: { 建设阶段: '专业', 核心设施: ['零点货架', '异常商品储位', '禁忌价签'], 功能: '每次夜班生成3件异常商品库存，支持交易或由店员按店规购买自用。', 产出: '每次夜班根据交易结果获得情报、人情、异常货币或特殊商品。', 下次产出日期: '下一次夜班营业时' },
                                    员工通道: { 建设阶段: '进阶', 核心设施: ['跨店后门', '店规告示', '索赔清单'], 功能: '允许从仍在营业的便利店或深夜小卖部返回零点便利店，并执行店内保护与违规索赔。', 产出: '无固定物资产出；提供安全区、撤离路线与规则约束。', 下次产出日期: '无' }
                                },
                                驻扎人员: { [owner]: '产权人兼固定夜班员' },
                                待办事件: ['确认店铺正式地址与第一夜的非人货架库存。']
                            }
                        };
                    }
                    return null;
                }

                function applyDragonOpeningAssetRegistration(statData, originName, spawn, playerName) {
                    if (!statData || typeof statData !== 'object') return;
                    const nextAssets = (statData.核心资产 && typeof statData.核心资产 === 'object')
                        ? { ...statData.核心资产 }
                        : {};
                    DRAGON_OPENING_ASSET_NAMES.forEach(assetName => delete nextAssets[assetName]);
                    const registration = buildDragonOpeningAsset(originName, spawn, playerName);
                    if (registration) {
                        nextAssets[registration.name] = registration.value;
                    }
                    statData.核心资产 = nextAssets;
                }

                function buildDragonInitialProficiency(name) {
                    return {
                        阶位: '学徒',
                        进度: 0,
                        升阶阈值: 25,
                        效果: `${name}相关检定+1`
                    };
                }
                function applyDragonOriginMvuBonuses(person, originName) {
                    if (!person || !originName) return;
                    const normalizedOrigin = String(originName || '').trim();
                    if (!normalizedOrigin) return;

                    if (!person.熟练度 || typeof person.熟练度 !== 'object') {
                        person.熟练度 = {};
                    }
                    if (!person.熟练度.生活 || typeof person.熟练度.生活 !== 'object') {
                        person.熟练度.生活 = {};
                    }
                    if (!person.熟练度.战斗 || typeof person.熟练度.战斗 !== 'object') {
                        person.熟练度.战斗 = {};
                    }
                    if (!person.状态效果 || typeof person.状态效果 !== 'object') {
                        person.状态效果 = {};
                    }

                    if (normalizedOrigin === '我于万物之中') {
                        if (!person.熟练度.生活['克苏鲁神话']) {
                            person.熟练度.生活['克苏鲁神话'] = buildDragonInitialProficiency('克苏鲁神话');
                        }
                        person.状态效果['[SAN:100/100]'] = {
                            类型: 'BUFF',
                            持续时间: '永久',
                            属性影响: {},
                            特殊影响: '当前SAN为100，SAN上限为100。接触神话、禁忌真相、邪教仪式、不可名状事物，或学习和使用COC法术时，按[调查员理智]规则进行SAN检定与损失结算；状态名称中的数值必须随当前SAN同步更新。'
                        };
                    }

                    if (normalizedOrigin === '卡塞尔执行员' && !person.熟练度.战斗['屠龙术']) {
                        person.熟练度.战斗['屠龙术'] = buildDragonInitialProficiency('屠龙术');
                    }
                }

                const currentRaceDisplayBuffs = computed(() => {
                    if(isSolarisWorldview.value && currentRace.value){
 const origin=currentRace.value;
 const displayText={'刀剑精通':'熟悉刀剑的使用，出手迅捷而稳健。','枪械精通':'熟悉枪械的使用，瞄准沉着而精准。'};
 return [...(origin.buffs||[]),...(origin.initialTraits||[]).map(t=>({name:t.name,summary:displayText[t.name]||t.描述,detail:displayText[t.name]||t.描述,negative:(t.标签||[]).includes('负面')}))];
} 
                    if (isEarthseaWorldview.value && currentRace.value) {
                        const origin = currentRace.value;
                        return [
                            ...(origin.initialTraits || []).map(trait => ({ name: trait.name, summary: trait.描述, detail: trait.描述, negative: (trait.标签 || []).includes('负面') })),
                            ...(origin.displayBonus ? [{ name: origin.displayBonus.name, summary: origin.displayBonus.description, detail: origin.displayBonus.description }] : [])
                        ];
                    }
                    const baseBuffs = Array.isArray(currentRace.value?.buffs) ? currentRace.value.buffs : [];
                    const effectKey = selectedCombatValueMode.value === 'classic' ? '经典效果' : '新版效果';
                    const modeAdjustedBuffs = baseBuffs.map(buff => {
                        if (!buff || buff[effectKey] === undefined) return buff;
                        return {
                            ...buff,
                            detail: String(buff[effectKey] || '').trim()
                        };
                    });
                    if (!isAmberHumanRaceSelected.value) return modeAdjustedBuffs;
                    return modeAdjustedBuffs.map(buff => {
                        if (buff?.name !== '人类的可能性') return buff;
                        const summary = String(buff.summary || '').trim();
                        const detail = String(buff.detail || '').trim();
                        return {
                            ...buff,
                            summary: summary ? `${summary}；${AMBER_HUMAN_FATE_CARD_HINT}` : AMBER_HUMAN_FATE_CARD_HINT,
                            detail: detail ? `${detail}；${AMBER_HUMAN_FATE_CARD_HINT}` : AMBER_HUMAN_FATE_CARD_HINT
                        };
                    });
                });
                // 出身与种族特质统一在卡片内展示，避免浮层被滚动区域截断。
                const hoveredRaceBuff = ref(null);
                const selectedRaceBuff = ref(null);
                const activeRaceBuff = computed(() => {
                    const name = hoveredRaceBuff.value || selectedRaceBuff.value;
                    return name ? currentRaceDisplayBuffs.value.find(buff => buff.name === name) || null : null;
                });
                const toggleRaceBuff = (name) => {
                    selectedRaceBuff.value = selectedRaceBuff.value === name ? null : name;
                };
                watch([() => currentRace.value?.name, selectedWorldview], () => {
                    hoveredRaceBuff.value = null;
                    selectedRaceBuff.value = null;
                });
                // 获取可选的出生等级列表（低于当前种族初始等级的其他种族初始等级，阶梯式）
                const availableStartLevels = computed(() => {
                    if (isAmberWorldview.value || isJiuzhouWorldview.value || isDragonWorldview.value || isEarthseaWorldview.value || isSolarisWorldview.value) return [];
                    const race = currentRace.value;
                    if (!race) return [];
                    const nativeLevel = race.startLevel;
                    // 收集所有低于本种族初始等级的种族初始等级（去重+排序）
                    const levels = new Set();
                    levels.add(1); // 始终包含Lv.1
                    availableRaces.value.forEach(r => {
                        if (!r.disabled && r.startLevel < nativeLevel) {
                            levels.add(r.startLevel);
                        }
                    });
                    return Array.from(levels).sort((a, b) => a - b).map(lv => {
                        const matchRace = availableRaces.value.find(r => r.startLevel === lv && !r.disabled);
                        return {
                            level: lv,
                            raceName: matchRace ? matchRace.name : '人类种',
                            label: lv === 1 ? 'Lv.1（从零开始 +20 RP）' : `Lv.${lv}（${matchRace?.name || ''}级）`
                        };
                    });
                });

                // 当前实际出生等级
                const actualStartLevel = computed(() => {
                    if(isSolarisWorldview.value) return Math.max(1,Math.min(SOLARIS_MAX_START_LEVEL,Math.floor(Number(selectedCustomLevel.value)||1)));
                    if (isSaoOpeningSelected.value) {
                        return 1;
                    }
                    if (isJiuzhouWorldview.value) {
                        return Math.max(1, Math.min(JIUZHOU_MAX_START_LEVEL, Number(selectedCustomLevel.value) || 1));
                    }
                    if (isAmberWorldview.value) {
                        return Math.max(1, Number(selectedCustomLevel.value) || 1);
                    }
                    if (isDragonWorldview.value) {
                        return Math.max(1, Math.min(DRAGON_MAX_START_LEVEL, Number(selectedCustomLevel.value) || 1));
                    }
                    if (isEarthseaWorldview.value) {
                        return Math.max(1, Math.min(EARTHSEA_MAX_START_LEVEL, Math.floor(Number(selectedCustomLevel.value) || 1)));
                    }
                    if (selectedLevelMode.value === 'native' || !currentRace.value) {
                        return currentRace.value?.startLevel || 1;
                    }
                    return selectedCustomLevel.value || currentRace.value?.startLevel || 1;
                });

                // Lv.1出生的RP奖励
                const levelBonusRP = computed(() => {
                    if (isAmberWorldview.value || isJiuzhouWorldview.value || isDragonWorldview.value || isEarthseaWorldview.value || isSolarisWorldview.value) {
                        return actualStartLevel.value === 1 ? 20 : 0;
                    }
                    const race = currentRace.value;
                    if (!race) return 0;
                    // 只有本种族初始等级>1，且选择了Lv.1出发时才给奖励
                    if (race.startLevel > 1 && actualStartLevel.value === 1) return 20;
                    return 0;
                });

                // 当前等级对应的出生点列表（根据实际出生等级匹配种族出生点）
                const currentSpawnPoints = computed(() => {
                    if (isAmberWorldview.value) return [];
                    if (isJiuzhouWorldview.value) return [];
                    if (isDragonWorldview.value || isEarthseaWorldview.value || isSolarisWorldview.value) return [];
                    // 找到与实际出生等级匹配的种族出生点
                    const level = actualStartLevel.value;
                    // 找到初始等级等于当前出生等级的种族
                    const matchRace = mockData.races.find(r => r.startLevel === level && !r.disabled);
                    const raceName = matchRace ? matchRace.name : '人类种';
                    return spawnPointData[raceName]?.出生点 || spawnPointData['人类种'].出生点;
                });

                // 当出生点列表变化或进入角色创建时，自动选中推荐出生点
                watch([currentSpawnPoints, presetMode], ([points]) => {
                    if (isAmberWorldview.value || isDragonWorldview.value || isEarthseaWorldview.value || isSolarisWorldview.value) return;
                    if (points && points.length > 0 && !selectedSpawnPoint.value) {
                        const recommended = points.find(sp => sp.type === '推荐出生点');
                        selectedSpawnPoint.value = recommended ? recommended.name : points[0].name;
                    }
                }, { immediate: true });

                // 出生点列表内容变化时强制重选
                watch(currentSpawnPoints, (points) => {
                    if (isAmberWorldview.value || isDragonWorldview.value || isEarthseaWorldview.value || isSolarisWorldview.value) return;
                    if (points && points.length > 0) {
                        const recommended = points.find(sp => sp.type === '推荐出生点');
                        selectedSpawnPoint.value = recommended ? recommended.name : points[0].name;
                    }
                });

                watch(isAmberWorldview, (isAmber) => {
                    if (isAmber) {
                        if (selectedAmberSpawn.value?.名称) {
                            selectedSpawnPoint.value = selectedAmberSpawn.value.名称;
                        } else if (!trySetAmberSpawnSelection(DEFAULT_AMBER_SPAWN, { silent: true, source: '默认出生点' })) {
                            selectedSpawnPoint.value = null;
                        }
                        setTimeout(() => {
                            postAmberSpawnFocusToMap();
                        }, 0);
                        return;
                    }
                    selectedAmberSpawn.value = null;
                }, { immediate: true });

                watch(selectedAmberSpawn, (spawn) => {
                    if (isAmberWorldview.value) {
                        selectedSpawnPoint.value = spawn?.名称 || null;
                    }
                }, { deep: true });

                watch(isDragonWorldview, (isDragon) => {
                    if (isDragon) {
                        if (isDragonHighSchoolOrigin.value) {
                            trySetDragonSpawnSelection(DRAGON_SHILAN_SPAWN, { silent: true, source: '仕兰高中特殊开局' });
                        } else if (selectedDragonSpawn.value?.名称) {
                            selectedSpawnPoint.value = selectedDragonSpawn.value.名称;
                        } else {
                            trySetDragonSpawnSelection(DEFAULT_DRAGON_SPAWN, { silent: true, source: '默认出生点' });
                        }
                        setTimeout(() => {
                            postDragonSpawnFocusToMap();
                        }, 0);
                        return;
                    }
                    selectedDragonSpawn.value = null;
                }, { immediate: true });

                watch(selectedDragonSpawn, (spawn) => {
                    if (isDragonWorldview.value) {
                        selectedSpawnPoint.value = spawn?.名称 || null;
                    }
                }, { deep: true });

                // 自动更新角色等级
                const characterLevel = computed(() => {
                    return actualStartLevel.value;
                });

                // Logic - 博德之门3购点法
                // 计算当前属性值消耗的点数
                const getPointCost = (value) => {
                    return POINT_BUY_COSTS[value] || 0;
                };

                // 计算已使用的购点
                const usedPoints = computed(() => {
                    return Object.values(character.attributes).reduce((total, val) => {
                        return total + getPointCost(val);
                    }, 0);
                });

                // 剩余购点
                const remainingPoints = computed(() => {
                    return TOTAL_POINTS + buildReviewBonusAttributePoints.value - usedPoints.value;
                });

                // 获取种族加成
                const currentRaceBonuses = computed(() => {
                    let race = currentRace.value;
                    // 处理自定义种族
                    if (character.race === '__custom__' && customRace.enabled) {
                        race = {
                            name: customRace.name || '自定义种族',
                            rank: 0,
                            lore: `自定义种族。特性：${customRace.trait1.name}、${customRace.trait2.name}`
                        };
                    }
                    return race?.bonuses || { strength: 0, dexterity: 0, constitution: 0, intelligence: 0, wisdom: 0, charisma: 0 };
                });

                // 获取最终属性值（基础+种族加成）
                const getFinalAttr = (key) => {
                    const base = character.attributes[key];
                    const bonus = currentRaceBonuses.value[key] || 0;
                    return base + bonus;
                };

                // 旧的AP系统保留用于兼容
                const maxAP = computed(() => {
                    return TOTAL_POINTS + buildReviewBonusAttributePoints.value;
                });

                const remainingAP = computed(() => {
                    return remainingPoints.value;
                });

                const levelBonus = computed(() => {
                    return 0; // 购点法不使用等级加成
                });
                const baseRP = computed(() => {
                    if (isAmberWorldview.value || isJiuzhouWorldview.value || isDragonWorldview.value || isEarthseaWorldview.value || isSolarisWorldview.value) return 50;
                    return 100;
                });

                // 计算剩余RP
                const remainingRP = computed(() => {
                    // 预设角色模式：RP不适用，固定为0
                    if (isPresetChar.value) return 0;

                    let rp = baseRP.value + buildReviewBonusRP.value; // 初始RP + 构筑评议奖励

                    // Lv.1出生奖励
                    rp += levelBonusRP.value;

                    // 种族消耗
                    if (!isAmberWorldview.value && !isEarthseaWorldview.value) {
                        const r = availableRaces.value.find(x => x.name === character.race);
                        if (r) rp -= Number(r.cost) || 0;
                    }

                    // 身份消耗（SAO 开局时强制锁定为无财产出身）
                    rp -= effectiveIdentityCost.value;

                    // 初始装备商店消耗
                    rp -= starterShopSpentRP.value;

                    // 队友消耗
                    character.teammates.forEach(t => rp -= t.cost);

                    // 特质消耗（正面消耗RP，负面获得RP）
                    character.selectedTraits.forEach(t => rp -= t.cost);

                    // 自定义特质消耗（导入的预设固有特质按名字恢复正负面，其余默认固定30RP）
                    customTraits.forEach(t => rp -= getCustomTraitCost(t));

                    // 自定义专长消耗（每个固定20RP）
                    rp -= customExpertise.length * 20;

                    return rp;
                });

                // Attributes - 博德之门3购点法
                function updateAttr(key, delta) {
                    const currentVal = character.attributes[key];
                    const newVal = currentVal + delta;

                    // 检查边界
                    if (newVal < MIN_ATTR || newVal > MAX_ATTR) return;

                    // 计算点数变化
                    const currentCost = getPointCost(currentVal);
                    const newCost = getPointCost(newVal);
                    const costDiff = newCost - currentCost;

                    // 检查是否有足够的点数
                    if (costDiff > 0 && remainingPoints.value < costDiff) return;

                    character.attributes[key] = newVal;
                }

                // 检查是否可以增加属性
                function canIncreaseAttr(key) {
                    const currentVal = character.attributes[key];
                    if (currentVal >= MAX_ATTR) return false;
                    const currentCost = getPointCost(currentVal);
                    const newCost = getPointCost(currentVal + 1);
                    return remainingPoints.value >= (newCost - currentCost);
                }

                // 检查是否可以减少属性
                function canDecreaseAttr(key) {
                    return character.attributes[key] > MIN_ATTR;
                }

                function getAttributeLabel(key) {
                    const map = { strength: '力量', dexterity: '敏捷', constitution: '体质', intelligence: '智力', wisdom: '感知', charisma: '魅力' };
                    return map[key];
                }
                function getAttributeIcon(key) {
                    const map = { strength: 'ri-ancient-gate-fill', dexterity: 'ri-run-line', constitution: 'ri-heart-line', intelligence: 'ri-brain-line', wisdom: 'ri-eye-2-line', charisma: 'ri-star-smile-line' };
                    return map[key] || 'ri-circle-fill';
                }

                // 解析身份的初始装备信息
                function getIdentityEquipment(items) {
                    if (!items) return '无初始装备';
                    const match = items.match(/^(.+?)(?:。|。\s*)?初始金钱/);
                    if (match) return match[1].trim();
                    if (!items.includes('初始金钱')) return items;
                    return '无初始装备';
                }

                function getIdentityGoldAmount(items) {
                    if (!items) return 0;
                    const match = items.match(/初始金钱\s*([\d,]+)\s*G/);
                    if (!match) return 0;
                    return parseInt(String(match[1] || '').replace(/,/g, ''), 10) || 0;
                }

                function formatGoldAmount(value) {
                    const amount = Math.max(0, Math.floor(Number(value) || 0));
                    return `${new Intl.NumberFormat('zh-CN').format(amount)}G`;
                }

                function normalizeQualityName(value) {
                    return value === '神器' ? '卓越' : value;
                }

                function getIdentityResourceTierLabel(items) {
                    const equipText = getIdentityEquipment(items);
                    const match = String(equipText || '').match(/(普通|精良|稀有|卓越|神器|传说|史诗)/);
                    return match ? `${normalizeQualityName(match[1])}档` : '无装备';
                }

                // 解析身份的初始金钱信息
                function getIdentityGold(items) {
                    return formatGoldAmount(getIdentityGoldAmount(items));
                }

                function applySolarisOriginMvuBonuses(person,originName){
 const origin=solarisRaces.find(x=>x.name===originName);if(!person||!origin)return;
 person.特质||={};for(const t of origin.initialTraits||[])person.特质[t.name]={标签:[...t.标签],描述:t.描述};
 person.熟练度||={};person.熟练度.战斗||={};person.资源技能||={};
 const tiers=['学徒','熟手','专家','大师','传奇'];
 for(const p of origin.initialProficiencies){const current=person.熟练度.战斗[p.name];if(!current||tiers.indexOf(current.阶位)<1)person.熟练度.战斗[p.name]={阶位:'熟手',进度:Math.min(Math.max(0,Number(current?.进度)||0),49),升阶阈值:50,效果:p.name+'相关检定+3'};}
 for(const {name,...skill} of origin.initialResourceSkills)if(!person.资源技能[name])person.资源技能[name]=structuredClone(skill);
 if(originName==='漂泊之人'){person.身份='漂泊者';person.出生点='云陵谷';person.背景设定="从天空海掉落下来的失忆之人，游历各地，追寻失去的记忆。出生地固定为云陵谷，身份固定为漂泊者，无法更改。";}
}
                // 品质关键词染色映射
