                });
                const STARTER_SHOP_REMOTE_URLS = Object.freeze([
                    './start_equipment_shop.json',
                    'https://cdn.jsdelivr.net/gh/tangquanghuy/dnf@master/start_equipment_shop.json',
                    'https://cdn.jsdelivr.net/gh/tangquanghuy/dnf@master/start_equipment_shop_v1_3.json'
                ]);
                const STARTER_SHOP_DEFAULT_PRICE_MAP = Object.freeze({
                    普通: 0,
