                    稀有: 5,
                    卓越: 20,
                    传说: 35,
                    史诗: 50,
                    神话: 80
                });
                const STARTER_SHOP_QUALITY_ORDER = Object.freeze(['普通', '精良', '稀有', '卓越', '传说', '史诗', '神话']);
                const STARTER_SHOP_QUALITY_COLOR_MAP = Object.freeze({
                    普通: '#2D3436',
                    精良: '#0047AB',
                    稀有: '#9b59b6',
                    卓越: '#e84393',
                    传说: '#e67e22',
                    史诗: '#C9A227',
                    神话: 'linear-gradient(to right, #e8198b, #f1c40f)'
                });
                const STARTER_SHOP_QUALITY_SOLID_COLOR_MAP = Object.freeze({
                    普通: '#2D3436',
                    精良: '#0047AB',
                    稀有: '#9b59b6',
                    卓越: '#e84393',
                    传说: '#e67e22',
                    史诗: '#C9A227',
