                    '戒指', '手镯', '项链', '耳环',
                    '辅助装备', '魔法石'
                ]);
                const STARTER_SHOP_QUALITY_RANK = Object.freeze(
                    Object.fromEntries(STARTER_SHOP_QUALITY_ORDER.map((quality, index) => [quality, index]))
                );
                const STARTER_SHOP_SLOT_RANK = Object.freeze(
                    Object.fromEntries(STARTER_SHOP_SLOT_ORDER.map((slot, index) => [slot, index]))
                );
                const STARTER_SHOP_MVU_TAG = '开局商店';
                const starterShopState = reactive({
                    loading: false,
                    loaded: false,
                    error: '',
