                    items: [],
                    defaultPrices: { ...STARTER_SHOP_DEFAULT_PRICE_MAP }
                });
                const starterShopSelection = ref([]);
                const starterShopKeyword = ref('');
                const starterShopTypeFilter = ref('');
                const starterShopQualityFilter = ref('');
                const starterShopExpandedItems = ref([]);

                const toFiniteNumber = (value, fallback = null) => {
                    if (typeof value === 'number') return Number.isFinite(value) ? value : fallback;
                    if (typeof value === 'string') {
                        const trimmed = value.trim();
                        if (!trimmed) return fallback;
                        const parsed = Number(trimmed);
                        return Number.isFinite(parsed) ? parsed : fallback;
                    }
                    return fallback;
                };

                const normalizeStarterShopBonuses = (bonusMap) => {
                    if (!bonusMap || typeof bonusMap !== 'object' || Array.isArray(bonusMap)) return {};
                    const normalized = {};
                    Object.entries(bonusMap).forEach(([key, rawValue]) => {
                        const cleanKey = String(key || '').trim();
                        if (!cleanKey) return;
                        const value = toFiniteNumber(rawValue, null);
                        if (value === null) return;
                        normalized[cleanKey] = value;
                    });
                    return normalized;
                };

                const normalizeStarterShopItem = (rawItem, index, priceMap) => {
                    if (!rawItem || typeof rawItem !== 'object' || Array.isArray(rawItem)) return null;
                    const quality = normalizeQualityName(String(rawItem.品质 || '').trim());
                    if (!STARTER_SHOP_QUALITY_ORDER.includes(quality)) return null;
                    const type = String(rawItem.类型 || rawItem.分类 || '').trim() || '武器';
                    const slot = String(rawItem.部位 || '').trim() || (type === '首饰' ? '戒指' : type === '防具' ? '上衣' : '主手');
                    const price = toFiniteNumber(rawItem.售价RP, null);
                    const resolvedPrice = Number.isFinite(price) ? Math.max(0, price) : Math.max(0, Number(priceMap[quality] || 0));
                    const tags = Array.isArray(rawItem.标签)
                        ? Array.from(new Set(rawItem.标签.map(tag => String(tag || '').trim()).filter(Boolean)))
                        : [];
                    return {
                        id: String(rawItem.id || `${type}_${slot}_${index + 1}`).trim() || `${type}_${slot}_${index + 1}`,
                        分类: String(rawItem.分类 || type).trim() || type,
                        类型: type,
                        部位: slot,
                        名称: String(rawItem.名称 || `未命名装备${index + 1}`).trim() || `未命名装备${index + 1}`,
                        品质: quality,
                        等级: Math.max(1, Math.floor(toFiniteNumber(rawItem.等级, 1) || 1)),
                        品级: null,
                        标签: tags,
                        属性加成: normalizeStarterShopBonuses(rawItem.属性加成),
                        效果: String(rawItem.效果 || '').trim(),
                        经典效果: String(rawItem.经典效果 ?? rawItem.效果 ?? '').trim(),
                        新版效果: String(rawItem.新版效果 ?? rawItem.效果 ?? '').trim(),
                        描述: String(rawItem.描述 || '').trim(),
                        售价RP: resolvedPrice
                    };
                };

                const sortStarterShopItems = (items) => {
                    const qualityRank = Object.fromEntries(STARTER_SHOP_QUALITY_ORDER.map((quality, index) => [quality, index]));
                    const categoryRank = Object.fromEntries(STARTER_SHOP_CATEGORY_ORDER.map((category, index) => [category, index]));
                    return items.slice().sort((a, b) => {
                        const categoryDiff = (categoryRank[a.分类] ?? 99) - (categoryRank[b.分类] ?? 99);
                        if (categoryDiff !== 0) return categoryDiff;
                        const qualityDiff = (qualityRank[a.品质] ?? 99) - (qualityRank[b.品质] ?? 99);
                        if (qualityDiff !== 0) return qualityDiff;
                        const priceDiff = (Number(a.售价RP) || 0) - (Number(b.售价RP) || 0);
                        if (priceDiff !== 0) return priceDiff;
                        return String(a.名称 || '').localeCompare(String(b.名称 || ''), 'zh-Hans-CN');
                    });
                };

                const normalizeStarterShopPayload = (payload) => {
                    const rawDefaultPrices = (payload && typeof payload === 'object' && !Array.isArray(payload) && payload['默认售价RP'] && typeof payload['默认售价RP'] === 'object')
                        ? payload['默认售价RP']
                        : {};
                    const normalizedDefaultPrices = {};
                    Object.entries(rawDefaultPrices).forEach(([quality, price]) => {
                        normalizedDefaultPrices[normalizeQualityName(String(quality || '').trim())] = price;
                    });
                    const defaultPrices = {
                        ...STARTER_SHOP_DEFAULT_PRICE_MAP,
                        ...normalizedDefaultPrices
                    };
                    const rawItems = Array.isArray(payload?.items) ? payload.items : [];
                    const normalizedItems = sortStarterShopItems(
                        rawItems
                            .map((item, index) => normalizeStarterShopItem(item, index, defaultPrices))
                            .filter(Boolean)
                    );
                    return {
                        version: String(payload?.version || '').trim(),
                        updatedAt: String(payload?.updatedAt || '').trim(),
                        defaultPrices,
                        items: normalizedItems
                    };
                };

                function applyStarterShopNormalizedData(normalized, sourceUrl, usingFallback) {
                    starterShopState.items = normalized.items;
                    starterShopState.defaultPrices = normalized.defaultPrices;
                    starterShopState.version = normalized.version;
                    starterShopState.updatedAt = normalized.updatedAt;
                    starterShopState.sourceUrl = sourceUrl;
                    starterShopState.usingFallback = !!usingFallback;
                    starterShopState.loaded = true;
                    starterShopState.error = '';
                    starterShopState.loading = false;
                }

                async function loadStarterShopData() {
                    if (starterShopState.loading) return;
                    starterShopState.loading = true;
                    starterShopState.error = '';
                    let lastError = null;

                    for (let index = 0; index < STARTER_SHOP_REMOTE_URLS.length; index += 1) {
                        const targetUrl = STARTER_SHOP_REMOTE_URLS[index];
                        try {
                            const response = await fetch(targetUrl, {
                                method: 'GET',
                                credentials: 'omit',
                                cache: 'no-store'
                            });
                            if (!response.ok) {
                                throw new Error(`HTTP ${response.status}`);
                            }
                            const payload = await response.json();
                            const normalized = normalizeStarterShopPayload(payload);
                            if (!normalized.items.length) {
                                throw new Error('商店数据为空');
                            }
                            applyStarterShopNormalizedData(normalized, targetUrl, !/^https?:\/\//i.test(targetUrl));
                            return;
                        } catch (error) {
                            lastError = error;
                        }
                    }

                    starterShopState.items = [];
                    starterShopState.loaded = false;
                    starterShopState.loading = false;
                    starterShopState.sourceUrl = '';
                    starterShopState.usingFallback = false;
                    starterShopState.error = lastError?.message || '未知错误';
                }

                const starterShopItemMap = computed(() =>
                    new Map((starterShopState.items || []).map(item => [item.id, item]))
                );
                const starterShopAvailable = computed(() => !isPresetChar.value && !isSaoOpeningSelected.value);
                const starterShopSelectedItems = computed(() => {
                    const map = starterShopItemMap.value;
                    return starterShopSelection.value
                        .map(id => map.get(id))
                        .filter(Boolean);
                });
                const starterShopSpentRP = computed(() => {
                    if (!starterShopAvailable.value) return 0;
                    return starterShopSelectedItems.value.reduce((sum, item) => sum + (Number(item?.售价RP) || 0), 0);
                });
                const starterShopTypeOptions = computed(() => {
                    const types = Array.from(new Set(
                        (starterShopState.items || [])
                            .map(item => String(item?.类型 || item?.分类 || '').trim())
                            .filter(Boolean)
                    ));
                    const ordered = STARTER_SHOP_CATEGORY_ORDER.filter(type => types.includes(type));
                    types.forEach(type => {
                        if (!ordered.includes(type)) ordered.push(type);
                    });
                    return ordered;
                });
                const starterShopQualityOptions = computed(() => {
                    const qualities = Array.from(new Set((starterShopState.items || []).map(item => item.品质).filter(Boolean)));
                    return STARTER_SHOP_QUALITY_ORDER.filter(quality => qualities.includes(quality));
                });
                const starterShopFiltersReady = computed(() => {
                    return !!String(starterShopTypeFilter.value || '').trim()
                        && !!String(starterShopQualityFilter.value || '').trim();
                });
                const filteredStarterShopItems = computed(() => {
                    const keyword = String(starterShopKeyword.value || '').trim().toLowerCase();
                    const type = starterShopTypeFilter.value;
                    const quality = starterShopQualityFilter.value;
                    if (!starterShopFiltersReady.value) return [];
                    return (starterShopState.items || []).filter(item => {
                        const itemType = String(item?.类型 || item?.分类 || '').trim();
                        if (itemType !== type) return false;
                        if (item.品质 !== quality) return false;
                        if (!keyword) return true;
                        const haystack = [
                            item.名称,
                            itemType,
                            item.分类,
                            item.类型,
                            item.部位,
                            item.品质,
                            ...(item.标签 || [])
                        ].join(' ').toLowerCase();
                        return haystack.includes(keyword);
                    });
                });

                const starterShopDisplayItems = computed(() => {
                    const items = filteredStarterShopItems.value || [];
                    return items.slice().sort((a, b) => {
                        const typeA = String(a?.类型 || a?.分类 || '').trim();
                        const typeB = String(b?.类型 || b?.分类 || '').trim();
                        const typeRankA = STARTER_SHOP_CATEGORY_ORDER.indexOf(typeA);
                        const typeRankB = STARTER_SHOP_CATEGORY_ORDER.indexOf(typeB);
                        const safeRankA = typeRankA >= 0 ? typeRankA : 999;
                        const safeRankB = typeRankB >= 0 ? typeRankB : 999;
                        const typeDiff = safeRankA - safeRankB;
                        if (typeDiff !== 0) return typeDiff;
                        if (safeRankA === 999 && safeRankB === 999) {
                            const typeNameDiff = typeA.localeCompare(typeB, 'zh-Hans-CN');
                            if (typeNameDiff !== 0) return typeNameDiff;
                        }
                        const qualityDiff = (STARTER_SHOP_QUALITY_RANK[a.品质] ?? 999) - (STARTER_SHOP_QUALITY_RANK[b.品质] ?? 999);
                        if (qualityDiff !== 0) return qualityDiff;
                        const slotDiff = (STARTER_SHOP_SLOT_RANK[a.部位] ?? 999) - (STARTER_SHOP_SLOT_RANK[b.部位] ?? 999);
                        if (slotDiff !== 0) return slotDiff;
                        const priceDiff = (Number(a?.售价RP) || 0) - (Number(b?.售价RP) || 0);
                        if (priceDiff !== 0) return priceDiff;
                        return String(a.名称 || '').localeCompare(String(b.名称 || ''), 'zh-Hans-CN');
                    });
                });
                function isStarterShopItemExpanded(itemId) {
                    return starterShopExpandedItems.value.includes(itemId);
                }

                function toggleStarterShopItemExpanded(itemId) {
                    const id = String(itemId || '').trim();
                    if (!id) return;
