                }

                function isStarterShopRowPeerHidden(itemId, itemIndex) {
                    const id = String(itemId || '').trim();
                    if (!id) return false;
                    const expandedId = String(starterShopExpandedItems.value[0] || '').trim();
                    if (!expandedId || id === expandedId) return false;
                    const expandedIndex = starterShopDisplayItems.value.findIndex(item => item?.id === expandedId);
                    if (expandedIndex < 0) return false;
                    const peerIndex = expandedIndex % 2 === 0 ? expandedIndex + 1 : expandedIndex - 1;
                    if (peerIndex < 0) return false;
                    if (Number.isInteger(itemIndex)) return itemIndex === peerIndex;
                    return starterShopDisplayItems.value.findIndex(item => item?.id === id) === peerIndex;
                }

                function isStarterShopItemSelected(itemId) {
                    return starterShopSelection.value.includes(itemId);
                }

                function toggleStarterShopItem(itemId) {
                    const id = String(itemId || '').trim();
                    if (!id) return;
                    const nextSelection = starterShopSelection.value.slice();
                    const existingIndex = nextSelection.indexOf(id);
                    if (existingIndex >= 0) {
                        nextSelection.splice(existingIndex, 1);
                    } else {
                        nextSelection.push(id);
                    }
                    starterShopSelection.value = nextSelection;
                }

                function formatStarterShopBonuses(bonusMap) {
                    const entries = Object.entries(bonusMap || {});
                    if (!entries.length) return '无';
                    const labelMap = {
                        力量: '力量',
                        敏捷: '敏捷',
                        体质: '体质',
                        智力: '智力',
                        感知: '感知',
                        魅力: '魅力',
                        生命值上限: '生命值上限',
                        物理减伤: '物理减伤',
                        魔法减伤: '魔法减伤',
                        全技能: '全技能',
                        基础: '基础技能',
                        转职: '转职技能',
                        进阶: '进阶技能',
                        必杀: '必杀技能',
                        奥义: '奥义技能',
                        觉醒一: '觉醒一技能',
                        觉醒二: '觉醒二技能',
                        觉醒三: '觉醒三技能'
                    };
                    const order = [
                        '力量', '敏捷', '体质', '智力', '感知', '魅力',
                        '生命值上限', '物理减伤', '魔法减伤',
                        '全技能', '基础', '转职', '进阶', '必杀', '奥义', '觉醒一', '觉醒二', '觉醒三'
                    ];
                    const rankMap = Object.fromEntries(order.map((key, index) => [key, index]));
                    return entries
                        .slice()
                        .sort((a, b) => (rankMap[a[0]] ?? 999) - (rankMap[b[0]] ?? 999))
                        .map(([key, value]) => `${key}${value > 0 ? '+' : ''}${value}`)
                        .map(text => {
                            const idx = text.search(/[+-]/);
                            if (idx <= 0) return text;
                            const rawKey = text.slice(0, idx);
                            const tail = text.slice(idx);
                            return `${labelMap[rawKey] || rawKey}${tail}`;
                        })
                        .join(' / ');
                }

                function formatStarterShopDetailText(text) {
                    const source = String(text || '').trim();
                    if (!source) return '无';
                    return source
                        .replace(/[ \t\r\f\v]+/g, ' ')
                        .replace(/([。！？；])/g, '$1\n')
                        .replace(/\n{2,}/g, '\n')
                        .trim();
                }

                function escapeStarterShopHtml(text) {
                    const source = String(text || '');
                    if (!source) return '';
                    const el = document.createElement('div');
                    el.textContent = source;
                    return el.innerHTML;
                }

                function isStarterShopFormulaToken(token) {
                    const body = String(token || '').slice(1, -1).trim();
                    if (!body) return false;
                    const hasDigit = /[0-9０-９]/.test(body);
                    const hasMathSymbol = /[%+\-*/×xX()（）=<>≤≥]/.test(body);
                    const hasFormulaWord = /(等级|level|lv|倍率|伤害|加成|冷却)/i.test(body);
                    return !!(hasDigit && (hasMathSymbol || hasFormulaWord));
                }

                function renderStarterShopDetailText(text) {
                    const normalized = formatStarterShopDetailText(text);
                    const escaped = escapeStarterShopHtml(normalized);
                    return escaped
                        .replace(/(\[[^\]\r\n]{1,120}\]|【[^】\r\n]{1,120}】)/g, (token) => {
                            const cls = isStarterShopFormulaToken(token) ? 'starter-shop-formula-highlight' : 'starter-shop-term-highlight';
                            return `<span class="${cls}">${token}</span>`;
                        })
                        .replace(/\n/g, '<br>');
                }

                function getStarterShopQualityBadgeStyle(quality) {
                    const qualityKey = STARTER_SHOP_QUALITY_ORDER.includes(quality) ? quality : '普通';
                    const rawColor = STARTER_SHOP_QUALITY_COLOR_MAP[qualityKey] || STARTER_SHOP_QUALITY_COLOR_MAP['普通'];
                    const solidColor = STARTER_SHOP_QUALITY_SOLID_COLOR_MAP[qualityKey] || STARTER_SHOP_QUALITY_SOLID_COLOR_MAP['普通'];
                    const isGradient = typeof rawColor === 'string' && rawColor.includes('linear-gradient');
                    if (isGradient) {
                        return {
                            background: 'rgba(232, 25, 139, 0.16)',
                            color: solidColor,
                            borderColor: solidColor,
                            textStyle: {
                                background: rawColor,
                                WebkitBackgroundClip: 'text',
                                WebkitTextFillColor: 'transparent',
                                color: 'transparent'
                            }
                        };
                    }
                    return {
                        background: `${solidColor}1A`,
                        color: solidColor,
                        borderColor: solidColor,
                        textStyle: { color: solidColor }
                    };
                }
                watch(() => starterShopState.items, (items) => {
