                watch(starterShopDisplayItems, (items) => {
                    const validItemIds = new Set((items || []).map(item => item.id));
                    starterShopExpandedItems.value = starterShopExpandedItems.value.filter(id => validItemIds.has(id));
                }, { immediate: true });

