                }

                // Skills
                const availableSkills = computed(() => {
                    // For simplicity, showing skills based on selected class, defaulting to warrior if not found
                    return mockData.skills[character.class] || mockData.skills['warrior'];
                });

                function hasSkill(skill) { return character.skills.some(s => s.name === skill.name); }
                function toggleSkill(skill) {
                    const idx = character.skills.findIndex(s => s.name === skill.name);
                    if (idx >= 0) {
                        character.skills.splice(idx, 1);
                    } else {
                        if (character.skills.length < 3) character.skills.push(skill);
                    }
                }

                // Teammates

                const SOLARIS_HIDDEN_TEAMMATE_IDS = new Set(['t13','t14','t17']);
                const SOLARIS_HIDDEN_TEAMMATE_NAMES = new Set(['卡提希娅','爱弥斯','达妮娅']);
                const isSolarisTeammateHidden = mate => isSolarisWorldview.value && !!mate && (SOLARIS_HIDDEN_TEAMMATE_IDS.has(mate.id) || SOLARIS_HIDDEN_TEAMMATE_NAMES.has(mate.name));
                const sanitizeSolarisTeammates = () => {
                    if(!isSolarisWorldview.value)return;
                    const allowed=character.teammates.filter(mate=>!isSolarisTeammateHidden(mate));
                    if(allowed.length!==character.teammates.length)character.teammates=allowed;
                };
                watch(()=>[selectedWorldview.value,...character.teammates.map(mate=>String(mate.id)+':'+String(mate.name))],sanitizeSolarisTeammates,{immediate:true});

                function hasTeammate(m) { return character.teammates.some(t => t.id === m.id); }
                function toggleTeammate(m) {
                    if(isSolarisTeammateHidden(m))return;
                    if (isBondSelectionDisabled.value) return;
                    const idx = character.teammates.findIndex(t => t.id === m.id);
                    if (idx >= 0) {
                        character.teammates.splice(idx, 1);
                    } else {
                        if (character.teammates.length < 1) character.teammates.push(m);
                    }
                }

                // ==================== 自定义队友系统 ====================
                const CUSTOM_TEAMMATE_COST = 0; // 自定义队友不消耗RP
                const CT_POINT_BUY_COSTS = { 8: 0, 9: 1, 10: 2, 11: 3, 12: 4, 13: 5, 14: 7, 15: 9 };

                const customTeammate = reactive({
                    enabled: false,
                    name: '',
                    gender: '女',
                    race: '人类种',
                    affinity: 50,
                    oath: false,
                    appearance: '',
                    outfit: '',
                    background: '',
                    attributes: { strength: 10, dexterity: 10, constitution: 10, intelligence: 10, wisdom: 10, charisma: 10 },
                    equipment: [],
                    skills: [],
                    combo: { name: '', type: '伤害', quality: '普通', effect: '', desc: '' }
                });

                function syncCustomTeammateProxy() {
                    const customIdx = character.teammates.findIndex(t => t.id === '__custom__');
                    const customProxy = { id: '__custom__', name: '自定义队友', cost: CUSTOM_TEAMMATE_COST, isCustom: true };

                    if (customTeammate.enabled) {
                        // 自定义队友开启时，强制确保占位存在且为唯一队友
                        if (customIdx >= 0) {
                            character.teammates.splice(customIdx, 1);
