                        character.teammates.splice(0, character.teammates.length, customProxy);
                    } else if (customIdx >= 0) {
                        character.teammates.splice(customIdx, 1);
                    }
                }

                function enableCustomTeammate() {
                    if (isBondSelectionDisabled.value) return;
                    if (character.teammates.length >= 1) return;
                    customTeammate.enabled = true;
                    syncCustomTeammateProxy();
                }

                function disableCustomTeammate() {
                    customTeammate.enabled = false;
                    syncCustomTeammateProxy();
                }

                // 自定义队友属性购点
                const customTeammateRemainingPoints = computed(() => {
                    let spent = 0;
                    for (const val of Object.values(customTeammate.attributes)) {
                        spent += CT_POINT_BUY_COSTS[val] || 0;
                    }
                    return 27 - spent;
                });

                function updateCustomTeammateAttr(key, delta) {
                    const cur = customTeammate.attributes[key];
                    const next = cur + delta;
                    if (next < 8 || next > 15) return;
                    const curCost = CT_POINT_BUY_COSTS[cur];
                    const nextCost = CT_POINT_BUY_COSTS[next];
                    if (nextCost - curCost > customTeammateRemainingPoints.value) return;
                    customTeammate.attributes[key] = next;
                }

                function canIncreaseCustomTeammateAttr(key) {
                    const cur = customTeammate.attributes[key];
                    if (cur >= 15) return false;
                    const diff = CT_POINT_BUY_COSTS[cur + 1] - CT_POINT_BUY_COSTS[cur];
                    return customTeammateRemainingPoints.value >= diff;
                }

                // 装备管理
                function addCustomTeammateEquip() {
                    if (customTeammate.equipment.length >= 2) return;
                    customTeammate.equipment.push({
                        name: '', type: '武器', slot: '主手', quality: '普通',
                        effect: '', desc: '',
                        bonuses: { '力量': 0, '敏捷': 0, '体质': 0, '智力': 0, '感知': 0, '魅力': 0, '暴击率': 0, '暴击伤害': 0, '物理减伤': 0, '魔法减伤': 0, '生命值上限': 0 }
                    });
                }
                function removeCustomTeammateEquip(idx) { customTeammate.equipment.splice(idx, 1); }

                // 技能管理
                function addCustomTeammateSkill() {
                    if (customTeammate.skills.length >= 2) return;
                    customTeammate.skills.push({ name: '', type: '伤害', quality: '普通', effect: '', desc: '' });
                }
                function removeCustomTeammateSkill(idx) { customTeammate.skills.splice(idx, 1); }

                // Traits
                const traitFilter = ref('positive');
                const traitCategoryLabels = { positive: '正面', negative: '负面', 'double-edged': '双刃剑', special: '稀有', life_skill: '生活技能', easter_egg: '彩蛋' };
                const traitCategories = computed(() => {
                    const cats = [...new Set(traitsData.map(t => t.category))];
                    return cats;
                });
                function hasTrait(t) { return character.selectedTraits.some(s => s.name === t.name); }
                // cost >= 0 算正面槽位，cost < 0 算负面槽位；导入的预设固有特质按名字恢复其正负面槽位
                const positiveTraitCount = computed(() => {
                    let count = character.selectedTraits.filter(t => t.cost >= 0).length;
                    count += customTraits.filter(t => getCustomTraitSlot(t) !== 'negative').length;
                    count += customExpertise.length;
                    return count;
                });
                const negativeTraitCount = computed(() => {
                    let count = character.selectedTraits.filter(t => t.cost < 0).length;
                    count += customTraits.filter(t => getCustomTraitSlot(t) === 'negative').length;
                    return count;
                });
                function isTraitDisabled(t) {
                    if (hasTrait(t)) return false;
                    if (t.cost >= 0 && positiveTraitCount.value >= 3) return true;
                    if (t.cost < 0 && negativeTraitCount.value >= 3) return true;
                    return false;
                }
                function toggleTrait(t) {
                    if (isTraitDisabled(t)) return;
                    const idx = character.selectedTraits.findIndex(s => s.name === t.name);
                    if (idx >= 0) {
                        character.selectedTraits.splice(idx, 1);
                    } else {
                        character.selectedTraits.push(t);
                    }
                }
                const TRAITS_PER_CATEGORY = 6;
                const filteredTraits = computed(() => {
                    let list = traitsData.filter(t => t.category === traitFilter.value);
                    list.sort((a, b) => Math.abs(b.cost) - Math.abs(a.cost));
                    return list;
                });
                const traitCostTotal = computed(() => {
                    let total = character.selectedTraits.reduce((sum, t) => sum + t.cost, 0);
                    total += customTraits.reduce((sum, t) => sum + getCustomTraitCost(t), 0);
                    total += customExpertise.length * 20;
                    return total;
                });
                const selectedTraitDetail = ref(null);

                // 自定义特质（支持多个，每个消耗30RP，占用正面槽位）
                const customTraits = reactive([]);
                const customTraitDraft = reactive({ name: '', effect: '' });
