                // 自定义出身背景
                const customIdentity = reactive({
                    enabled: true,
                    name: '自定义出身',
                    desc: '',
                    cardExpanded: false,
                    tierIndex: 0 // 层级索引，对应当前类型的出身背景列表
                });
                character.identity = '__custom__';

                // 获取当前自定义出身的层级配置（根据种族类型动态获取）
                const currentCustomIdentityTier = computed(() => {
                    const list = currentIdentities.value;
                    const index = Math.min(customIdentity.tierIndex, list.length - 1);
                    return list[index] || list[0];
                });

                // 切换自定义出身背景
                function toggleCustomIdentity() {
