                }

                function toggleSaoCustomIdentityText() {
                    customIdentity.enabled = true;
                    character.identity = '__custom__';
                }

                const normalizeCombatValueMode = () => 'new';
                const currentOpeningCombatValueMode = computed(() => normalizeCombatValueMode(selectedCombatValueMode.value));
                const getStarterShopItemEffect = (item, mode = currentOpeningCombatValueMode.value) => {
                    if (!item || typeof item !== 'object') return '';
                    const effectKey = normalizeCombatValueMode(mode) === 'new' ? '新版效果' : '经典效果';
                    return String(item[effectKey] ?? item.效果 ?? '').trim();
                };
                const currentOpeningCombatValueModeLabel = computed(() => (
                    combatValueModeOptions.find(mode => mode.key === currentOpeningCombatValueMode.value)?.label || '经典'
                ));
                const currentOpeningCombatValueModeDescription = computed(() => (
                    currentOpeningCombatValueMode.value === 'new'
                        ? '新版数值难度曲线较平滑，高位阶敌人更强，削弱了武器等级成长，相对不需要经常升级武器，但也削弱了成长感。'
                        : '旧版数值前期更难，高等级敌人更弱，武器等级占伤害最大影响，成长感更足，但需要频繁升级武器等级。'
                ));
                const getDiffPresetsByCombatMode = (mode = DEFAULT_OPENING_COMBAT_VALUE_MODE) => (
                    normalizeCombatValueMode(mode) === 'new' ? NEW_DIFF_PRESETS : DIFF_PRESETS
                );
                const difficultyOptionsForCurrentMode = computed(() =>
                    Object.values(getDiffPresetsByCombatMode(currentOpeningCombatValueMode.value))
                );
                const currentDifficultyModeDescription = computed(() => (
                    currentOpeningCombatValueMode.value === 'new'
                        ? '新版只使用普通、困难两档。'
                        : '经典保留简单、普通、困难、王者、噩梦。'
                ));
                const normalizeDifficultyKeyForMode = (difficultyKey, mode = DEFAULT_OPENING_COMBAT_VALUE_MODE) => {
                    const combatMode = normalizeCombatValueMode(mode);
                    if (combatMode === 'new') {
                        return ['hard', 'king', 'nightmare'].includes(difficultyKey) ? 'hard' : 'normal';
                    }
                    return DIFF_PRESETS[difficultyKey] ? difficultyKey : 'easy';
                };
                const getDifficultyPreset = (difficultyKey, mode = DEFAULT_OPENING_COMBAT_VALUE_MODE) => {
                    const presets = getDiffPresetsByCombatMode(mode);
                    const normalizedKey = normalizeDifficultyKeyForMode(difficultyKey, mode);
                    return presets[normalizedKey];
                };
                const cloneDifficultyMultipliers = (difficultyKey, mode = DEFAULT_OPENING_COMBAT_VALUE_MODE) => {
                    const preset = getDifficultyPreset(difficultyKey, mode);
                    if (!preset) return null;
                    const multipliers = {};
                    difficultyTierOrder.forEach(tier => {
                        multipliers[tier] = {
                            伤害倍率: preset[tier].伤害倍率,
                            HP倍率: preset[tier].HP倍率
                        };
                    });
                    return multipliers;
                };
                const cloneOpeningValue = (value) => {
                    if (!value || typeof value !== 'object') return value;
                    return JSON.parse(JSON.stringify(value));
                };
                const selectOpeningModeEffect = (source, mode = DEFAULT_OPENING_COMBAT_VALUE_MODE) => {
                    if (!source || typeof source !== 'object') return undefined;
                    const effectKey = normalizeCombatValueMode(mode) === 'new' ? '新版效果' : '经典效果';
                    if (source[effectKey] !== undefined) return cloneOpeningValue(source[effectKey]);
                    if (source.效果 !== undefined) return cloneOpeningValue(source.效果);
                    return undefined;
                };
                const applyOpeningModeEffectsByMode = (value, mode = DEFAULT_OPENING_COMBAT_VALUE_MODE) => {
                    if (!value || typeof value !== 'object') return value;
                    if (Array.isArray(value)) {
                        value.forEach(item => applyOpeningModeEffectsByMode(item, mode));
                        return value;
                    }

