                    const normalizedMode = normalizeCombatValueMode(mode);
                    selectedCombatValueMode.value = normalizedMode;
                    selectedDifficulty.value = normalizeDifficultyKeyForMode(selectedDifficulty.value, normalizedMode);
                }

                function setOpeningDifficulty(difficultyKey) {
                    if (isSaoOpeningSelected.value) return;
                    selectedDifficulty.value = normalizeDifficultyKeyForMode(difficultyKey, currentOpeningCombatValueMode.value);
                }

                watch([selectedCombatValueMode, selectedDifficulty], ([mode, difficulty]) => {
                    const normalizedMode = normalizeCombatValueMode(mode);
                    if (selectedCombatValueMode.value !== normalizedMode) {
                        selectedCombatValueMode.value = normalizedMode;
                        return;
                    }
                    const normalizedDifficulty = normalizeDifficultyKeyForMode(difficulty, normalizedMode);
                    if (selectedDifficulty.value !== normalizedDifficulty) {
                        selectedDifficulty.value = normalizedDifficulty;
                        return;
                    }
                    void saveDifficultyToMvu(normalizedDifficulty, true);
                });

                async function saveWorldviewToMvu(worldviewLabel = currentWorldviewMvuLabel.value, silent = false) {
                    const mvu = getMvuApi();
                    if (!mvu) {
                        if (!silent) {
                            alert('MVU系统不可用，无法写入世界观设置。');
                        }
                        return false;
                    }

                    try {
                        const mvuData = mvu.getMvuData({ type: 'message', message_id: 'latest' });
                        if (!mvuData) {
                            if (!silent) {
                                alert('无法获取MVU数据，世界观写入失败。');
                            }
                            return false;
                        }
                        if (!mvuData.stat_data) mvuData.stat_data = {};
                        if (!mvuData.stat_data.系统配置) mvuData.stat_data.系统配置 = {};
                        if (!mvuData.stat_data.世界信息) mvuData.stat_data.世界信息 = {};
                        mvuData.stat_data.系统配置.世界观 = worldviewLabel || '创世回廊';
                        if(worldviewLabel==='索拉里斯') {mvuData.stat_data.世界信息.世界剧情='索拉里斯';mvuData.stat_data.世界信息.年历='所选故事时点';}
                        if (worldviewLabel === '琥珀之剑') {
                            mvuData.stat_data.世界信息.世界剧情 = '布契之夜';
                            mvuData.stat_data.世界信息.年历 = '375年';
                        }
                        if (worldviewLabel === '大明志异') {
                            mvuData.stat_data.世界信息.年历 = '1560年3月1日';
                        }
                        if (worldviewLabel === '诡秘地海') {
                            mvuData.stat_data.世界信息.年历 = '地海历807年';
                            mvuData.stat_data.世界信息.世界剧情 = '诡秘地海';
                        }
                        if (worldviewLabel === '屠龙与都市日常') {
                            mvuData.stat_data.世界信息.年历 = '2026年3月1日';
                            mvuData.stat_data.世界信息.世界剧情 = '屠龙与都市日常';
                        }

                        await mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
                        return true;
                    } catch (e) {
                        console.error('[RPG开局] 世界观写入MVU失败:', e);
                        if (!silent) {
                            alert('世界观写入失败: ' + (e.message || e));
                        }
                        return false;
                    }
                }

                // 阶位配置 (与辅助脚本 TIER_CONFIG 保持一致，伤害倍率和冷却由运行时动态计算)
                const SKILL_TIER_CONFIG = {
                    '基础': { 习得等级: 1, 等级上限: 15, SP消耗: 10 },
                    '转职': { 习得等级: 15, 等级上限: 15, SP消耗: 15 },
                    '进阶': { 习得等级: 30, 等级上限: 10, SP消耗: 20 },
                    '必杀': { 习得等级: 45, 等级上限: 7, SP消耗: 30 },
                    '奥义': { 习得等级: 75, 等级上限: 5, SP消耗: 50 },
                    '觉醒一': { 习得等级: 50, 等级上限: 3, SP消耗: 100 },
                    '觉醒二': { 习得等级: 85, 等级上限: 2, SP消耗: 150 },
                    '觉醒三': { 习得等级: 100, 等级上限: 1, SP消耗: 200 }
                };

                // AI生成的阶位key到schema枚举的映射
                const SKILL_TIER_KEY_MAP = {
                    'Tier1': '基础', 'Tier2': '转职', 'Tier3': '进阶',
                    'Tier4': '必杀', 'Tier5': '奥义',
                    '觉醒1': '觉醒一', '觉醒2': '觉醒二', '觉醒3': '觉醒三',
                    // 兼容原始数据直接使用中文阶位名
                    '基础': '基础', '转职': '转职', '进阶': '进阶',
                    '必杀': '必杀', '奥义': '奥义',
                    '觉醒一': '觉醒一', '觉醒二': '觉醒二', '觉醒三': '觉醒三'
                };
                const AWAKENING_STAGE_MAP = {
                    '觉醒一': '觉醒一', '觉醒二': '觉醒二', '觉醒三': '觉醒三',
                    '觉醒1': '觉醒一', '觉醒2': '觉醒二', '觉醒3': '觉醒三',
                };

                // 主动/召唤中出现机制类描述时，要求提供特殊效果（用于升级时按等级读取）
                const ACTIVE_MECHANIC_EFFECT_REGEX = /(命中后|附加|施加|获得|进入|标记|持续|每回合|回复|吸血|护盾|无敌|免疫|眩晕|击退|束缚|禁锢|斩杀|流血|中毒|灼烧|冰冻|麻痹|易伤|增益|减益|额外.*伤害|再次造成|\[[^\]]+\])/;
                const FORBIDDEN_COOLDOWN_CHANGE_REGEX = /(冷却(?:时间|回合|计数)?[^，。；\n]*(?:减少|降低|缩短|刷新|重置|归零|清零)|(?:减少|降低|缩短|刷新|重置)[^，。；\n]*冷却)/;

                const skillNeedsSpecialEffect = (skill) => {
                    const type = String(skill?.类型 || '主动').trim();
                    if (type === '特殊' || type === '职业特殊') return true;
                    if (type !== '主动' && type !== '召唤') return false;
                    const text = `${skill?.名称 || ''} ${skill?.描述 || ''}`;
                    return ACTIVE_MECHANIC_EFFECT_REGEX.test(text);
                };

                const normalizeSkillSpecialEffect = (skill, tierConfig, strictMode = false) => {
                    const type = String(skill?.类型 || '主动').trim();
                    const maxLevel = Math.max(1, parseInt(tierConfig?.等级上限, 10) || 1);
                    const rawEffect = skill?.特殊效果;
                    const effectMap = {};

                    if (typeof rawEffect === 'string') {
                        const txt = rawEffect.trim();
                        if (txt) effectMap['1'] = txt;
                    } else if (rawEffect && typeof rawEffect === 'object' && !Array.isArray(rawEffect)) {
                        for (const [k, v] of Object.entries(rawEffect)) {
                            const txt = String(v || '').trim();
                            if (!txt) continue;
                            const m = String(k).match(/\d+/);
                            if (!m) continue;
                            const lv = parseInt(m[0], 10);
                            if (Number.isFinite(lv) && lv >= 1) {
                                effectMap[String(lv)] = txt;
                            }
                        }
                    }

                    const levels = Object.keys(effectMap).map(n => parseInt(n, 10)).filter(Number.isFinite).sort((a, b) => a - b);
                    if (levels.length === 0) {
                        return { '1': '无' };
                    }

                    // 职业特殊技能不升级，只保留1级效果
                    if (type === '职业特殊') {
                        const firstLv = levels[0];
                        return { '1': effectMap['1'] || effectMap[String(firstLv)] };
                    }

                    if (strictMode) {
                        const strictNormalized = {};
                        for (let lv = 1; lv <= maxLevel; lv++) {
                            if (effectMap[String(lv)]) strictNormalized[String(lv)] = effectMap[String(lv)];
                        }
                        return Object.keys(strictNormalized).length > 0 ? strictNormalized : { '1': '无' };
                    }

                    // 补齐1..maxLevel每一级，缺失等级沿用最近低等级效果，保证升级读取稳定
                    const firstLv = levels[0];
                    const firstText = effectMap[String(firstLv)];
                    for (let lv = 1; lv < firstLv; lv++) effectMap[String(lv)] = firstText;
                    let cursor = firstText;
                    for (let lv = firstLv; lv <= maxLevel; lv++) {
                        if (effectMap[String(lv)]) cursor = effectMap[String(lv)];
                        else effectMap[String(lv)] = cursor;
                    }

                    const normalized = {};
                    for (let lv = 1; lv <= maxLevel; lv++) {
                        if (effectMap[String(lv)]) normalized[String(lv)] = effectMap[String(lv)];
                    }
                    return Object.keys(normalized).length > 0 ? normalized : { '1': '无' };
                };

                const buildSkillSoftWarningsForTree = (tree) => {
                    const warningTree = {};
                    if (!tree || typeof tree !== 'object') return warningTree;

                    const pushWarning = (tierKey, skillName, message) => {
                        if (!tierKey || !skillName || !message) return;
                        if (!warningTree[tierKey]) warningTree[tierKey] = {};
                        if (!warningTree[tierKey][skillName]) warningTree[tierKey][skillName] = [];
                        const list = warningTree[tierKey][skillName];
                        if (!list.includes(message)) list.push(message);
                    };

                    const hasForbiddenCooldownChange = (effect) => {
                        if (!effect) return false;
                        if (typeof effect === 'string') return FORBIDDEN_COOLDOWN_CHANGE_REGEX.test(effect);
                        if (typeof effect === 'object' && !Array.isArray(effect)) {
                            return Object.values(effect).some(v => FORBIDDEN_COOLDOWN_CHANGE_REGEX.test(String(v || '')));
                        }
                        return false;
                    };

                    const getExpectedLevelCount = (tierKey, skill) => {
                        const rawTierKey = String(tierKey || '').trim();
                        if (rawTierKey.includes('觉醒')) {
                            const stage = AWAKENING_STAGE_MAP[String(skill?.阶位 || rawTierKey).trim()] || rawTierKey;
                            return Math.max(1, parseInt(SKILL_TIER_CONFIG[stage]?.等级上限, 10) || 1);
                        }
                        if (String(skill?.类型 || '').trim() === '职业特殊') return 1;
                        const mappedTier = SKILL_TIER_KEY_MAP[rawTierKey] || rawTierKey;
                        return Math.max(1, parseInt(SKILL_TIER_CONFIG[mappedTier]?.等级上限, 10) || 1);
                    };

                    const getAdjacentDuplicateLevels = (effect) => {
                        if (!effect || typeof effect !== 'object' || Array.isArray(effect)) return [];
                        const keys = Object.keys(effect)
                            .map(k => parseInt(String(k), 10))
                            .filter(Number.isFinite)
                            .sort((a, b) => a - b);
                        const duplicates = [];
                        let previousText = null;
                        let previousLevel = null;
                        for (const level of keys) {
                            const currentText = String(effect[String(level)] || '').replace(/\s+/g, ' ').trim();
                            if (previousText != null && currentText && currentText === previousText) {
                                duplicates.push([previousLevel, level]);
                            }
                            previousText = currentText;
                            previousLevel = level;
                        }
                        return duplicates;
                    };

                    for (const [tierKey, skills] of Object.entries(tree)) {
                        if (!Array.isArray(skills)) continue;
                        const isAwakeningTier = String(tierKey || '').includes('觉醒');
                        for (const skill of skills) {
                            const isAwakeningSkill = isAwakeningTier || String(skill?.阶位 || '').includes('觉醒');
                            const skillName = skill?.名称 || '未命名技能';
                            const skillType = String(skill?.类型 || '主动').trim() || '主动';
                            if (!VALID_MVU_SKILL_TYPES.has(skillType)) {
                                pushWarning(tierKey, skillName, `${ILLEGAL_SKILL_TYPE_WARNING_PREFIX}：${skillType}`);
                            }

                            const effect = skill?.特殊效果;
                            const effectKeys = (effect && typeof effect === 'object' && !Array.isArray(effect))
                                ? Object.keys(effect).filter(k => /^\d+$/.test(String(k)))
                                : [];
                            const expectedLevelCount = getExpectedLevelCount(tierKey, skill);
                            if (effectKeys.length !== expectedLevelCount) {
                                pushWarning(tierKey, skillName, `特殊效果等级数量不足或不匹配：当前 ${effectKeys.length} / 应为 ${expectedLevelCount}`);
                            }
                            if (effectKeys.some(k => String(effect[k] || '').trim() === '待补完')) {
                                pushWarning(tierKey, skillName, '特殊效果仍存在“待补完”占位文本');
                            }
                            const duplicateLevels = getAdjacentDuplicateLevels(effect);
                            if (duplicateLevels.length > 0) {
                                const pairs = duplicateLevels.map(([a, b]) => `${a}-${b}`).join('、');
                                pushWarning(tierKey, skillName, `特殊效果存在连续重复等级：${pairs}`);
                            }

                            if (isAwakeningSkill) continue; // 觉醒技能不做机制类软校验
                            if (hasForbiddenCooldownChange(skill?.特殊效果)) {
                                pushWarning(tierKey, skillName, '特殊效果包含冷却变化，无法适用');
                            }
                        }
                    }
                    return warningTree;
                };

                // 将AI生成的技能树转换为MVU格式
                const convertSkillTreeToMvuFormat = (aiSkillTree, className) => {
                    if (!aiSkillTree) return null;

                    const skillList = {};
                    const normalizeMvuSkillType = (type) => {
                        const normalizedType = String(type || '主动').trim() || '主动';
                        return VALID_MVU_SKILL_TYPES.has(normalizedType) ? normalizedType : '特殊';
                    };

                    // 遍历每个阶位
                    for (const [tierKey, skills] of Object.entries(aiSkillTree)) {
                        if (!Array.isArray(skills)) continue;

                        const mappedTier = SKILL_TIER_KEY_MAP[tierKey] || tierKey;

                        for (const skill of skills) {
                            // 觉醒技能使用技能自身的阶位字段
                            const skillTier = (tierKey === '觉醒' && skill.阶位) ? skill.阶位 : mappedTier;
                            const tierConfig = SKILL_TIER_CONFIG[skillTier] || SKILL_TIER_CONFIG['基础'];
                            const normalizedEffect = normalizeSkillSpecialEffect(skill, tierConfig) || { '1': '无' };
                            const normalizedType = normalizeMvuSkillType(skill.类型);

                            skillList[skill.名称] = {
                                名称: skill.名称,
                                类型: normalizedType,
                                阶位: skillTier,
                                描述: skill.描述 || '',
                                召唤物名称: skill.召唤物名称 || '',
                                特殊效果: normalizedEffect,
                                习得等级: tierConfig.习得等级,
                                等级上限: tierConfig.等级上限,
                                SP消耗: tierConfig.SP消耗,
                                冷却: 0,
                                伤害倍率: 0,
                                当前等级: 0,
                                是否装备: false
                            };
                        }
                    }

                    return {
                        技能列表: skillList,
                        总SP: 0,
                        已使用SP: 0
                    };
                };

                // 根据等级和种族计算开局成长资源（对齐辅助计算脚本）
                const getStartingGrowthRewards = (level, raceName) => {
                    const safeLevel = Math.max(1, parseInt(level, 10) || 1);
                    const spPerLevel = raceName === '森精种' ? 30 : 25;
                    return {
                        totalSP: Math.max(0, (safeLevel - 1) * spPerLevel),
                        attributePoints: Math.floor(safeLevel / 10)
                    };
                };

                // 与辅助计算脚本保持一致：返回“累计总经验阈值”
                const calculateDiabloThreshold = (targetLevel) => {
                    const safeTarget = Math.max(1, parseInt(targetLevel, 10) || 1);
                    if (safeTarget <= 1) return 0;
                    let total = 0;
                    for (let L = 1; L < safeTarget; L++) {
                        total += Math.floor(100 * Math.pow(L, 1.5));
                    }
                    return total;
                };

                const getStartingExpSnapshot = (level) => {
                    const safeLevel = Math.max(1, parseInt(level, 10) || 1);
                    return {
                        currentTotalExp: calculateDiabloThreshold(safeLevel),
                        nextLevelThreshold: calculateDiabloThreshold(safeLevel + 1)
                    };
                };

                const stripStarterShopEquipment = (equipmentList) => {
                    const cleaned = {};
                    Object.entries(equipmentList || {}).forEach(([key, equip]) => {
                        const tags = Array.isArray(equip?.标签) ? equip.标签 : [];
                        if (tags.includes(STARTER_SHOP_MVU_TAG)) return;
                        cleaned[key] = equip;
                    });
                    return cleaned;
                };

                const buildStarterShopEquipmentKey = (equipmentList, baseName) => {
                    const safeBase = String(baseName || '开局装备').trim() || '开局装备';
                    if (!equipmentList[safeBase]) return safeBase;
                    let suffix = 2;
                    while (equipmentList[`${safeBase}_${suffix}`]) {
                        suffix += 1;
                    }
                    return `${safeBase}_${suffix}`;
                };

                const appendStarterShopEquipmentToMvu = (equipmentList, items, level, combatValueMode = DEFAULT_OPENING_COMBAT_VALUE_MODE) => {
                    const nextEquipment = stripStarterShopEquipment(equipmentList);
                    const safeLevel = Math.max(1, Math.floor(Number(level) || 1));
                    (Array.isArray(items) ? items : []).forEach((item) => {
                        if (!item) return;
                        const equipKey = buildStarterShopEquipmentKey(nextEquipment, item.名称);
                        nextEquipment[equipKey] = {
                            类型: item.类型 || '武器',
                            部位: item.部位 || '主手',
                            名称: item.名称 || equipKey,
                            品质: item.品质 || '精良',
                            标签: Array.from(new Set([...(item.标签 || []), STARTER_SHOP_MVU_TAG])),
                            等级: safeLevel,
                            品级: 0,
                            强化等级: 0,
                            属性加成: { ...(item.属性加成 || {}) },
                            效果: getStarterShopItemEffect(item, combatValueMode),
                            描述: item.描述 || '',
                            装备箱: true
                        };
                    });
                    return nextEquipment;
                };

                // 将角色数据写入MVU
                const saveCharacterToMvu = async () => {
                    // 保存头像到浏览器缓存（确保状态栏能读取）
                    if (character.avatar) {
                        try { localStorage.setItem('rpg_player_avatar', character.avatar); } catch (err) { console.warn('[RPG开局] 头像存储失败:', err); }
                    }

                    const mvu = getMvuApi();
                    if (!mvu) {
                        console.error('[RPG开局] MVU API不可用');
                        alert('MVU系统不可用，无法保存角色数据');
                        return false;
                    }

                    try {
                        // 1. 获取当前MVU数据
                        const mvuData = mvu.getMvuData({ type: 'message', message_id: 'latest' });
                        if (!mvuData) {
                            console.error('[RPG开局] 无法获取MVU数据');
                            alert('无法获取游戏数据');
                            return false;
                        }

                        // 确保stat_data存在
                        if (!mvuData.stat_data) {
                            mvuData.stat_data = {};
                        }

                        // 2. 转换技能树
                        const mvuSkillTree = convertSkillTreeToMvuFormat(skillTreeData.value, character.class);

                        // 3. 获取种族信息（兼容自定义种族）
                        const isCustomRace = character.race === '__custom__' && customRace.enabled;
                        const race = isCustomRace ? currentRace.value : availableRaces.value.find(r => r.name === character.race);
                        const actualRaceName = isCustomRace ? (customRace.name || '自定义种族') : character.race;
                        const startLevel = actualStartLevel.value;
                        const openingCombatValueMode = currentOpeningCombatValueMode.value;
                        const backgroundSettingText = effectiveBackgroundDesc.value || (isSaoOpeningSelected.value ? '' : (character.backstory || ''));
                        const growthRewards = getStartingGrowthRewards(startLevel, actualRaceName);
                        const expSnapshot = getStartingExpSnapshot(startLevel);
                        const shouldGrantAmberHumanFateCard = isAmberWorldview.value && !isCustomRace && actualRaceName === AMBER_HUMAN_RACE_NAME;
                        const existingResourceSkills = (mvuData.stat_data.人物 && mvuData.stat_data.人物.资源技能 && typeof mvuData.stat_data.人物.资源技能 === 'object')
                            ? mvuData.stat_data.人物.资源技能
                            : {};
                        const nextResourceSkills = applyOpeningModeEffectsToResourceSkills(cloneOpeningValue(existingResourceSkills) || {}, openingCombatValueMode);
                        delete nextResourceSkills[AMBER_HUMAN_FATE_CARD_NAME];
                        if (shouldGrantAmberHumanFateCard) {
                            nextResourceSkills[AMBER_HUMAN_FATE_CARD_NAME] = applyOpeningModeEffectToSkill(buildAmberHumanFateCard(), openingCombatValueMode);
                        }

                        delete nextResourceSkills[DRAGON_LOCK_SKILL_NAME];
                        if (isDragonWorldview.value && actualRaceName === '青春期男高') {
                            nextResourceSkills[DRAGON_LOCK_SKILL_NAME] = applyOpeningModeEffectToSkill(buildDragonLockSkill(), openingCombatValueMode);
                        }

                        // 4. 计算最终属性 (基础属性 + 种族加成)
                        const finalAttributes = {};
                        const attrMap = {
                            strength: '力量',
                            dexterity: '敏捷',
                            constitution: '体质',
                            intelligence: '智力',
                            wisdom: '感知',
                            charisma: '魅力'
                        };
                        for (const [engKey, cnKey] of Object.entries(attrMap)) {
                            const base = character.attributes[engKey] || 10;
                            const bonus = race?.bonuses?.[engKey] || 0;
                            finalAttributes[cnKey] = base + bonus;
                        }

                        // 5. 计算生命值上限（新版战斗数值）
                        const maxHp = calcOpeningMaxHp(startLevel, finalAttributes);

                        // 6. 构建种族特性 → 写入状态效果（永久BUFF）
                        const raceBuffs = {};
                        const buildRaceBuffData = (buff) => {
                            const modeSpecificEffect = selectOpeningModeEffect(buff, openingCombatValueMode);
                            const specialEffect = String(modeSpecificEffect !== undefined ? modeSpecificEffect : (buff?.detail || '')).trim();
                            return {
                                类型: buff?.negative ? 'DEBUFF' : 'BUFF',
                                持续时间: '永久',
                                属性影响: {},
                                特殊影响: specialEffect
                            };
                        };
                        // 处理自定义种族（与普通种族使用相同的写入格式）
                        if (isCustomRace) {
                            if (customRace.trait1.name) {
                                const buffKey = `[种族·${customRace.trait1.name}]`;
                                raceBuffs[buffKey] = buildRaceBuffData({
                                    negative: customRace.trait1.negative,
                                    detail: customRace.trait1.detail
                                });
                            }
                            if (customRace.trait2.name) {
                                const buffKey = `[种族·${customRace.trait2.name}]`;
                                raceBuffs[buffKey] = buildRaceBuffData({
                                    negative: customRace.trait2.negative,
                                    detail: customRace.trait2.detail
                                });
                            }
                        }
                        if (race?.buffs) {
                            for (const buff of race.buffs) {
                                if (isDragonWorldview.value && DRAGON_SELECTION_ONLY_BUFF_NAMES.has(buff.name)) continue;
                                const buffKey = `[种族·${buff.name}]`;
                                raceBuffs[buffKey] = buildRaceBuffData(buff);
                            }
                        }
                        if (isEarthseaWorldview.value && Array.isArray(race?.initialTraits)) {
