                                // 高阶强者(法露特95/璐米欧儿85)等级固定，其余队友等级与主角一致
                                if (!FIXED_LEVEL_TEAMMATE_NAMES.has(t.name)) {
                                    mateData.等级 = startLevel;
                                }
                                mvuData.stat_data.羁绊列表[t.name] = applyOpeningModeEffectsToBond(mateData, openingCombatValueMode);
                            } else {
                                // 兜底：避免新增队友遗漏导致不写入MVU
                                console.warn(`[RPG开局] 队友缺少预设档案，使用兜底写入: ${t.name || t.id}`);
                                const fallbackMateData = {
                                    性别: '未知',
                                    种族: t.race || '未知',
                                    等级: t.name === '法露特' ? 95 : startLevel,
                                    属性: { 力量: 10, 敏捷: 10, 体质: 10, 智力: 10, 感知: 10, 魅力: 10 },
                                    装备列表: {},
                                    技能: {},
                                    外貌: t.desc || '',
                                    着装: '',
                                    好感度: Number.isFinite(t.affinity) ? t.affinity : 10,
                                    同行誓约: false,
                                    连携奥义: {}
                                };
                                if (t.skill) {
                                    fallbackMateData.技能['固有能力'] = {
                                        品质: '普通',
                                        类型: '特殊',
                                        效果: t.skill,
                                        描述: t.skill
                                    };
                                }
                                const teammateKey = t.name || t.id || '未知队友';
                                mvuData.stat_data.羁绊列表[teammateKey] = applyOpeningModeEffectsToBond(fallbackMateData, openingCombatValueMode);
                            }
                        });

                        // 诡秘地海：队友与玩家使用同一套 SAN 初始化口径。
                        if (isEarthseaWorldview.value) {
                            Object.values(mvuData.stat_data.羁绊列表).forEach(initializeEarthseaSan);
                        }

                        // 同时初始化CP
                        mvuData.stat_data.人物.CP = 0;

                        // 9. 写入MVU
                        await mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });

                        console.log('[RPG开局] 角色数据已保存到MVU:', mvuData.stat_data);
                        return true;
                    } catch (e) {
                        console.error('[RPG开局] 保存角色数据失败:', e);
                        alert('保存角色数据失败: ' + e.message);
                        return false;
                    }
                };

