                // 处理地图世界书开关（🌋🌏🗺️标记的条目）
                async function applyMapWorldbook(enable) {
                    const MAP_TAGS = ['🌋', '🌏', '🗺️'];
                    try {
                        let wb = null;
                        if (typeof getCharWorldbookNames === 'function') {
                            wb = getCharWorldbookNames('current').primary;
                        }
                        if (!wb) {
                            console.warn('[地图世界书] 世界书未初始化，跳过');
                            return;
                        }
                        if (typeof getWorldbook !== 'function' || typeof replaceWorldbook !== 'function') {
                            console.warn('[地图世界书] 世界书API不可用');
                            return;
                        }
                        const allEntries = await getWorldbook(wb);
                        let changed = false;
                        const updated = allEntries.map(entry => {
                            if (entry.name && MAP_TAGS.some(tag => entry.name.includes(tag))) {
                                if (entry.enabled !== enable) {
                                    changed = true;
                                    return { ...entry, enabled: enable };
                                }
                            }
                            return entry;
                        });
                        if (changed) {
                            await replaceWorldbook(wb, updated);
                            console.log(`[地图世界书] 已${enable ? '启用' : '禁用'}地图世界书条目`);
                        }
                    } catch (e) {
                        console.error('[地图世界书] 操作失败:', e);
                    }
                }

                // 按世界观处理世界书（名称匹配规则）：
                // - 创世回廊：关闭 SAO/琥珀，打开 创世回廊/DNF/NGNL/西幻
                // - 刀剑神域：关闭 琥珀/DNF/NGNL，打开 创世回廊/SAO/西幻（并强制关闭地图世界书）
                // - 琥珀之剑：关闭 创世回廊/SAO/DNF/NGNL，打开 全部带“琥珀”或“西幻”的世界书
                // - 大明志异：关闭 创世回廊/SAO/琥珀/DNF/NGNL/西幻，打开 全部带“大明”的世界书
                // 注意：英文关键词仅按大写严格匹配（SAO/DNF/NGNL）
                async function applyOpeningWorldbookRules() {
                    const MAP_TAGS = ['🌋', '🌏', '🗺️'];
                    const TOKEN_CORRIDOR = '创世回廊';
                    const TOKEN_SAO = 'SAO';
                    const TOKEN_DNF = 'DNF';
                    const TOKEN_NGNL = 'NGNL';
                    const TOKEN_AMBER = '琥珀';
                    const TOKEN_JIUZHOU = '大明';
                    const TOKEN_DRAGON = ['都市'];
                    const TOKEN_EARTHSEA = ['诡秘地海', '地海'];
                    const TOKEN_SOLARIS = ['索拉里斯','鸣潮'];
                    const TOKEN_WESTERN_FANTASY = '西幻';
                    const NIGHTMARE_ENTRY_NAME = '任务链 - 明焰与梦魇【琥珀】';
                    const worldview = selectedWorldview.value || WORLDVIEW_CORRIDOR_ID;
                    const isCorridorOpening = worldview === WORLDVIEW_CORRIDOR_ID;
                    const isNightmareOpening = worldview === WORLDVIEW_AMBER_ID && selectedOpening.value === 'amber_nightmare';
                    const mapWorldbookTarget = isCorridorOpening ? !!enableMapWorldbook.value : false;
                    let openTokens;
                    let closeTokens;
                    if(worldview===WORLDVIEW_SOLARIS_ID){
                        openTokens=TOKEN_SOLARIS;
                        closeTokens=[TOKEN_CORRIDOR,TOKEN_SAO,TOKEN_DNF,TOKEN_NGNL,TOKEN_AMBER,TOKEN_JIUZHOU,TOKEN_WESTERN_FANTASY,...TOKEN_DRAGON,...TOKEN_EARTHSEA];
                    } else if (worldview === WORLDVIEW_AMBER_ID) {
                        openTokens = [TOKEN_AMBER, TOKEN_WESTERN_FANTASY];
                        closeTokens = [TOKEN_CORRIDOR, TOKEN_SAO, TOKEN_DNF, TOKEN_NGNL, TOKEN_JIUZHOU, ...TOKEN_DRAGON, ...TOKEN_EARTHSEA, ...TOKEN_SOLARIS];
                    } else if (worldview === WORLDVIEW_JIUZHOU_ID) {
                        openTokens = [TOKEN_JIUZHOU];
                        closeTokens = [TOKEN_CORRIDOR, TOKEN_SAO, TOKEN_AMBER, TOKEN_DNF, TOKEN_NGNL, TOKEN_WESTERN_FANTASY, ...TOKEN_DRAGON, ...TOKEN_EARTHSEA, ...TOKEN_SOLARIS];
                    } else if (worldview === WORLDVIEW_DRAGON_ID) {
                        openTokens = [...TOKEN_DRAGON];
                        closeTokens = [TOKEN_CORRIDOR, TOKEN_SAO, TOKEN_AMBER, TOKEN_JIUZHOU, TOKEN_DNF, TOKEN_NGNL, TOKEN_WESTERN_FANTASY, ...TOKEN_EARTHSEA, ...TOKEN_SOLARIS];
                    } else if (worldview === WORLDVIEW_EARTHSEA_ID) {
                        openTokens = TOKEN_EARTHSEA;
                        closeTokens = [TOKEN_CORRIDOR, TOKEN_SAO, TOKEN_AMBER, TOKEN_JIUZHOU, TOKEN_DNF, TOKEN_NGNL, TOKEN_WESTERN_FANTASY, ...TOKEN_DRAGON, ...TOKEN_SOLARIS];
                    } else if (worldview === WORLDVIEW_SAO_ID) {
                        openTokens = [TOKEN_CORRIDOR, TOKEN_SAO, TOKEN_WESTERN_FANTASY];
                        closeTokens = [TOKEN_AMBER, TOKEN_DNF, TOKEN_NGNL, TOKEN_JIUZHOU, ...TOKEN_DRAGON, ...TOKEN_EARTHSEA, ...TOKEN_SOLARIS];
                    } else {
                        openTokens = [TOKEN_CORRIDOR, TOKEN_DNF, TOKEN_NGNL, TOKEN_WESTERN_FANTASY];
                        closeTokens = [TOKEN_SAO, TOKEN_AMBER, TOKEN_JIUZHOU, ...TOKEN_DRAGON, ...TOKEN_EARTHSEA, ...TOKEN_SOLARIS];
                    }

                    if (!isCorridorOpening && enableMapWorldbook.value) {
                        enableMapWorldbook.value = false;
                    }

                    try {
                        if (typeof getWorldbook !== 'function' || typeof replaceWorldbook !== 'function') {
                            console.warn('[开局世界书] 世界书API不可用');
                            return;
                        }
                        const worldbookNameSet = new Set();
                        if (typeof getCharWorldbookNames === 'function') {
                            const charWorldbooks = getCharWorldbookNames('current') || {};
                            if (charWorldbooks.primary) worldbookNameSet.add(charWorldbooks.primary);
                            if (Array.isArray(charWorldbooks.additional)) {
                                charWorldbooks.additional.forEach(name => {
                                    if (name) worldbookNameSet.add(name);
                                });
                            }
                        }
                        if (typeof getChatWorldbookName === 'function') {
                            const chatWorldbook = getChatWorldbookName('current');
                            if (chatWorldbook) worldbookNameSet.add(chatWorldbook);
                        }
                        if (typeof getGlobalWorldbookNames === 'function') {
                            const globalWorldbooks = getGlobalWorldbookNames() || [];
                            globalWorldbooks.forEach(name => {
                                if (name) worldbookNameSet.add(name);
                            });
                        }
                        const worldbookNames = Array.from(worldbookNameSet);
                        if (worldbookNames.length === 0) {
                            console.warn('[开局世界书] 未找到可操作的世界书，跳过');
                            return;
                        }

                        let changed = false;
                        let changedWorldbookCount = 0;
                        let worldviewRuleChanged = 0;
                        let mapChanged = 0;

                        for (const wb of worldbookNames) {
                            const allEntries = await getWorldbook(wb);
                            let currentWorldbookChanged = false;

                            const updated = allEntries.map(entry => {
                                const name = String(entry?.name || '');
                                if(['鸣潮副本资料','鸣潮伴星任务资料','地图静态资料 - 索拉里斯'].includes(name)) {
                                  if(entry.enabled!==false){currentWorldbookChanged=true;worldviewRuleChanged++;return {...entry,enabled:false};}
                                  return entry;
                                }
                                const hasAnyOpenToken = openTokens.some(token => name.includes(token));
                                const hasAnyCloseToken = closeTokens.some(token => name.includes(token));
                                const hasMapTag = MAP_TAGS.some(tag => name.includes(tag));
                                let nextEnabled = entry.enabled;
                                let entryChanged = false;

                                // 梦魇任务链：精确匹配条目名，仅在选择"梦魇"开局时开启，其余情况一律关闭（优先级最高）
                                if (name === NIGHTMARE_ENTRY_NAME) {
                                    if (nextEnabled !== isNightmareOpening) {
                                        nextEnabled = isNightmareOpening;
                                        entryChanged = true;
                                        worldviewRuleChanged++;
                                    }
                                    if (entryChanged) {
                                        currentWorldbookChanged = true;
                                        return { ...entry, enabled: nextEnabled };
                                    }
                                    return entry;
                                }

                                // 世界观关键词命中时优先应用世界观规则。
                                // 若同时命中"打开词"和"关闭词"，以"关闭词"优先，避免误开。
                                if (hasAnyOpenToken || hasAnyCloseToken) {
                                    const worldviewTarget = hasAnyCloseToken ? false : true;
                                    if (nextEnabled !== worldviewTarget) {
                                        nextEnabled = worldviewTarget;
                                        entryChanged = true;
                                        worldviewRuleChanged++;
                                    }
                                }

                                // 仅在未命中世界观关键词时，地图标签才按地图开关接管
                                if (!hasAnyOpenToken && !hasAnyCloseToken && hasMapTag && nextEnabled !== mapWorldbookTarget) {
                                    nextEnabled = mapWorldbookTarget;
                                    entryChanged = true;
                                    mapChanged++;
                                }

                                if (entryChanged) {
                                    currentWorldbookChanged = true;
                                    return { ...entry, enabled: nextEnabled };
                                }
                                return entry;
                            });

                            if (currentWorldbookChanged) {
                                changed = true;
                                changedWorldbookCount++;
                                await replaceWorldbook(wb, updated);
                            }
                        }

                        if (changed) {
                            const worldviewLabel = getWorldviewMvuLabel(worldview);
                            console.log(`[开局世界书] 已按${worldviewLabel}规则应用。涉及世界书=${changedWorldbookCount}/${worldbookNames.length}，变更数量：世界观规则=${worldviewRuleChanged}，地图=${mapChanged}`);
                        } else {
                            console.log('[开局世界书] 当前状态已符合规则，无需变更');
                        }
                    } catch (e) {
                        console.error('[开局世界书] 操作失败:', e);
                    }
                }

                // 收集不能量化的配置并发送开局初始化指令到酒馆
                function sendStartMessage() {
