                    const isCustomRaceMsg = character.race === '__custom__' && customRace.enabled;
                    const race = isCustomRaceMsg ? currentRace.value : availableRaces.value.find(r => r.name === character.race);
                    const actualRaceNameMsg = isCustomRaceMsg ? (customRace.name || '自定义种族') : character.race;
                    const worldview = selectedWorldview.value || WORLDVIEW_CORRIDOR_ID;
                    const opening = selectedOpening.value;
                    const isSaoOpening = worldview === WORLDVIEW_SAO_ID;
                    const isAmberWorld = worldview === WORLDVIEW_AMBER_ID;
                    const isJiuzhouWorld = worldview === WORLDVIEW_JIUZHOU_ID;
                    const isDragonWorld = worldview === WORLDVIEW_DRAGON_ID;
