                    if(isSolarisWorld){const origin=solarisRaces.find(x=>x.name===actualRaceNameMsg);config.代码已注册={特质:[...(origin?.buffs||[]),...(origin?.initialTraits||[])].map(x=>x.name),熟练度:(origin?.initialProficiencies||[]).map(x=>x.name+'·'+x.tier),资源技能:(origin?.initialResourceSkills||[]).map(x=>x.name),说明:'这些能力已写入人物数据，不要重复创建或重复加成；精通特质、熟练度与附带技能均已分别登记。'};config.角色信息.出身=actualRaceNameMsg;config.角色信息.种族='人类';config.角色信息.身份=currentIdentityObj.value?.name||character.identity||'';config.角色信息.身份描述=currentIdentityObj.value?.desc||'';config.角色信息.背景设定=effectiveBackgroundDesc.value||character.backstory||'';}
                    if (isEarthseaWorld) {
                        config.角色信息.出身 = actualRaceNameMsg;
                        const origin = earthseaWorldviewRaces.find(item => item.name === actualRaceNameMsg);
                        config.角色信息.种族 = origin?.raceName || '人类';
