                            核心资产: ['次元房东', '黄金渔岛', '妖怪便利店夜班员'].includes(actualRaceNameMsg)
                                ? ({ 次元房东: '次元公寓', 黄金渔岛: '黄金渔岛', 妖怪便利店夜班员: '零点便利店' })[actualRaceNameMsg]
                                : '无',
