                };

                // 默认占位图标
                const DEFAULT_SVG_PATH = 'M64 64h384v384H64z';

                // 获取技能SVG图标
                function getSkillIcon(type, tierKey) {
                    let mainType = '主动';
                    if (type === '召唤') mainType = '召唤';
                    else if (type === '特殊' || type === '被动' || type === '辅助') mainType = '特殊';
                    else if (type === '职业特殊') mainType = '职业特殊';

                    let pathData = '';
                    if (mainType === '职业特殊') {
                        pathData = SKILL_SVG_PATHS['职业特殊'] || '';
                    } else {
                        // 从tierKey提取阶位，如 "Tier1" 或 "觉醒一"
                        let tier = 'Tier1';
                        if (tierKey) {
                            if (tierKey.includes('觉醒')) {
                                // 觉醒一/觉醒二/觉醒三
                                tier = tierKey;
                            } else if (tierKey.includes('Tier')) {
                                tier = tierKey.match(/Tier\d/)?.[0] || 'Tier1';
                            }
                        }
                        pathData = SKILL_SVG_PATHS[mainType]?.[tier] || '';
                    }

                    const finalPath = pathData || DEFAULT_SVG_PATH;
                    const opacity = pathData ? '1' : '0.5';

                    return `<svg class="skill-icon-svg" viewBox="0 0 512 512" xmlns="http://www.w3.org/2000/svg" style="opacity:${opacity}"><path fill="currentColor" d="${finalPath}"/></svg>`;
                }

                // ==================== 动态技能树生成 ====================
                const isGeneratingSkills = ref(false);
                const skillTreeData = ref(null);
                const skillTreeForClass = ref(null); // 记录技能树是为哪个职业生成的
                const skillGenerationError = ref('');
                const skillFlavorInput = ref('');
                const usePresetAndWorldbook = ref(false); // 是否带预设和世界书生成（默认关闭）
                const useSegmentedSkillGeneration = ref(true); // 是否分两步生成（默认开启）
                const generationTimer = ref(0);
                const skillGenerationPhaseText = ref('');
                const showSkillReadyBubble = ref(false);
                const lockedSkillMap = ref({}); // { [className]: { [tierKey]: { [skillName]: skillObj } } }
                const skillSoftWarningMap = ref({}); // { [className]: { [tierKey]: { [skillName]: string[] } } }
                let timerInterval = null;
                const VALID_MVU_SKILL_TYPES = new Set(['主动', '特殊', '召唤', '职业特殊']);
                const ILLEGAL_SKILL_TYPE_WARNING_PREFIX = '非法类型技能';

                const cloneJson = (value) => {
                    if (value == null) return value;
                    try {
                        return JSON.parse(JSON.stringify(value));
                    } catch (e) {
                        console.warn('[技能树锁定] 深拷贝失败，返回原值:', e);
                        return value;
                    }
                };

                const isSkillLocked = (tierKey, skillName, className = character.class) => {
                    if (!className || !tierKey || !skillName) return false;
                    return !!lockedSkillMap.value?.[className]?.[tierKey]?.[skillName];
                };

                const hasSkillSoftWarning = (tierKey, skillName, className = character.class) => {
                    if (!className || !tierKey || !skillName) return false;
                    const list = skillSoftWarningMap.value?.[className]?.[tierKey]?.[skillName];
                    return Array.isArray(list) && list.length > 0;
                };

                const getSkillSoftWarnings = (tierKey, skillName, className = character.class) => {
                    if (!className || !tierKey || !skillName) return [];
                    const list = skillSoftWarningMap.value?.[className]?.[tierKey]?.[skillName];
                    return Array.isArray(list) ? list : [];
                };

                const hasSkillHardWarning = (tierKey, skillName, className = character.class) => {
                    return getSkillSoftWarnings(tierKey, skillName, className).some(msg => String(msg || '').startsWith(ILLEGAL_SKILL_TYPE_WARNING_PREFIX));
                };

                const setClassSkillSoftWarnings = (className, warningTree) => {
                    if (!className) return;
                    const next = cloneJson(skillSoftWarningMap.value) || {};
                    if (warningTree && Object.keys(warningTree).length > 0) {
                        next[className] = warningTree;
                    } else {
                        delete next[className];
                    }
                    skillSoftWarningMap.value = next;
                };

                const currentSkillWarningCount = computed(() => {
                    const className = character.class;
                    if (!className) return 0;
                    const classWarnings = skillSoftWarningMap.value?.[className];
                    if (!classWarnings || typeof classWarnings !== 'object') return 0;
                    let count = 0;
                    for (const tierWarnings of Object.values(classWarnings)) {
                        if (!tierWarnings || typeof tierWarnings !== 'object') continue;
                        for (const list of Object.values(tierWarnings)) {
                            if (Array.isArray(list) && list.length > 0) count++;
                        }
                    }
                    return count;
                });

                const currentSkillHardWarningCount = computed(() => {
                    const className = character.class;
                    if (!className) return 0;
                    const classWarnings = skillSoftWarningMap.value?.[className];
                    if (!classWarnings || typeof classWarnings !== 'object') return 0;
                    let count = 0;
                    for (const tierWarnings of Object.values(classWarnings)) {
                        if (!tierWarnings || typeof tierWarnings !== 'object') continue;
                        for (const list of Object.values(tierWarnings)) {
                            if (Array.isArray(list) && list.some(msg => String(msg || '').startsWith(ILLEGAL_SKILL_TYPE_WARNING_PREFIX))) count++;
                        }
                    }
                    return count;
                });

                const currentSkillSoftWarningCount = computed(() => Math.max(0, currentSkillWarningCount.value - currentSkillHardWarningCount.value));

                const toggleSkillLock = (tierKey, skill) => {
                    const className = character.class;
                    const skillName = skill?.名称;
                    if (!className || !tierKey || !skillName) return;

                    const nextLockedMap = cloneJson(lockedSkillMap.value) || {};
                    const classLocks = nextLockedMap[className] || {};
                    const tierLocks = classLocks[tierKey] || {};

                    if (tierLocks[skillName]) {
                        delete tierLocks[skillName];
                        if (Object.keys(tierLocks).length === 0) {
                            delete classLocks[tierKey];
                        } else {
                            classLocks[tierKey] = tierLocks;
                        }
                    } else {
                        tierLocks[skillName] = cloneJson(skill);
                        classLocks[tierKey] = tierLocks;
                    }

                    if (Object.keys(classLocks).length === 0) {
                        delete nextLockedMap[className];
                    } else {
                        nextLockedMap[className] = classLocks;
                    }
                    lockedSkillMap.value = nextLockedMap;
                };

                const applyLockedSkillsToTree = (className, tree) => {
                    if (!className || !tree || typeof tree !== 'object') return tree;
                    const classLocks = lockedSkillMap.value?.[className];
                    if (!classLocks || typeof classLocks !== 'object') return tree;

                    const mergedTree = cloneJson(tree) || {};
                    for (const [tierKey, tierLocks] of Object.entries(classLocks)) {
                        if (!tierLocks || typeof tierLocks !== 'object') continue;
                        if (!Array.isArray(mergedTree[tierKey])) {
                            mergedTree[tierKey] = [];
                        }

                        const skills = mergedTree[tierKey];
                        const usedReplaceIndexes = new Set();
                        for (const [skillName, lockedSkill] of Object.entries(tierLocks)) {
                            if (!skillName || !lockedSkill) continue;
                            const lockedSkillClone = cloneJson(lockedSkill);

                            // 1) 同名技能优先覆盖
                            let idx = skills.findIndex((item, i) => !usedReplaceIndexes.has(i) && item?.名称 === skillName);

                            // 2) 同类型技能覆盖（避免新增节点）
                            if (idx < 0) {
                                const lockedType = String(lockedSkill?.类型 || '').trim();
                                if (lockedType) {
                                    idx = skills.findIndex((item, i) => {
                                        if (usedReplaceIndexes.has(i)) return false;
                                        return String(item?.类型 || '').trim() === lockedType;
                                    });
                                }
                            }

                            // 3) 仍未命中则覆盖该阶位任一未占用技能（保持节点数量不增长）
                            if (idx < 0) {
                                idx = skills.findIndex((_, i) => !usedReplaceIndexes.has(i));
                            }

                            if (idx >= 0) {
                                skills[idx] = lockedSkillClone;
                                usedReplaceIndexes.add(idx);
                            } else {
                                // 仅在目标阶位原本为空时新增（避免出现“越生成越多”）
                                skills.push(lockedSkillClone);
                            }
                        }
                    }
                    return mergedTree;
                };

                // 格式化时间显示
                const formatTime = (seconds) => {
                    const mins = Math.floor(seconds / 60);
                    const secs = seconds % 60;
                    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
                };

                // 跳转到技能树
                const goToSkillTree = () => {
                    currentStep.value = 3;
                    showSkillReadyBubble.value = false;
                };

                const PROMPT_TIER_KEY_MAP = {
                    '基础': 'Tier1',
                    '转职': 'Tier2',
                    '进阶': 'Tier3',
                    '必杀': 'Tier4',
                    '奥义': 'Tier5',
                    '觉醒一': '觉醒一',
                    '觉醒二': '觉醒二',
                    '觉醒三': '觉醒三',
                    'Tier1': 'Tier1',
                    'Tier2': 'Tier2',
                    'Tier3': 'Tier3',
                    'Tier4': 'Tier4',
                    'Tier5': 'Tier5',
                    '觉醒': '觉醒'
                };

                const buildLockedSkillsPromptPayload = (className) => {
                    if (!className) return null;
                    const classLocks = lockedSkillMap.value?.[className];
                    if (!classLocks || typeof classLocks !== 'object') return null;

                    const payload = {};
                    for (const [tierKey, lockedByName] of Object.entries(classLocks)) {
                        if (!lockedByName || typeof lockedByName !== 'object') continue;
                        const promptTierKey = PROMPT_TIER_KEY_MAP[tierKey] || tierKey;
                        const skills = Object.values(lockedByName)
                            .map(s => cloneJson(s))
                            .filter(s => s && s.名称);
                        if (skills.length === 0) continue;
                        // 同一阶级仅保留一组锁定技能，避免历史别名键导致重复附加
                        payload[promptTierKey] = skills;
                    }

                    return Object.keys(payload).length > 0 ? payload : null;
                };

                const extractTopLevelJsonObjects = (text) => {
                    const src = String(text || '');
                    const objects = [];
                    let depth = 0;
                    let start = -1;
                    let inString = false;
                    let escaped = false;

                    for (let i = 0; i < src.length; i++) {
                        const ch = src[i];

                        if (inString) {
                            if (escaped) escaped = false;
                            else if (ch === '\\') escaped = true;
                            else if (ch === '"') inString = false;
                            continue;
                        }

                        if (ch === '"') {
                            inString = true;
                            continue;
                        }
                        if (ch === '{') {
                            if (depth === 0) start = i;
                            depth++;
                            continue;
                        }
                        if (ch === '}' && depth > 0) {
                            depth--;
                            if (depth === 0 && start >= 0) {
                                objects.push(src.slice(start, i + 1));
                                start = -1;
                            }
                        }
                    }
                    return objects;
                };

                const stripJsonComments = (text) => {
                    const src = String(text || '');
                    let out = '';
                    let inString = false;
                    let escaped = false;
                    let lineComment = false;
                    let blockComment = false;

                    for (let i = 0; i < src.length; i++) {
                        const ch = src[i];
                        const next = src[i + 1];

                        if (lineComment) {
                            if (ch === '\n') {
                                lineComment = false;
                                out += ch;
                            }
                            continue;
                        }
                        if (blockComment) {
                            if (ch === '*' && next === '/') {
                                blockComment = false;
                                i++;
                            }
                            continue;
                        }
                        if (inString) {
                            out += ch;
                            if (escaped) escaped = false;
                            else if (ch === '\\') escaped = true;
                            else if (ch === '"') inString = false;
                            continue;
                        }

                        if (ch === '"') {
                            inString = true;
                            out += ch;
                            continue;
                        }
                        if (ch === '/' && next === '/') {
                            lineComment = true;
                            i++;
                            continue;
                        }
                        if (ch === '/' && next === '*') {
                            blockComment = true;
                            i++;
                            continue;
                        }
                        out += ch;
                    }

                    return out;
                };

                const parseJsonLenient = (text) => {
                    const raw = String(text || '').trim();
                    if (!raw) return null;

                    const variants = [];
                    variants.push(raw);
                    variants.push(stripJsonComments(raw).replace(/,\s*([}\]])/g, '$1'));

                    const firstBrace = raw.indexOf('{');
                    const lastBrace = raw.lastIndexOf('}');
                    if (firstBrace >= 0 && lastBrace > firstBrace) {
                        const sliced = raw.slice(firstBrace, lastBrace + 1);
                        variants.push(sliced);
                        variants.push(stripJsonComments(sliced).replace(/,\s*([}\]])/g, '$1'));
                    }

                    for (const v of variants) {
                        try {
                            return JSON.parse(v);
                        } catch (e) { }
                    }
                    return null;
                };

                const scoreSkillTreeCandidate = (obj) => {
                    if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return -9999;

                    let score = 0;
                    if (obj['职业名']) score += 20;
                    if (obj['职业描述']) score += 10;
                    if (obj['技能联动思路']) score += 8;

                    const tree = obj['技能树'];
                    if (!tree || typeof tree !== 'object' || Array.isArray(tree)) return score - 120;
                    score += 60;

                    let tierHit = 0;
                    let skillCount = 0;
                    for (const [k, v] of Object.entries(tree)) {
                        if (SKILL_TIER_KEY_MAP[k]) tierHit++;
                        if (Array.isArray(v)) skillCount += v.length;
                    }
                    score += tierHit * 4;
                    score += Math.min(40, skillCount);

                    return score;
                };

                const pickBestSkillTreeJson = (text) => {
                    const src = String(text || '');
                    const candidates = [];

                    // 1) 优先收集所有 fenced code block（json/非json 都尝试）
                    const codeBlockRegex = /```(?:json|JSON)?\s*([\s\S]*?)```/g;
                    let m;
                    while ((m = codeBlockRegex.exec(src)) !== null) {
                        const payload = String(m[1] || '').trim();
                        if (payload) candidates.push({ source: 'codeblock', payload });
                    }

                    // 2) 再收集文本中的顶层 { ... } 对象
                    for (const payload of extractTopLevelJsonObjects(src)) {
                        candidates.push({ source: 'brace', payload: String(payload || '').trim() });
                    }

                    let best = null;
                    for (let i = 0; i < candidates.length; i++) {
                        const candidate = candidates[i];
                        const parsed = parseJsonLenient(candidate.payload);
                        if (!parsed) continue;

                        const topKeys = Object.keys(parsed).slice(0, 8);
                        const score = scoreSkillTreeCandidate(parsed);
                        if (!best || score > best.score || (score === best.score && candidate.payload.length > best.raw.length)) {
                            best = {
                                score,
                                parsed,
                                raw: candidate.payload,
                                source: candidate.source,
                                topKeys
                            };
                        }
                    }

                    if (!best) {
                        throw new Error(`AI回复中未找到可解析的JSON对象（共扫描 ${candidates.length} 个候选）`);
                    }
                    console.log('[技能树生成] JSON候选解析结果:', {
                        source: best.source,
                        score: best.score,
                        topKeys: best.topKeys
                    });
                    return best.parsed;
                };

                // 技能生成提示词模板 (从 YAML 读取)
                const SKILL_GEN_PROMPT_TEMPLATE = `# RPG 技能树生成规范

## 任务目标
为指定职业生成完整技能树。输出必须为合法 JSON，不得附加任何 JSON 外的说明。

## 术语与单位约定
- 正文用“阶位”指 Tier；JSON 键名固定为 Tier1、Tier2、Tier3、Tier4、Tier5 和 觉醒。
- 距离、位移、范围统一用“码”，不用网格计量。
- 状态、地形、标记等专有机制统一用 [方括号] 表示。
- 一切额外伤害收益统一写作“最终伤害+X%”；禁止“附加 X 点固定伤害”“xdy 固定伤害”“造成 X 倍伤害”“基础倍率提升到 X 倍”等口径。
- 特殊效果写成简洁干净的 TRPG 规则句，只写可结算内容，避免小作文。必须尽量克制且简洁，避免任何夸大其词的夸张描述。

## 核心生成规则
- 全树禁止任何被动技能及效果；所有技能都必须填写 特殊效果。
- 特殊效果按该技能可升级的每一级逐级独立列出：key 为等级数字，value 为该等级完整效果文本。
- key 数量必须与该技能所属阶位的等级上限严格一致，不得缺级、跳级、省略。
- 逐级独立、逐级完整、逐级成长：每级必须完整覆盖上一级且不丢效果，禁止“同上”“仅写差异”；相邻等级不得同文或同效，每升一级至少变化 1 项可验证效果，只换措辞不算成长，不得出现连续平台期。
- 优先复用 DNF 原作技能名、机制、节奏与职业特色。
- 鬼泣的伤害型阵，以及其他“以持续伤害、阵体或召唤物为核心”的技能按“召唤”处理；纯增益、纯减益、纯控制且不直接造成伤害的阵按“特殊”处理。

## 数值与表述要求
- 整体数值符合 DNF + DND 5e 混合世界观，不得明显失衡。
- 涉及属性时仅用 DND 5e 六维：力量、敏捷、体质、智力、感知、魅力；禁止直接增减属性点或 HP 上限，统一改写为检定修正、豁免修正、AC 修正、抗性穿透、临时生命值或状态。
- 主动/召唤技能的基础伤害倍率由系统按阶位固定结算，绝对不写入 特殊效果；特殊效果不得重新定义基础倍率、追加一段“等同技能伤害”的伤害，也不得用“伤害翻倍/造成X倍伤害”变相覆盖系统倍率，只设计附加机制或条件收益。
- 最终伤害加成必须极度克制：如果需要，常规单条以 +5%~15% 为宜，+20%~25% 已属于显著高收益，+25%~40% 只允许出现在高阶技能、严格条件窗口或高成本爆发中；任何单条、单次结算的额外最终伤害加成硬上限为 +40%。Tier1/Tier2 低阶技能原则上不得超过 +15%，且禁止通过多段描述、叠层、标记引爆或多技能联动绕过上限。
- 同一攻击或同一技能结算时，来自技能树的多个最终伤害加成默认不叠加，取最高值；不要让整棵技能树到处散落最终伤害词条。额外收益必须依附命中、状态、地形、资源或连携条件，不无条件白送高额增伤；优先设计位移、控制、地形、标记、资源转换、范围变化、豁免窗口与队友联动。
- 治疗/护盾参考装备数值口径：低阶单体通常为生命值上限的 5%~10%，中阶 10%~15%，高阶 15%~25%，顶阶或觉醒 25%~40%。群体、范围、可频繁使用、兼具净化/减伤/复活时必须进一步降低比例或增加资源、专注、长休次数等代价；禁止用“恢复大量生命”“获得巨额护盾”等模糊表述。
- 禁止在 特殊效果 中设计冷却缩减、刷新、重置类成长；冷却由阶位决定。
- 模糊效果必须转成可结算口径：“更快/更稳/更容易”改为明确的某项检定+N、先攻+N或下一次检定优势；概率触发改为 d20≥明确阈值；敌我行为倾向改为持续N轮的[标记]/[无法移动]/下一次检定-N；抗性写明伤害类型与减免比例或对应豁免优势。范围、位移、持续、次数和判定加值必须写实数，禁止“较大范围”“短距离”“大幅提升”“少量伤害”。
- 特殊效果必须简洁：每级优先 1~2 句，最多 3 句；围绕一个核心效果，至多附带一个直接服务于核心循环的联动。禁止把背景故事、演出描写、设计解释、五六个并列收益或例外条款塞进效果文本，禁止“小作文式技能”。

## 联动设计要求
- 技能之间尽可能围绕该职业核心机制形成自洽的玩法循环。
- 循环范式按职业特色任选其一或自由组合，不强求统一模板。常见范式：
  - 爆发连段：铺垫/控制 -> 标记/状态 -> 引爆/处决。
  - 叠层增幅：只在确实契合职业主题时使用，积攒单一核心资源或层数 -> 消耗/达到阈值后触发强化或质变；不需要叠层的职业不要强行叠层。
  - 资源循环：消耗与回收形成可持续输出节奏。
  - 召唤协同：召唤物与本体技能互相强化。
  - 姿态/形态切换：不同形态各有定位并相互衔接。
  - 异常传播：施加异常 -> 扩散、连锁或转化收益。
- 高阶技能应复用或延展低阶已建立的核心机制，而非孤立堆砌；不强制每个阶位都做跨阶联动。
- 严禁滥用叠层：整套职业原则上只保留 0~1 种核心层数/资源，层数上限通常 3~5；必须写明获取、上限、持续/衰减、消耗方式。同一动作或同一技能一次至多获得1层，多段攻击不得按命中段数疯狂叠层。每层收益必须微小，叠满后的总收益仍受最终伤害、检定与控制上限约束；禁止层中套层、多个同义资源并存、每个技能各造一种标记、无限叠加或叠层后再次乘算。
- 层数成长优先改善获取条件、持续时间、消费方式或玩法分支，不要每一级都简单增加层数上限、每层增伤和触发次数。若叠层删掉后技能仍能成立，应优先采用更直接简洁的状态或资源设计。
- 主动技能的特殊效果优先体现地形互动、控制、位移、状态传播、命中条件、资源转换与窗口制造，避免只写纯自我增益。

## 技能数量与阶位要求
- Tier1：3 个，15 级以下基础技。
- Tier2：3 个，15 到 30 级转职技。
- Tier3：3 个，30 到 45 级进阶技。
- Tier4：3 个，45 到 75 级必杀技。
- Tier5：3 个，75 到 95 级奥义技。
- 觉醒：3 个，分别为一觉、二觉、三觉。
- 总计 18 个技能。

### 特殊效果等级上限
- Tier1、Tier2 普通技能：1 到 15。
- Tier2 职业特殊：1。
- Tier3：1 到 10。
- Tier4：1 到 7。
- Tier5：1 到 5。
- 觉醒技能必须标注 阶位：觉醒一为 1 到 3，觉醒二为 1 到 2，觉醒三为 1。

### 职业特殊技能规则
- Tier2 必须包含 1 个职业特殊技能，承载该职业最核心、最不可替代的机制；不可升级，特殊效果只写 1 级。
- 仅当该职业确实不存在合适的“不可升级核心机制”时，才允许不设置，并以普通技能补足数量。
- 整棵技能树中职业特殊技能最多 1 个。

### 技能配比
- 每个阶位至少 2 个输出向技能。
- 常规“特殊”技能总数不超过 3 个。
- “特殊”技能强度必须与所属阶位匹配，参考 DNF 原作同等级技能的定位与影响力。

## 技能类型说明
技能类型固定为：主动、召唤、特殊、职业特殊。各类型的等级要求统一遵循上文“核心生成规则”，不再重复。

### 主动
- 定义：造成伤害的攻击技能，可附带控制、位移、标记、异常、连携或地形机制。
- 必填字段：名称、类型、描述、特殊效果。
- 设计要求：额外机制尽量建立在命中、状态、地形、资源或时机条件之上。

### 召唤
- 定义：以召唤战斗单位、分身、阵体、装置或协同实体为核心的技能。
- 必填字段：名称、类型、描述、召唤物名称、特殊效果。
- 设计要求：重心在召唤物本体与联动机制。

### 特殊
- 定义：以变身、增益、削弱、控制、姿态、领域、资源转换等非直接伤害效果为核心的技能。
- 必填字段：名称、类型、描述、特殊效果。
- 设计要求：不得写成纯被动常驻；必须明确持续时间、触发条件、影响范围或资源代价。

### 职业特殊
- 定义：仅用于 Tier2 的职业核心机制技能，例如职业变身、资源开启、核心召唤或标志性战斗框架。
- 必填字段：名称、类型、描述、特殊效果。
- 限制：不可升级，只写 1 级；整棵技能树最多 1 个。

## 输出要求
- 结果必须是合法 JSON，不输出 Markdown 解释、前言、校验说明或任何 JSON 外文本。
- 顶层必须包含：职业名、职业描述、技能联动思路、技能树。
- 技能联动思路用自然语言说明该职业的核心循环如何运转，条数随职业机制而定，不强制固定模板。
- 技能树阶位键固定为 Tier1、Tier2、Tier3、Tier4、Tier5、觉醒；每个技能对象按上文对应类型的字段要求完整展开。
- 觉醒下的 3 个技能必须显式写出 阶位，分别对应 觉醒一、觉醒二、觉醒三 的等级上限。
- 技能描述可点明联动对象，但写法须自然，不能像注释或开发文档。
- 输出前自检：等级 key 写满且不缺级、跳级、截断；相邻等级不同文同效；觉醒阶位与等级上限一致。

## 基础规则参考
1. 遵循 DND 5e 六维属性与 d20 检定。
2. 属性强化转化为元素附伤、抗性穿透、豁免 DC 修正或同量级机制收益。
3. 数值与阶位保持平衡。
4. 暴击率以暴击阈值体现：每 10% 暴击率写明暴击阈值额外减 1，或转化为 DND 描述，如“重击范围扩大（如 19-20）”“命中检定优势”。

