                const buildPlaceholderSpecialEffectMap = (skill, tierKey, fallbackAwakeningStage = null) => {
                    const type = String(skill?.类型 || '主动').trim();
                    if (type === '职业特殊') return { '1': '待补完' };

                    let configKey = SKILL_TIER_KEY_MAP[tierKey] || tierKey || '基础';
                    if (configKey === '觉醒' || tierKey === '觉醒') {
                        configKey = AWAKENING_STAGE_MAP[String(skill?.阶位 || '').trim()] || fallbackAwakeningStage || '觉醒三';
                    }

                    if (String(configKey).startsWith('觉醒')) {
                        skill.阶位 = configKey;
                    }

                    const maxLevel = Math.max(1, parseInt(SKILL_TIER_CONFIG[configKey]?.等级上限, 10) || 1);
                    const placeholder = {};
                    for (let lv = 1; lv <= maxLevel; lv++) {
                        placeholder[String(lv)] = '待补完';
                    }
                    return placeholder;
                };

                const prepareSkillTreeSkeletonForStageTwo = (parsed) => {
                    const skeleton = cloneJson(parsed) || {};
                    const rawTree = skeleton?.['技能树'];
                    if (!rawTree || typeof rawTree !== 'object') {
                        throw new Error("第一步生成结果不符合规范: 缺少'技能树'字段");
                    }

                    for (const [tierKey, skills] of Object.entries(rawTree)) {
                        if (!Array.isArray(skills)) continue;

                        if (tierKey === '觉醒') {
                            skills.forEach((skill, idx) => {
                                if (!skill || typeof skill !== 'object') return;
                                const fallbackStage = ['觉醒一', '觉醒二', '觉醒三'][idx] || '觉醒三';
                                skill.特殊效果 = buildPlaceholderSpecialEffectMap(skill, tierKey, fallbackStage);
                            });
                            continue;
                        }

                        skills.forEach((skill) => {
                            if (!skill || typeof skill !== 'object') return;
                            skill.特殊效果 = buildPlaceholderSpecialEffectMap(skill, tierKey);
                        });
                    }

                    return skeleton;
                };

                const buildSkillTreeEffectFillPrompt = (skeleton) => {
