                const pickBestSkillRevisionJson = (text) => {
                    const src = String(text || '');
                    const candidates = [];
                    const codeBlockRegex = /```(?:json|JSON)?\s*([\s\S]*?)```/g;
                    let match;
                    while ((match = codeBlockRegex.exec(src)) !== null) {
                        const payload = String(match[1] || '').trim();
                        if (payload) candidates.push(payload);
                    }
                    for (const payload of extractTopLevelJsonObjects(src)) candidates.push(String(payload || '').trim());
                    let best = null;
                    for (const payload of candidates) {
                        const parsed = parseJsonLenient(payload);
                        if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) continue;
                        const changes = Array.isArray(parsed['技能修改']) ? parsed['技能修改'] : null;
                        if (!changes) continue;
                        const score = changes.length * 10 + (Array.isArray(parsed['修改摘要']) ? 5 : 0);
                        if (!best || score > best.score) best = { parsed, score };
                    }
                    if (!best) throw new Error('AI回复中未找到合法的技能局部修订包');
                    return best.parsed;
                };

                const applySkillRevisionPatch = (sourceTree, revisionPayload) => {
                    const nextTree = cloneJson(sourceTree) || {};
                    const changes = Array.isArray(revisionPayload?.['技能修改']) ? revisionPayload['技能修改'].slice(0, 10) : [];
                    let appliedCount = 0;
                    const skipped = [];
                    for (const change of changes) {
                        const rawTier = String(change?.['原阶位'] || '').trim();
                        const tierKey = SKILL_TIER_KEY_MAP[rawTier] || rawTier;
                        const originalName = String(change?.['原技能名'] || '').trim();
                        const replacement = cloneJson(change?.['修改后技能']);
                        const tierSkills = nextTree?.[tierKey];
                        if (!tierKey || !originalName || !replacement || typeof replacement !== 'object' || !Array.isArray(tierSkills)) {
                            skipped.push(`${rawTier || '未知阶位'}/${originalName || '未知技能'}：定位或对象无效`); continue;
                        }
                        const index = tierSkills.findIndex(skill => String(skill?.名称 || '').trim() === originalName);
                        if (index < 0) { skipped.push(`${tierKey}/${originalName}：未找到`); continue; }
                        if (isSkillLocked(tierKey, originalName, character.class)) { skipped.push(`${tierKey}/${originalName}：已锁定`); continue; }
                        tierSkills[index] = {
                            ...cloneJson(tierSkills[index]),
                            ...replacement,
                            阶位: tierKey
                        };
                        appliedCount++;
                    }
                    if (appliedCount === 0) throw new Error(`修订包没有可应用的技能修改${skipped.length ? `（${skipped.join('；')}）` : ''}`);
                    if (skipped.length) console.warn('[技能树局部修订] 部分修改已跳过:', skipped);
                    return { tree: nextTree, appliedCount, skipped };
                };

                const normalizeGeneratedSkillTreePayload = (parsed) => {
                    const normalizedPayload = cloneJson(parsed) || {};
                    if (!normalizedPayload['技能树']) throw new Error("JSON结构不符合规范: 缺少'技能树'字段");

                    const VALID_TIER_KEYS = Object.keys(SKILL_TIER_CONFIG);
                    const rawTree = normalizedPayload['技能树'];
                    const normalizedTree = {};

                    for (const [key, skills] of Object.entries(rawTree)) {
                        if (key === '觉醒' && Array.isArray(skills)) {
                            const awakeningBuckets = { '觉醒一': [], '觉醒二': [], '觉醒三': [] };
                            skills.forEach((skill, idx) => {
                                const stage = skill.阶位 && AWAKENING_STAGE_MAP[skill.阶位];
                                const targetStage = stage || (['觉醒一', '觉醒二', '觉醒三'][idx] || '觉醒三');
                                skill.阶位 = targetStage;
                                const tierCfg = SKILL_TIER_CONFIG[targetStage] || SKILL_TIER_CONFIG['基础'];
                                skill.特殊效果 = normalizeSkillSpecialEffect(skill, tierCfg, true);
                                awakeningBuckets[targetStage].push(skill);
                            });
                            for (const [stage, bucket] of Object.entries(awakeningBuckets)) {
                                if (bucket.length > 0) {
                                    normalizedTree[stage] = bucket;
                                }
                            }
                            continue;
                        }

                        const normalizedKey = SKILL_TIER_KEY_MAP[key];
                        if (!normalizedKey) {
                            console.warn(`[技能树生成] 未知阶位 "${key}"，已按「基础」处理`);
                            if (Array.isArray(skills)) {
                                if (!normalizedTree['基础']) normalizedTree['基础'] = [];
                                for (const skill of skills) {
                                    skill.阶位 = '基础';
                                    const tierCfg = SKILL_TIER_CONFIG['基础'];
                                    skill.特殊效果 = normalizeSkillSpecialEffect(skill, tierCfg, true);
                                    normalizedTree['基础'].push(skill);
                                }
                            }
                            continue;
                        }

                        if (Array.isArray(skills)) {
                            for (const skill of skills) {
                                const mappedSkillTier = SKILL_TIER_KEY_MAP[skill.阶位];
                                const normalizedSkillTier = mappedSkillTier
                                    || (VALID_TIER_KEYS.includes(skill.阶位) ? skill.阶位 : normalizedKey);
                                skill.阶位 = normalizedSkillTier;
                                const tierCfg = SKILL_TIER_CONFIG[normalizedSkillTier] || SKILL_TIER_CONFIG[normalizedKey] || SKILL_TIER_CONFIG['基础'];
                                skill.特殊效果 = normalizeSkillSpecialEffect(skill, tierCfg, true);
                            }
                        }
                        normalizedTree[normalizedKey] = skills;
                    }

                    normalizedPayload['技能树'] = normalizedTree;
                    return normalizedPayload;
                };

                // 核心函数：生成技能树（支持两种模式切换）
                const generateSkillTree = async (options = null) => {
                    if (!character.class) return;

                    const revisionRequest = String(options?.revisionRequest || '').trim();
                    const revisionSourceTree = cloneJson(options?.sourceTree || currentClassSkillTree.value);
                    const isRevision = !!(revisionRequest && revisionSourceTree);
                    const previousSkillTree = cloneJson(skillTreeData.value);
                    const previousSkillTreeForClass = skillTreeForClass.value;
                    const previousClassWarnings = cloneJson(skillSoftWarningMap.value?.[character.class] || null);
                    const hadPreviousCurrentClassTree = !!(previousSkillTree && previousSkillTreeForClass === character.class);

                    isGeneratingSkills.value = true;
                    skillGenerationError.value = '';
                    skillGenerationPhaseText.value = isRevision ? '按要求修改：生成技能修改补丁' : (useSegmentedSkillGeneration.value ? '阶段 1/2：生成技能树骨架' : '单步生成：生成完整技能树');
                    showSkillReadyBubble.value = false;

                    // 启动计时器
                    generationTimer.value = 0;
                    timerInterval = setInterval(() => {
                        generationTimer.value++;
                    }, 1000);

                    try {
                        const targetWindow = getSkillGenerationTargetWindow();
                        let parsed = null;

                        if (isRevision) {
                            const revisionPrompt = buildSkillTreeRevisionPrompt(revisionSourceTree, revisionRequest);
                            const revisionResultText = await requestSkillGenerationFromApi(targetWindow, revisionPrompt);
                            if (!revisionResultText) throw new Error("局部修订超时或无响应");
                            const revisionPayload = pickBestSkillRevisionJson(revisionResultText);
                            const patchResult = applySkillRevisionPatch(revisionSourceTree, revisionPayload);
                            parsed = { 职业名: character.class, 技能树: patchResult.tree };
                            console.log(`[技能树局部修订] 已应用 ${patchResult.appliedCount} 项修改`);
                        } else if (useSegmentedSkillGeneration.value) {
                            const skeletonPrompt = buildSkillTreeSkeletonPrompt();
                            const skeletonResultText = await requestSkillGenerationFromApi(targetWindow, skeletonPrompt);
                            if (!skeletonResultText) throw new Error("第一步生成超时或无响应");

                            const skeletonParsed = pickBestSkillTreeJson(skeletonResultText);
                            const preparedSkeleton = prepareSkillTreeSkeletonForStageTwo(skeletonParsed);

                            skillGenerationPhaseText.value = '阶段 2/2：补全每级技能效果';
                            const fillPrompt = buildSkillTreeEffectFillPrompt(preparedSkeleton);
                            const finalResultText = await requestSkillGenerationFromApi(targetWindow, fillPrompt);
                            if (!finalResultText) throw new Error("第二步生成超时或无响应");

                            parsed = pickBestSkillTreeJson(finalResultText);
                        } else {
                            const prompt = buildFullSkillTreePrompt();
                            const resultText = await requestSkillGenerationFromApi(targetWindow, prompt);
                            if (!resultText) throw new Error("生成超时或无响应");
                            parsed = pickBestSkillTreeJson(resultText);
                        }

                        const normalizedPayload = normalizeGeneratedSkillTreePayload(parsed);
                        const mergedTree = applyLockedSkillsToTree(character.class, normalizedPayload['技能树']);
                        const warningTree = buildSkillSoftWarningsForTree(mergedTree);
                        setClassSkillSoftWarnings(character.class, warningTree);

                        // 成功!
                        skillTreeData.value = mergedTree;
                        skillTreeForClass.value = character.class; // 记录技能树归属的职业

                        // 如果用户不在步骤3，显示气泡提醒
                        if (currentStep.value !== 3) {
                            showSkillReadyBubble.value = true;
                        }

                    } catch (e) {
                        console.error("Skill Generation Error:", e);
                        skillTreeData.value = previousSkillTree;
                        skillTreeForClass.value = previousSkillTreeForClass;
                        setClassSkillSoftWarnings(character.class, previousClassWarnings || {});

                        const errorMsg = e?.message || "未知错误";
                        skillGenerationError.value = hadPreviousCurrentClassTree
                            ? `${errorMsg}（已回退到上一次成功的技能树）`
                            : errorMsg;
                    } finally {
                        // 停止计时器
                        if (timerInterval) {
                            clearInterval(timerInterval);
                            timerInterval = null;
                        }
                        isGeneratingSkills.value = false;
                        skillGenerationPhaseText.value = '';
                    }
                };

                const reviseCurrentSkillTree = async () => {
                    const request = String(skillFlavorInput.value || '').trim();
                    if (!currentClassSkillTree.value) { skillGenerationError.value = '当前职业还没有可优化的技能树。'; return; }
                    if (!request) { skillGenerationError.value = '请先填写要修改的具体意见。'; return; }
                    await generateSkillTree({ revisionRequest: request, sourceTree: cloneJson(currentClassSkillTree.value) });
                };

                // ==================== 构筑共鸣评议 ====================
                const BUILD_REVIEW_RUBRIC_VERSION = 11;
                const BUILD_REVIEW_DIMENSIONS = [
                    { name: '规则与数值', max: 25 },
                    { name: '边界与反制', max: 15 },
                    { name: '玩法与联动', max: 20 },
                    { name: '叙事与扮演', max: 20 },
                    { name: '成长与定位', max: 20 }
                ];

                const buildReviewPayload = computed(() => ({
                    角色: {
                        姓名: character.name || '未命名',
                        系统等级: characterLevel.value,
                        DND对标等级: Number((characterLevel.value / 4).toFixed(2)),
                        世界观: currentWorldviewLabel.value,
                        六维基础值: cloneJson(character.attributes),
                        背景: character.backstory || ''
                    },
                    种族与出身: {
                        当前种族: displayRaceName.value,
                        预设种族数据: character.race === '__custom__' ? null : cloneJson(currentRace.value),
                        自定义种族: customRace.enabled ? cloneJson(customRace) : null,
                        当前出身: summaryIdentityLabel.value,
                        出身数据: character.identity === '__custom__' ? cloneJson(customIdentity) : cloneJson(currentIdentityObj.value)
                    },
                    职业: {
                        名称: displayClassName.value,
                        基础职业: selectedBaseClass.value,
                        自定义职业名: customClassName.value,
                        战斗定位: customClassCombatStyle.value,
                        武器: customClassWeapon.value,
                        风格说明: customClassStyle.value,
                        玩家补充: skillFlavorInput.value
                    },
                    特质与专长: {
                        预设特质: cloneJson(character.selectedTraits),
                        自定义特质: cloneJson(customTraits),
                        自定义专长: cloneJson(customExpertise)
                    },
                    技能树说明: '这是从基础到100级的完整未来成长表，不代表当前等级已经掌握全部技能',
                    技能阶位基准: {
                        Tier1基础: '系统Lv.1起 / DND约0.25级起 / 特殊效果最高15级',
                        Tier2转职: '系统Lv.15起 / DND约3.75级起 / 特殊效果最高15级',
                        Tier3进阶: '系统Lv.30起 / DND约7.5级起 / 特殊效果最高10级',
                        Tier4必杀: '系统Lv.45起 / DND约11.25级起 / 特殊效果最高7级',
                        觉醒一: '系统Lv.50起 / DND约12.5级起 / 最高3级',
                        Tier5奥义: '系统Lv.75起 / DND约18.75级起 / 特殊效果最高5级',
                        觉醒二: '系统Lv.85起 / DND约21.25级起 / 最高2级',
                        觉醒三: '系统Lv.100 / DND25级 / 最高1级'
                    },
                    技能树: cloneJson(currentClassSkillTree.value)
                }));

                const buildReviewFingerprint = computed(() => JSON.stringify({
                    rubricVersion: BUILD_REVIEW_RUBRIC_VERSION,
                    level: characterLevel.value,
                    worldview: selectedWorldview.value,
                    race: character.race,
                    customRace: customRace.enabled ? cloneJson(customRace) : null,
                    identity: character.identity,
                    customIdentity: character.identity === '__custom__' ? cloneJson(customIdentity) : null,
                    className: displayClassName.value,
                    classSettings: [selectedBaseClass.value, customClassName.value, customClassCombatStyle.value, customClassWeapon.value, customClassStyle.value, skillFlavorInput.value],
                    traits: cloneJson(character.selectedTraits),
                    customTraits: cloneJson(customTraits),
                    customExpertise: cloneJson(customExpertise),
                    skillTree: cloneJson(currentClassSkillTree.value)
                }));

                // 奖励一旦达标领取便保持生效；构筑变化只会让评议结果过期，不会回收已发放点数。
                const buildReviewRewardActive = computed(() =>
                    !isPresetChar.value
                    && buildReviewBonusRP.value === 10
                    && buildReviewBonusAttributePoints.value === 2
                );

                const buildReviewDimensionList = computed(() => BUILD_REVIEW_DIMENSIONS.map(item => {
                    const source = buildReviewResult.value?.维度评分?.[item.name] || {};
                    const score = Math.max(0, Math.min(item.max, Number(source.得分) || 0));
                    return {
                        name: item.name,
                        max: item.max,
                        score,
                        percent: Math.round(score / item.max * 100),
                        note: String(source.说明 || '暂无详细说明').replace(/\s+/g, ' ').slice(0, 70)
                    };
                }));

                watch(buildReviewFingerprint, (nextFingerprint) => {
                    if (!buildReviewReviewedFingerprint.value) return;
                    // 保留已经获得的奖励，只根据当前构筑是否与评议版本一致更新过期提示。
                    buildReviewStale.value = nextFingerprint !== buildReviewReviewedFingerprint.value;
                });

                const BUILD_REVIEW_RULES = `你是跑团角色构筑的友善同行评议者。评议是可选润色，不是资格审判；禁止嘲讽、羞辱或使用“垃圾、作弊、驳回、禁止游玩”等措辞。

基础分100：规则与数值25、边界与反制15、玩法与联动20、叙事与扮演20、成长与定位20。最终总分=五项基础分之和+小作文与冗余扣分+滥强与越级扣分；两项扣分均为0或负数，最终总分允许低于0。

## 五项评分必须相互独立
同一个问题只能在最直接对应的维度扣分一次，禁止跨维度重复处罚。各维度说明只能讨论本维度内容：
1. 规则与数值（25）：只评价描述能否结算、伤害/治疗/控制的数值表达是否违反系统硬规则。能力是不是“出现得太早”由成长与定位负责，本项不得因为习得阶位再次重复扣分。不要讨论叙事、职业幻想、团队贡献、玩法是否有趣。
2. 边界与反制（15）：只评价无限触发、无成本额外行动、无法定义作用范围或持续时间、跨场景永久压制等是否缺少必要边界。不要因为技能没有额外资源、反噬或每日次数而扣分，也不要把“绝对命中、完全免伤、无法抵抗”等字眼脱离阶位单独判死刑；100级三觉的神话权限可以合理包含绝对性效果。
3. 玩法与联动（20）：忽略具体数值强弱，专注想象玩家在实际跑团中使用这套BD会做什么、形成什么战术效果、面对哪些选择、如何接敌/位移/潜行/爆发/控制/脱离，以及技能之间是否产生清晰体验。这里只给玩法本身的基础分；小作文、技能冗余、重复机制和桌面负担改由独立负分项处理，不在本维度重复扣分。简单直接但体验明确的刺客、射手或战士同样可以高分，不强求资源循环和复杂联动。
4. 叙事与扮演（20）：只评价职业幻想、画面感、身份气质、性格表达、抉择空间、关系与剧情钩子、和世界观的结合。必须忽略强度、倍率、动作经济、资源代价、反制是否充分以及机制复杂度；绝不能用“机制失衡”“缺少代价”“强度过高”作为本维度扣分理由。
5. 成长与定位（20）：核心是评价“这个能力在这个习得等级出现是否合适”。主要扣分对象是前期技能提前拿到远超当前阶段的完整权限，以及成长倒退、阶位割裂或职业定位失焦。不得要求团队功能，也不得因高阶技能脱离常规凡人互动而扣分。越到后期，允许的能力尺度必须明显放宽；100级三觉本来就应接近神话或成神层面。

## 本体系等级与阶位基准
- 系统等级 ÷ 4 = 对标DND总等级。例：系统Lv.15≈DND3.75，Lv.30≈7.5，Lv.45≈11.25，Lv.50≈12.5，Lv.75≈18.75，Lv.85≈21.25，Lv.100=DND25。
- 这棵技能树是角色从低级到100级的完整未来成长表，不代表开局角色已经掌握全部技能。不得拿当前角色等级去否定未来阶位的技能，只检查技能是否放在正确阶位。
- Tier1基础：习得Lv.1，主要覆盖15级以下，普通技能特殊效果1~15级。
- Tier2转职：习得Lv.15，主要覆盖15~30级，普通技能特殊效果1~15级；职业特殊技能不可升级，仅1级。
- Tier3进阶：习得Lv.30，主要覆盖30~45级，特殊效果1~10级。
- Tier4必杀：习得Lv.45，主要覆盖45~75级，特殊效果1~7级。
- 觉醒一：习得Lv.50，对标DND12.5级，最高3级。
- Tier5奥义：习得Lv.75，主要覆盖75~95级，对标DND18.75级以上，特殊效果1~5级。
- 觉醒二：习得Lv.85，对标DND21.25级，已经超过DND5e常规20级上限，最高2级。
- 觉醒三：习得Lv.100，对标DND25级，属于神话、半神乃至成神层面的终局能力，最高1级。其影响战场、空间、命运、灵魂、领域或常规社会互动是合理的，不得仅因“脱离常规互动范畴”扣分。
- 阶位判断必须相对化：低阶需要克制清晰；75级以后允许史诗级影响；85级以后允许超越常规DND上限；100级终局技能应有神话尺度。只有明显超出所属阶位，而不是单纯“很强”，才算问题。

## “成长与定位”的具体扣分口径
- 该维度首先看能力的投放时机，而不是笼统评价强弱。相同效果放在不同阶位，结论可以完全不同。
- 负面示例：Tier1、系统Lv.1即可学习的技能直接获得“完全免受所有伤害，并把所有伤害完整反弹给来源”。这等于在成长起点提前获得终局防御权限，应在“成长与定位”明显扣分，因为能力出现得过早、后续成长空间被掏空。
- 中性示例：觉醒三、系统Lv.100、对标DND25级的终局技能获得“完全免伤并反弹所有伤害”。只要它符合职业最终形态和神话叙事，就可以接受，不应因强度尺度在“成长与定位”扣分；但“后期很强、释放爽快、像神仙”本身只是符合阶位，不构成加分理由。是否获得高分仍要看前期铺垫、阶段变化、玩法兑现和终局能力是否真正完成职业主题。
- 对上述Lv.100效果，其他维度也不得仅因为它“太强”或“脱离常规互动”重复扣分；只有文本无法结算、作用对象和场景范围完全无定义、产生无限递归反弹等独立问题，才由对应维度评价。
- 中低阶能力的扣分强度取决于它提前跨越了多少阶段；高阶技能则应看是否成功兑现此前铺垫，而不是要求它继续停留在普通冒险者尺度。

## 通用评议原则
- 代价是处理超规格效果的工具，不是每项能力的入场券。处于阶位上限内、占用正常动作且频率合理的能力，不得因为没有额外的气、耐力、充能、反噬或每日次数而扣分，也不要强行建议添加资源管理。
- 动作经济只检查无成本追加动作、无限反应、重复触发或一回合包办过多效果；普通主动技能默认占用一次常规动作。
- 团队贡献不是必修项。刺客、独行者、决斗家、自利型施法者等纯个人定位可以获得完整分数；不因缺少治疗、保护、增益或队友联动扣分。
- 简洁优先。能用清晰触发条件、正常动作或数值上限解决的问题，不要引入新资源、叠层、冷却链和额外例外条款。
- 机制简单但职业幻想鲜明、实际玩法明确，同样应获得高分。

## 规则与数值参考（只用于“规则与数值”维度）
1. 身份、能力和资源须符合对应技能阶位。六维只用力量、敏捷、体质、智力、感知、魅力。BUFF不得直接增加六维点数或HP上限，应改为具体检定、豁免、临时生命、护盾或减伤。
2. 对敌非纯伤害效果应写DC、属性豁免及成功结果；控制默认1轮，延长须允许重复豁免或有结束条件。模糊效果应转为可结算口径。
3. 技能基础伤害倍率由系统按阶位固定，技能树只设计特殊效果。特殊效果不得重写基础倍率、追加等同技能伤害，也不得使用“伤害翻倍/造成X倍伤害”覆盖系统倍率。
4. 最终伤害参考：+5%~15%常规，+20%~25%较高，+25%~40%用于高阶、严格条件或有限爆发；单条单次硬上限+40%，Tier1/Tier2原则上不超过+15%。同一结算的多个最终伤害加成默认取最高，不叠加。该限制只处罚数值表达，不得连带降低玩法、叙事或成长分。
5. 治疗/护盾参考：低阶单体5%~10%生命，中阶10%~15%，高阶15%~25%，顶阶/觉醒25%~40%。只有群体、频繁且兼具多重收益时，才需要降档或限制。
6. 不需要层数或资源的职业可以保持直接机制。确实使用核心层数时，原则上只保留0~1种，通常上限3~5层；禁止层中套层、多个同义资源、无限叠加和满层后再次乘算。

## 独立额外扣分制（仅作轻量纠偏）
额外扣分不是第二套基础评分，不能把五维中已经扣过的问题再次重罚。它只处理“严重到仅降低某一维得分仍不足以体现”的跨技能系统性问题；普通缺点、单个技能措辞不严谨、少量重复一律留在五维评分中，不启用额外扣分。两项合计最多扣28分。

### A. 小作文与冗余扣分（0至-8）
- 审查真正影响桌面运行的全局文本膨胀、功能重复和追踪负担，不按字数、技能数量或描述华丽程度机械判罚。
- 技能树中每级技能的效果描述必须完整独立写全，不得因此判定为"冗余"。因为系统在升级时只读取当级键名对应的效果文本，不会继承或引用之前等级的描述；如果某级只写"同上+xxx"或省略前置效果，运行时将丢失信息。逐级完整写出效果是系统要求，不是小作文。
- 0分：绝大多数正常构筑都应在此档；即使有数个偏长技能，只要职责不同、能稳定结算，也不额外扣分。
- -1~-2分：多处可明显精简，存在轻度重复，但尚不妨碍游玩。
- -3~-5分：重复状态、同义机制或查表负担贯穿多个阶位，已经明显拖慢结算。
- -6~-8分：复杂度成为整套构筑的主要运行障碍，大量技能堆叠重复收益、嵌套资源和例外规则。
- 风味文本、演出描述、严谨定义和逐级成长表本身不是“小作文”；只有它们制造实际追踪负担时才扣分。

### B. 滥强与越级扣分（0至-20）
- 只审查跨多个技能、足以让同阶遭遇或核心规则失效的系统性滥强。单个数值偏高、单个绝对措辞或高阶能力很强，应在”规则与数值/成长与定位”中处理，不再额外扣分。
- 快速开始【影魂绝刃】本身已经是强度偏高的参考样例。若构筑出现明显比快速开始还要滥强的设计——例如骰子结果直接取最大值、无条件必定暴击、无条件秒杀敌人、无脑自身无敌、动辄乘以数倍甚至数十倍的伤害倍率——应加大本项扣分力度，直接进入-20重扣档位。
- 0分：强度与阶位大体相符，或只有局部可修正问题。绝大多数构筑都应在此档。
- -1~-3分：有2至3个相互关联的效果略微绕过同阶边界，但不构成整套构筑核心。
- -4~-8分：多个阶位持续出现明显越级、硬上限叠加或缺少交互的强制成功，已经形成稳定优势链。
- -9~-14分：构筑核心依赖无条件强制成功、超额多段结算、近乎常驻无敌或系统性绕过反制，常规遭遇明显失真。
- -15~-20分：作弊式系统闭环，例如低级永久无敌并反弹全部伤害、无限行动/无限伤害、任意目标无豁免即死，且多个漏洞互相乘算。
- 阶位必须相对判断：100级三觉拥有神话级、绝对性或改变世界层面的效果，只要符合终局阶位就不属于滥强；“很强”“伤害高”“能斩杀”本身不是扣分理由。
- 不得因为没有额外资源代价、没有团队能力、机制简单直接，或技能使用“必定/完全/绝对”等词就自动扣分；必须结合习得阶位、适用对象和整套构筑判断。

## 【快速开始】参考标尺（只作校准，不享受豁免）
- 开局页内置【快速开始·影魂绝刃】是用于统一审查尺度的普通参考样例，不是保送模板；该扣的基础分和额外分照常扣，也不得为了证明严格而反向重罚。
- 这套模板的主要问题集中在后期部分数值与绝对性权限略显膨胀，应主要反映在“规则与数值”以及必要时的“成长与定位”中；它的职业主题、接敌游走、攻防转换和阶段成长仍然成立，不应把同一数值问题扩散到玩法、叙事等无关维度。
- 若构筑的问题与快速开始相近，即“整体可运行，只有后期数值略膨胀、少数效果偏强”，两项额外扣分合计通常应在0至-5之间；不能把每个高阶措辞逐条累加成十几或几十分。
- 只有当构筑比快速开始更系统性地绕过阶位、反制、行动或伤害上限时，才进入-6以下的额外扣分档；无限行动、永久无敌、无豁免即死等作弊闭环仍可按严重档处理。
- 对“玩法与联动”“叙事与扮演”等偏体验维度，达到本维度满分的75%~80%就是成熟、清晰且值得肯定的标准：20分维度通常为15~16分。17分以上必须有明显超出常规模板的独特玩法选择或叙事兑现，不能只因风格华丽就给高分。

## 各类构筑的公平评价
- 刺客重点看潜行、接敌、目标选择、爆发、脱离和身份气质是否形成鲜明体验，不要求保护队友。
- 辅助、坦克或团队指挥只有在构筑主动声明该定位时，才评价其团队能力是否兑现。
- 高阶技能自然延展职业主题即可，不必强行让所有技能互相消费资源。
- 开局页自带种族、出身和特质视作精心设计的标杆。学习其画面感、RP钩子、规则边界和长期玩法，不要求照抄，更不得把复杂范例当作所有构筑都必须具备的代价模板。

## 高分校准：整体压低高分发放
- 不要从满分开始寻找扣分项，应从“基本可用”档逐级加分。完整、华丽、技能数量多或后期演出宏大，只能证明内容充足，不能自动进入17分以上或总分90以上。
- 20分维度参考：9~10分基本可用，12~13分稳定成立，15~16分成熟优秀（满分的75%~80%，也是玩法与叙事的主要标准档），17分明显精修，18分罕见，19分具有标杆价值，20分原则上保留。
- 25分维度参考：11~13分基本可用，15~17分稳定成立，19~20分成熟优秀（约满分的75%~80%），21分明显精修，22~23分罕见，24分具有标杆价值，25分原则上保留。
- 15分维度参考：7~8分基本可用，9~10分稳定成立，11~12分成熟优秀（约满分的75%~80%），13分明显精修，14分具有标杆价值，15分原则上保留。
- “成熟优秀”不等于接近满分。17/20、21/25、13/15以上都必须指出超出常规成熟构筑的具体优势；如果说明只能写“定位清晰、很有风格、技能完整、玩起来很爽”，应停留在75%~80%档。
- 任一维度拿到19/20、24/25、14/15或更高，都必须说明其不可替代的标杆价值。满分只给几乎没有明显缺口、且能直接作为同类设计范本的极少数作品。
- 总分80~84代表各维度稳定且经过精修；85~89代表多项具体优势并且短板很少；90~94是罕见高完成度；95分以上只给几乎可以直接作为系统设计范本的作品。100分原则上不应出现。
- 高阶或三觉达到神话尺度只是符合等级预期，属于“不扣分”，不是成长、玩法或叙事的天然加分项。只有铺垫充分、阶段变化清楚、终局机制兑现核心主题并带来新的选择时，才可获得相应加分。

最终评分尺度（已经计入额外扣分）：60~69达到可用线；70~79成熟可玩；80~84稳定精修；85~89明显优秀；90~94罕见高完成度；95~99标杆级；100原则上保留。40~59通常存在明显越级、无限触发、叠层滥用、严重技能冗余或难以实际运行的复杂度；0~39暂难稳定结算。不得仅凭“没有额外代价”“缺少团队贡献”“联动不够复杂”“高阶能力脱离常规互动”把构筑压到60分以下，但也不得仅凭“风格好、很爽、后期像神仙”把构筑抬到90分以上。信息不足时注明“基于现有信息的暂评分”。建议优先简化文本、明确触发与上限、修正真正越界的数值；只有效果确实超出所属阶位时，才建议频率、资源、豁免或反制。`;

                const BUILD_REVIEW_SCHEMA = `只输出一个合法JSON对象，不使用Markdown代码块，不在JSON外写文字：
{
  "总分": 0,
  "结论": "8字以内友善结论",
  "一句话评价": "40字以内",
  "维度评分": {
    "规则与数值": {"得分": 0, "满分": 25, "说明": "50字以内，只写本维度结论"},
    "边界与反制": {"得分": 0, "满分": 15, "说明": "50字以内，只写本维度结论"},
    "玩法与联动": {"得分": 0, "满分": 20, "说明": "50字以内，只写本维度结论"},
    "叙事与扮演": {"得分": 0, "满分": 20, "说明": "50字以内，只写本维度结论"},
    "成长与定位": {"得分": 0, "满分": 20, "说明": "50字以内，只写本维度结论"}
  },
  "额外扣分": {
    "小作文与冗余": {"扣分": 0, "说明": "只能为0至-8；50字以内"},
    "滥强与越级": {"扣分": 0, "说明": "只能为0至-20；50字以内"}
  },
  "评语": "单段，180至260字；综合解释主要优点、核心问题、额外扣分和总分原因，不要重复逐项评分",
  "亮点": ["2至3条，每条25字以内"],
  "风险": ["最多3条，每条30字以内"],
  "建议方向": ["2至3条，每条60字以内"]
}`;

                const normalizeBuildReviewResult = (parsed) => {
                    const result = cloneJson(parsed) || {};
                    const dimensions = {};
                    let baseTotal = 0;
                    BUILD_REVIEW_DIMENSIONS.forEach(item => {
                        const source = result?.维度评分?.[item.name] || {};
                        const score = Math.max(0, Math.min(item.max, Number(source.得分) || 0));
                        dimensions[item.name] = { 得分: score, 满分: item.max, 说明: String(source.说明 || '暂无详细说明') };
                        baseTotal += score;
                    });
                    const normalizeDeduction = (source, min) => {
                        let value = Number(source?.扣分) || 0;
                        if (value > 0) value = -value;
                        return Math.max(min, Math.min(0, Math.round(value)));
                    };
                    const essaySource = result?.额外扣分?.小作文与冗余 || {};
                    const powerSource = result?.额外扣分?.滥强与越级 || {};
                    // 额外扣分只做轻量纠偏，所有构筑使用同一套上限。
                    const essayDeduction = normalizeDeduction(essaySource, -8);
                    const powerDeduction = normalizeDeduction(powerSource, -20);
                    const deductionTotal = essayDeduction + powerDeduction;
                    const finalTotal = Math.max(-100, Math.min(100, Math.round(baseTotal + deductionTotal)));
                    return {
                        总分: finalTotal,
                        基础分: Math.round(baseTotal),
                        额外扣分: {
                            小作文与冗余: { 扣分: essayDeduction, 说明: String(essaySource.说明 || '未发现明显小作文或冗余问题').replace(/\s+/g, ' ').slice(0, 70) },
                            滥强与越级: { 扣分: powerDeduction, 说明: String(powerSource.说明 || '未发现明显滥强或越级问题').replace(/\s+/g, ' ').slice(0, 70) },
                            总扣分: deductionTotal
                        },
                        结论: String(result.结论 || (finalTotal >= 60 ? '思路已经成形' : '值得继续打磨')).slice(0, 18),
                        一句话评价: String(result.一句话评价 || '这套构筑已经展现出自己的方向。').replace(/\s+/g, ' ').slice(0, 60),
                        维度评分: dimensions,
                        评语: String(result.评语 || '构筑拥有可继续发展的基础，可以根据建议补足规则边界。').replace(/\s+/g, ' ').slice(0, 360),
                        亮点: Array.isArray(result.亮点) ? result.亮点.slice(0, 3).map(item => String(item).replace(/\s+/g, ' ').slice(0, 35)) : ['角色概念已经形成'],
                        风险: Array.isArray(result.风险) ? result.风险.slice(0, 3).map(item => String(item).replace(/\s+/g, ' ').slice(0, 45)) : ['部分效果仍可补充结算口径'],
                        建议方向: Array.isArray(result.建议方向) ? result.建议方向.slice(0, 3).map(item => String(item).replace(/\s+/g, ' ').slice(0, 80)) : ['补充关键能力的动作、次数、恢复条件与豁免。']
                    };
                };

                const parseBuildReviewResult = (text) => {
                    let best = null;
                    for (const payload of extractTopLevelJsonObjects(String(text || ''))) {
                        try {
                            const parsed = JSON.parse(payload);
                            const score = ['总分', '维度评分', '评语', '建议方向'].reduce((sum, key) => sum + (parsed?.[key] != null ? 1 : 0), 0);
                            if (!best || score > best.score) best = { parsed, score };
                        } catch (error) { }
                    }
                    if (!best) throw new Error('AI回复中未找到可解析的评议JSON');
                    return normalizeBuildReviewResult(best.parsed);
                };

                const writeTextToClipboard = async (text) => {
                    if (navigator.clipboard?.writeText) {
                        try {
                            await navigator.clipboard.writeText(text);
                            return true;
                        } catch (error) { }
                    }
                    const textarea = document.createElement('textarea');
                    textarea.value = text;
                    textarea.setAttribute('readonly', '');
                    textarea.style.position = 'fixed';
                    textarea.style.opacity = '0';
                    document.body.appendChild(textarea);
                    textarea.select();
                    let copied = false;
                    try { copied = document.execCommand('copy'); } catch (error) { }
                    document.body.removeChild(textarea);
                    return copied;
                };

                const buildReviewSkillFeedbackText = () => {
                    if (!buildReviewResult.value) return '';
                    const result = buildReviewResult.value;
                    const dimensionLines = buildReviewDimensionList.value
                        .map(item => `- ${item.name}（${item.score}/${item.max}）：${item.note}`)
                        .join('\n');
                    const highlightLines = (result.亮点 || []).map(item => `- ${item}`).join('\n') || '- 保留当前职业核心风格';
                    const riskLines = (result.风险 || []).map(item => `- ${item}`).join('\n') || '- 暂无额外风险';
                    const adviceLines = (result.建议方向 || []).map((item, index) => `${index + 1}. ${item}`).join('\n') || '1. 根据评议收束技能描述。';
                    const penaltyLines = [
                        result.额外扣分?.小作文与冗余?.扣分 < 0 ? `- 小作文与冗余 ${result.额外扣分.小作文与冗余.扣分}：${result.额外扣分.小作文与冗余.说明}` : '',
                        result.额外扣分?.滥强与越级?.扣分 < 0 ? `- 滥强与越级 ${result.额外扣分.滥强与越级.扣分}：${result.额外扣分.滥强与越级.说明}` : ''
                    ].filter(Boolean).join('\n') || '- 无额外扣分';
                    return `请根据以下构筑评议局部优化现有技能树。保留职业定位、核心幻想、已有亮点以及所有未被意见点名的技能；只修改确实需要调整的技能，不要重新设计整棵技能树，不要强行添加资源循环、额外代价或团队功能。\n\n【角色与职业】\n${displayRaceName.value} / ${displayClassName.value} / Lv.${characterLevel.value}\n\n【总体评价】\n${result.一句话评价 || result.评语 || ''}\n\n【五维反馈】\n${dimensionLines}\n\n【额外扣分】\n${penaltyLines}\n\n【必须保留】\n${highlightLines}\n\n【需要处理】\n${riskLines}\n\n【修改方向】\n${adviceLines}`;
                };

                const copyBuildReviewSkillFeedback = async () => {
