                const skillEditDraft = ref(makeDefaultSkillEditDraft());

                const sortSkillEffectRows = (rows) => {
                    const list = Array.isArray(rows) ? rows.slice() : [];
                    return list.sort((a, b) => {
                        const aKey = String(a?.level ?? '').trim();
                        const bKey = String(b?.level ?? '').trim();
                        const aNum = Number(aKey);
                        const bNum = Number(bKey);
                        const bothNumeric = Number.isFinite(aNum) && Number.isFinite(bNum);
                        if (bothNumeric) return aNum - bNum;
                        return aKey.localeCompare(bKey, 'zh-Hans-CN');
                    });
                };

                const makeSkillEditDraftFromSkill = (skill) => {
