                    // 确保顶部不超出视口
                    if (desiredTop < 10) desiredTop = 10;
                    skillPopupPosition.value = { y: desiredTop };
                    isEditingSkill.value = false;
                    skillEditError.value = '';
                    skillEditDraft.value = makeDefaultSkillEditDraft();
                    selectedSkill.value = { ...skill, tierKey, 软警告: getSkillSoftWarnings(tierKey, skill?.名称) };
                };

                const startEditSkill = () => {
                    if (!selectedSkill.value) return;
                    skillEditError.value = '';
                    skillEditDraft.value = makeSkillEditDraftFromSkill(selectedSkill.value);
                    isEditingSkill.value = true;
                };

                const cancelEditSkill = () => {
                    isEditingSkill.value = false;
                    skillEditError.value = '';
                    skillEditDraft.value = makeDefaultSkillEditDraft();
                };

                const buildSkillEffectFromDraft = (draft) => {
                    if (!draft) return { '1': '无' };
                    const kind = draft.effectKind;
                    if (kind === 'none') return { '1': '无' };
                    if (kind === 'string') {
                        const txt = String(draft.effectText ?? '').trim();
                        return { '1': txt || '无' };
                    }
                    if (kind !== 'levels') return { '1': '无' };
                    const effectObj = {};
                    for (const row of (Array.isArray(draft.effectRows) ? draft.effectRows : [])) {
                        const level = String(row?.level ?? '').trim();
                        const text = String(row?.text ?? '').trim();
                        if (!level) continue;
                        effectObj[level] = text || '无';
                    }
                    const entries = Object.entries(effectObj);
                    if (!entries.length) return { '1': '无' };
                    entries.sort((a, b) => {
                        const aNum = Number(a[0]);
                        const bNum = Number(b[0]);
                        const bothNumeric = Number.isFinite(aNum) && Number.isFinite(bNum);
                        if (bothNumeric) return aNum - bNum;
                        return String(a[0]).localeCompare(String(b[0]), 'zh-Hans-CN');
                    });
                    return Object.fromEntries(entries);
                };

                const saveSkillEdit = () => {
                    if (!selectedSkill.value) return;
                    const tierKey = selectedSkill.value.tierKey;
                    const skillName = selectedSkill.value.名称;
                    const className = character.class;
                    const nextDesc = String(skillEditDraft.value?.description ?? '').trim();
                    if (!nextDesc) {
                        skillEditError.value = '技能描述不能为空';
                        return;
                    }
                    const tierSkills = skillTreeData.value?.[tierKey];
                    if (!Array.isArray(tierSkills)) {
                        skillEditError.value = '未找到该技能所属阶级';
                        return;
                    }

                    const targetIndex = tierSkills.findIndex(item => item?.名称 === skillName);
                    if (targetIndex < 0) {
                        skillEditError.value = '未找到要编辑的技能';
                        return;
                    }

                    const sourceSkill = tierSkills[targetIndex] || {};
                    const nextSkill = {
                        ...cloneJson(sourceSkill),
                        描述: nextDesc
                    };

                    const nextEffect = buildSkillEffectFromDraft(skillEditDraft.value);
                    nextSkill.特殊效果 = nextEffect;

                    const nextTierSkills = tierSkills.slice();
                    nextTierSkills[targetIndex] = nextSkill;
                    skillTreeData.value = {
                        ...(skillTreeData.value || {}),
                        [tierKey]: nextTierSkills
                    };

                    if (className) {
                        const nextLockedMap = cloneJson(lockedSkillMap.value) || {};
                        if (nextLockedMap[className]?.[tierKey]?.[skillName]) {
                            nextLockedMap[className][tierKey][skillName] = cloneJson(nextSkill);
                            lockedSkillMap.value = nextLockedMap;
                        }
                        setClassSkillSoftWarnings(className, buildSkillSoftWarningsForTree(skillTreeData.value));
                    }

                    selectedSkill.value = {
                        ...nextSkill,
                        tierKey,
                        软警告: getSkillSoftWarnings(tierKey, nextSkill?.名称)
                    };
                    isEditingSkill.value = false;
                    skillEditError.value = '';
                    skillEditDraft.value = makeDefaultSkillEditDraft();
                };

                // 角色详情弹窗
                const selectedTeammate = ref(null);
                const modalPosition = ref({ x: 0, y: 0 });

                // 羁绊列表分页（每页 6 个）
                const teammatePageSize = 6;
                const teammatePage = ref(0);
                const visibleTeammates = computed(() => (mockData.teammates || []).filter(mate => !isSolarisTeammateHidden(mate)));
                const teammatePageCount = computed(() =>
                    Math.max(1, Math.ceil(visibleTeammates.value.length / teammatePageSize))
                );
                watch(selectedWorldview, () => {
                    teammatePage.value = 0;
                    if(isSolarisTeammateHidden(selectedTeammate.value)) selectedTeammate.value = null;
                });
                const pagedTeammates = computed(() => {
                    const list = visibleTeammates.value;
                    const start = teammatePage.value * teammatePageSize;
                    return list.slice(start, start + teammatePageSize);
                });
                const teammatePagePrev = () => {
                    if (teammatePage.value > 0) teammatePage.value--;
                };
                const teammatePageNext = () => {
                    if (teammatePage.value < teammatePageCount.value - 1) teammatePage.value++;
                };
                watch(isBondSelectionDisabled, (disabled) => {
                    if (!disabled) return;
                    if (character.teammates.length > 0) {
                        character.teammates.splice(0, character.teammates.length);
                    }
                    if (customTeammate.enabled) {
                        customTeammate.enabled = false;
                    }
                    if (selectedTeammate.value) {
                        selectedTeammate.value = null;
                    }
                }, { immediate: true });
                const showTeammateDetail = (mate, event) => {
                    if(isSolarisTeammateHidden(mate)) return;
                    // 记录点击位置（相对于#app）
                    const appEl = document.getElementById('app');
                    const appRect = appEl.getBoundingClientRect();
                    const clickY = event.clientY - appRect.top + appEl.scrollTop;
                    // 估算弹窗高度，确保底部不超出视口
                    const viewportH = window.innerHeight;
                    const modalEstH = viewportH * 0.85; // max-height: 85vh
                    const clickInViewport = event.clientY;
                    // 弹窗顶部相对于视口 = clickInViewport - 200
                    // 弹窗底部相对于视口 = clickInViewport - 200 + modalEstH
                    // 如果底部超出视口，就往上提
                    let desiredTop = clickY - 200;
                    const bottomInViewport = clickInViewport - 200 + modalEstH;
                    if (bottomInViewport > viewportH - 20) {
                        // 需要上移的量
                        desiredTop -= (bottomInViewport - viewportH + 20);
                    }
                    modalPosition.value = {
                        x: appRect.width / 2,
                        y: Math.max(10, desiredTop)
                    };
                    selectedTeammate.value = mate;
                };

                watch([selectedWorldview,()=>character.race,()=>character.identity,selectedSolarisSpawn,solarisMapSelection],()=>{
 if(!isSolarisWorldview.value)return;
 if(!(character.race==='__custom__'&&customRace.enabled)&&!solarisRaces.some(x=>x.name===character.race))character.race=solarisRaces[0].name;
 selectedCustomLevel.value=Math.max(1,Math.min(SOLARIS_MAX_START_LEVEL,Math.floor(Number(selectedCustomLevel.value)||1)));
 if(isSolarisDrifter.value){character.identity='漂泊者';selectedSolarisSpawn.value='云陵谷';if(solarisMapSelection.value)solarisMapSelection.value=null;}
 else {selectedSolarisSpawn.value='今州城';if(solarisMapSelection.value)solarisMapSelection.value=null;if(character.identity==='漂泊者')character.identity='__custom__';}
 },{immediate:true});
                return {
